window.LEVEL_PACKS.b2={"units": {"1": {"n": 1, "title": "Crime and Justice", "ar": "الجريمة والعدالة — Modals of Deduction in the Past", "icon": "🕵️", "cover": "img/b2/u1.jpg", "intro": "اتكلم عن الجرايم والتحقيق والعدالة زي المحققين، واستخدم must have / might have / can't have عشان تستنتج إيه اللي حصل في الماضي.", "videos": [{"id": "b2v1", "title": "The Break-in Next Door", "ar": "سرقة الشقة اللي جنبنا — ليلى وعمر", "src": "video/b2/u1v1.mp4", "poster": "img/b2/u1v1.jpg", "sp": {"a": {"n": "Layla", "g": "f"}, "b": {"n": "Omar", "g": "m"}}, "lines": [["a", "Omar, did you hear? Someone broke into the flat next door last night!", "عمر، سمعت؟ حد اقتحم الشقة اللي جنبنا امبارح بالليل!"], ["b", "Seriously? I didn't hear a thing. The burglar must have been really quiet.", "بجد؟ مسمعتش أي حاجة. الحرامي أكيد كان هادي جدًا."], ["a", "The police said the front door wasn't damaged, so he can't have come in that way.", "البوليس قال إن الباب الرئيسي ماتكسرش، يبقى مستحيل يكون دخل من هناك."], ["b", "Then he must have climbed through the balcony window. It was open all evening.", "يبقى أكيد طلع من شباك البلكونة. كان مفتوح طول الليل."], ["a", "Maybe. Or he might have had a key. The neighbours said nothing else was touched — only the laptop and some jewellery.", "ممكن. أو يمكن كان معاه مفتاح. الجيران قالوا إن مفيش حاجة تانية اتلمست — بس اللابتوب وشوية دهب."], ["b", "So he must have known exactly what he was looking for. That's suspicious.", "يبقى أكيد كان عارف بالظبط هو بيدور على إيه. ده مريب."], ["a", "Exactly. The detective is looking into it now. They found a fingerprint on the window frame.", "بالظبط. المحقق بيحقق في الموضوع دلوقتي. لقوا بصمة على إطار الشباك."], ["b", "Good. I hope they catch him. Burglars often get away with it because there are no witnesses.", "كويس. أتمنى يقبضوا عليه. الحرامية كتير بيفلتوا لأن مفيش شهود."], ["a", "Well, there might have been a witness. The man across the street could have seen something from his window.", "ممكن يكون في شاهد. الراجل اللي في الناحية التانية من الشارع يمكن يكون شاف حاجة من شباكه."], ["b", "True. Let's make sure we always lock the balcony door from now on. I don't want to be next!", "صح. خلينا نتأكد إننا دايمًا نقفل باب البلكونة من هنا ورايح. مش عايز أبقى اللي عليه الدور!"]], "quiz": [{"q": "What happened next door?", "o": ["Someone broke into the flat.", "There was a fire.", "A new family moved in."], "a": 0}, {"q": "Why can't the burglar have come in through the front door?", "o": ["It wasn't damaged.", "It was painted.", "It was open."], "a": 0}, {"q": "What was stolen?", "o": ["a laptop and some jewellery", "a car", "only money"], "a": 0}, {"q": "What did the police find?", "o": ["a fingerprint on the window frame", "a knife", "a phone"], "a": 0}, {"q": "Who might have seen something?", "o": ["the man across the street", "Omar", "the detective"], "a": 0}], "fill": [[0, "broke into"], [1, "burglar"], [2, "damaged"], [3, "balcony"], [5, "suspicious"], [6, "detective"], [6, "fingerprint"], [7, "witnesses"], [8, "witness"]]}], "vocab": [{"t": "Crimes & criminals", "ar": "الجرايم والمجرمين", "items": [["🏠", "burglary", "There was a burglary in our building."], ["🦹", "burglar", "The burglar climbed through the window."], ["👜", "theft", "Phone theft is common in big cities."], ["💳", "fraud", "Online fraud is increasing every year."], ["🚗", "vandalism", "Breaking car windows is vandalism."], ["🤫", "suspect", "The police arrested a suspect."], ["👁️", "witness", "A witness saw the thief running away."], ["🙋", "victim", "The victim reported the crime to the police."]]}, {"t": "Investigation", "ar": "التحقيق", "items": [["🕵️", "detective", "The detective is looking into the case."], ["🔍", "evidence", "There isn't enough evidence."], ["☝️", "fingerprint", "They found a fingerprint on the glass."], ["📹", "CCTV", "The CCTV camera recorded everything."], ["🗂️", "clue", "The detective found an important clue."], ["🤔", "suspicious", "He was acting in a suspicious way."], ["🔗", "motive", "What was the motive for the crime?"], ["🧾", "alibi", "He had an alibi — he was at work."]]}, {"t": "Justice", "ar": "العدالة", "items": [["⚖️", "justice", "The victims want justice."], ["🏛️", "court", "The case will go to court next month."], ["👨‍⚖️", "judge", "The judge listened to both sides."], ["🧑‍💼", "lawyer", "You have the right to a lawyer."], ["✅", "guilty", "He was found guilty of fraud."], ["❎", "innocent", "She was innocent all along."], ["📜", "sentence", "He got a two-year sentence."], ["🔒", "prison", "He spent three years in prison."]]}], "talk": [{"title": "Let's Talk · Student A", "ar": "الطالب A", "list": [["What crimes are common in big cities?", "إيه الجرايم المنتشرة في المدن الكبيرة؟", "Phone theft and online fraud are very common."], ["Have you or someone you know ever been a victim of a crime?", "إنت أو حد تعرفه وقع ضحية جريمة قبل كده؟", "Yes, my cousin had his phone stolen on the bus."], ["Do you think CCTV cameras make streets safer?", "شايف إن كاميرات المراقبة بتخلي الشوارع أأمن؟", "Yes, criminals know they're being watched."], ["Why do some people commit crimes?", "ليه بعض الناس بيرتكبوا جرايم؟", "Poverty, greed, or bad friends."], ["Do you like crime documentaries or detective series? Why?", "بتحب أفلام الجريمة الوثائقية أو مسلسلات المحققين؟", "Yes, I love trying to guess who did it."]]}, {"title": "Let's Talk · Student B", "ar": "الطالب B", "list": [["Should prisons punish people or help them change?", "السجن لازم يعاقب ولا يساعد الناس تتغير؟", "Both, but helping them change is more important."], ["Is online crime more dangerous than street crime today?", "الجريمة الأونلاين أخطر من جريمة الشارع النهارده؟", "In some ways, yes, because anyone can be a victim."], ["What would you do if you witnessed a crime?", "هتعمل إيه لو شفت جريمة بتحصل؟", "I would call the police and stay safe."], ["Is it ever right to take the law into your own hands?", "ينفع أبدًا تاخد حقك بإيدك؟", "No, it's the police's job."], ["How can young people be kept away from crime?", "إزاي نبعد الشباب عن الجريمة؟", "Sports, education and good role models."]]}], "grammar": {"title": "Modals of Deduction in the Past", "ar": "الاستنتاج في الماضي — must have / might have / can't have", "blocks": [{"type": "intro", "en": "We use modal + have + past participle to make guesses or conclusions about the PAST, based on evidence — just like a detective!", "ar": "بنستخدم modal + have + التصريف التالت عشان نستنتج إيه اللي حصل في الماضي بناءً على أدلة — زي المحقق بالظبط!"}, {"type": "big", "items": [{"v": "must have + p.p.", "p": "I'm almost sure it happened ✔", "c": 1, "eg": ["The window is broken. He must have climbed in.", "She must have been tired after the trip.", "They must have left early — the lights are off."]}, {"v": "might / may / could have + p.p.", "p": "it's possible ❓", "c": 2, "eg": ["He might have had a key.", "She may have forgotten the meeting.", "The neighbour could have seen something."]}, {"v": "can't / couldn't have + p.p.", "p": "I'm sure it did NOT happen ✖", "c": 3, "eg": ["He can't have come through the door — it was locked.", "She couldn't have stolen it. She was in Cairo.", "You can't have finished already!"]}]}, {"type": "table", "title": "📏 How sure are you?", "head": ["Certainty", "Form", "Example"], "rows": [["~100% yes", "must have + p.p.", "He must have taken the laptop."], ["~50% maybe", "might / may / could have + p.p.", "He might have taken the laptop."], ["~100% no", "can't / couldn't have + p.p.", "He can't have taken the laptop."], ["continuous", "must have been + -ing", "He must have been waiting outside."]]}, {"type": "uses", "title": "🔍 Think like a detective", "ar": "فكّر زي المحقق", "items": [["🪟", "evidence → conclusion", "The window is open. → He must have escaped that way.", "دليل ← استنتاج"], ["🧾", "alibi", "He was at work. → He can't have done it.", "عنده حجة غياب"], ["❓", "possibility", "There are footprints. → Someone might have been here.", "احتمال"], ["😴", "continuous", "Nobody answered. → They must have been sleeping.", "كانوا في نص الحاجة"]]}, {"type": "tip", "en": "Don't use 'mustn't have' for deduction — use 'can't have'. Remember: modal + have + past participle (NOT past simple): He must have went ✖ → He must have gone ✔.", "ar": "متقولش mustn't have للاستنتاج، قول can't have. وبعد have لازم التصريف التالت: must have gone مش must have went."}]}, "exercises": [{"type": "mcq", "title": "Deduction in the Past — 10 MCQs", "ar": "اختار الصح", "speak": true, "items": [{"q": "The door was locked, so he ___ come in that way.", "o": ["can't have", "must have", "might", "should have"], "a": 0}, {"q": "Her eyes are red. She ___ crying.", "o": ["must have been", "can't have been", "must be have", "might be"], "a": 0}, {"q": "I'm not sure where my keys are. I ___ left them at work.", "o": ["might have", "must", "can't have", "have might"], "a": 0}, {"q": "He got 100% on the test. He ___ studied very hard.", "o": ["must have", "can't have", "might not", "mustn't have"], "a": 0}, {"q": "She ___ stolen the money. She was in Alexandria all week.", "o": ["couldn't have", "must have", "may have", "had"], "a": 0}, {"q": "The ground is wet. It ___ rained last night.", "o": ["must have", "can't have", "must", "should"], "a": 0}, {"q": "Nobody answered the phone. They ___ sleeping.", "o": ["might have been", "might be have", "must being", "can't sleeping"], "a": 0}, {"q": "The burglar knew the code. Someone ___ told him.", "o": ["must have", "can't have", "must", "would"], "a": 0}, {"q": "Which sentence is correct?", "o": ["He must have gone home.", "He must have went home.", "He must had gone home.", "He must gone home."], "a": 0}, {"q": "\"He can't have done it.\" means…", "o": ["I'm sure he didn't do it.", "He is not able to do it now.", "Maybe he did it.", "He did it."], "a": 0}]}, {"type": "mcq", "title": "How sure?", "ar": "متأكد قد إيه؟", "items": [{"q": "~100% YES = ___", "o": ["must have", "might have"], "a": 0}, {"q": "Maybe = ___", "o": ["might have", "can't have"], "a": 0}, {"q": "~100% NO = ___", "o": ["can't have", "must have"], "a": 0}, {"q": "The cake is gone! Someone ___ eaten it.", "o": ["must have", "can't have"], "a": 0}, {"q": "He's a vegetarian, so he ___ eaten the burger.", "o": ["can't have", "must have"], "a": 0}]}, {"type": "ord", "title": "Make sentences", "ar": "رتّب الكلمات", "items": [{"c": ["The burglar", "must have", "climbed", "through the window"], "a": [0, 1, 2, 3]}, {"c": ["She", "can't have", "stolen", "the money"], "a": [0, 1, 2, 3]}, {"c": ["Someone", "might have", "seen", "the thief"], "a": [0, 1, 2, 3]}, {"c": ["They", "must have been", "waiting", "outside"], "a": [0, 1, 2, 3]}]}], "reading": {"title": "Can Science Catch Every Criminal?", "ar": "هل العلم يقدر يمسك كل مجرم؟", "g": "m", "lines": [["A hundred years ago, detectives solved crimes mainly by asking questions and following suspects.", "من ميت سنة، المحققين كانوا بيحلّوا الجرايم بشكل أساسي بالأسئلة ومراقبة المشتبه فيهم."], ["Today, science plays a huge role in almost every investigation.", "النهارده، العلم ليه دور ضخم في كل تحقيق تقريبًا."], ["Forensic scientists can find tiny pieces of evidence that the human eye might miss: a single hair, a drop of blood, or a fingerprint on a glass.", "علماء الطب الشرعي يقدروا يلاقوا أدلة صغيرة جدًا ممكن العين تفوّتها: شعرة واحدة، أو نقطة دم، أو بصمة على كوباية."], ["DNA testing has changed criminal justice forever. Since the 1980s, it has helped to catch thousands of criminals who might otherwise have escaped.", "تحليل الـ DNA غيّر العدالة الجنائية للأبد. من الثمانينات، ساعد في القبض على آلاف المجرمين اللي كان ممكن يهربوا."], ["It has also freed many innocent people who had been sent to prison by mistake.", "وكمان طلّع ناس أبرياء كتير كانوا اتسجنوا بالغلط."], ["CCTV cameras are another powerful tool. In some cities, a person is filmed hundreds of times a day.", "كاميرات المراقبة أداة قوية تانية. في بعض المدن، الشخص بيتصور مئات المرات في اليوم."], ["When a crime happens, the police can often follow a suspect's route from camera to camera.", "لما جريمة بتحصل، البوليس كتير يقدر يتتبع طريق المشتبه فيه من كاميرا لكاميرا."], ["However, science is not perfect. Evidence can be damaged, samples can be mixed up, and experts can make mistakes.", "لكن العلم مش كامل. الأدلة ممكن تتلف، والعينات ممكن تتلخبط، والخبراء ممكن يغلطوا."], ["Criminals are also becoming smarter — many crimes now happen online, where there are no fingerprints at all.", "والمجرمين كمان بقوا أذكى — جرايم كتير دلوقتي بتحصل أونلاين، ومفيش فيها بصمات خالص."], ["So, can science catch every criminal? Not yet. But it has made it much harder to get away with a crime.", "طيب، العلم يقدر يمسك كل مجرم؟ لسه. بس خلّى الهروب بالجريمة أصعب بكتير."]], "keys": [["🧪", "forensic", "using science to investigate crimes"], ["🧬", "DNA", "the genetic code that makes every person unique"], ["🔍", "evidence", "facts or objects that prove something"], ["🙋", "innocent", "not guilty of a crime"], ["📹", "CCTV", "cameras that record public places"], ["🏃", "get away with", "do something wrong without being punished"]], "quiz": [{"q": "How did detectives solve crimes a hundred years ago?", "o": ["by asking questions and following suspects", "with DNA tests", "with CCTV"], "a": 0}, {"q": "What can forensic scientists find?", "o": ["tiny pieces of evidence like a hair or a fingerprint", "only big objects", "nothing useful"], "a": 0}, {"q": "How has DNA testing helped innocent people?", "o": ["It has freed people who were sent to prison by mistake.", "It has made them famous.", "It has given them jobs."], "a": 0}, {"q": "How can CCTV help the police?", "o": ["They can follow a suspect's route from camera to camera.", "They can stop all crimes.", "They can read minds."], "a": 0}, {"q": "Why is science not perfect?", "o": ["Evidence can be damaged and experts can make mistakes.", "Scientists are lazy.", "It is too cheap."], "a": 0}, {"q": "Why are online crimes difficult to solve?", "o": ["There are no fingerprints.", "They are not real crimes.", "They happen at night."], "a": 0}]}, "idioms": {"items": [["caught red-handed", "Caught while doing something wrong.", "اتمسك متلبس", "The thief was caught red-handed with the stolen phone in his pocket.", "الحرامي اتمسك متلبس والموبايل المسروق في جيبه."], ["get away with murder", "To do bad things without being punished.", "يعمل أي حاجة غلط ومحدش يحاسبه", "Their youngest son gets away with murder — his parents never punish him.", "ابنهم الصغير بيعمل أي حاجة ومحدش بيحاسبه."], ["take the law into your own hands", "To punish someone yourself instead of going to the police.", "ياخد حقه بإيده", "Don't take the law into your own hands. Call the police.", "متاخدش حقك بإيدك. كلّم البوليس."], ["a slap on the wrist", "A very light punishment.", "عقاب خفيف جدًا", "He stole a car and only got a slap on the wrist.", "سرق عربية وأخد عقاب خفيف جدًا."]], "quiz": [{"q": "The police found him inside the shop at night. He was ___.", "o": ["caught red-handed", "a slap on the wrist", "getting away with murder", "taking the law"], "a": 0}, {"q": "Only a small fine for such a big crime? That's just ___.", "o": ["a slap on the wrist", "caught red-handed", "murder", "the law"], "a": 0}, {"q": "\"Take the law into your own hands\" means…", "o": ["punish someone yourself", "become a lawyer", "read the law", "go to court"], "a": 0}, {"q": "\"Get away with murder\" means…", "o": ["do bad things without punishment", "kill someone", "run from the police", "catch a criminal"], "a": 0}]}, "phrasal": {"items": [["break into", "To enter a building illegally, usually to steal.", "يقتحم مكان (عشان يسرق)", "Someone broke into the flat next door last night.", "حد اقتحم الشقة اللي جنبنا امبارح بالليل."], ["get away with", "To do something wrong and not be caught or punished.", "يفلت من العقاب", "Burglars often get away with it because there are no witnesses.", "الحرامية كتير بيفلتوا لأن مفيش شهود."], ["turn in", "To give someone to the police.", "يسلّم حد للبوليس", "His own brother turned him in.", "أخوه نفسه سلّمه للبوليس."], ["look into", "To investigate or examine something.", "يحقق في / يدرس موضوع", "The detective is looking into the case.", "المحقق بيحقق في القضية."]], "quiz": [{"q": "The police are ___ the robbery at the bank.", "o": ["looking into", "breaking into", "turning in", "getting away"], "a": 0}, {"q": "Thieves ___ the shop and took all the phones.", "o": ["broke into", "looked into", "turned in", "got away with"], "a": 0}, {"q": "He felt guilty, so he ___ himself ___ to the police.", "o": ["turned / in", "looked / into", "broke / into", "got / away"], "a": 0}, {"q": "You won't ___ cheating! The teacher saw you.", "o": ["get away with", "break into", "look into", "turn in"], "a": 0}]}, "slang": {"items": [["sus", "Suspicious; not trustworthy.", "مريب / مش مريح", "That guy outside is acting kinda sus.", "الواد اللي برة ده تصرفاته مريبة شوية.", "بين الصحاب — مش في الشغل"], ["busted", "Caught doing something wrong.", "اتقفش", "He tried to copy my homework and got busted.", "حاول ينقل الواجب بتاعي واتقفش.", "كلمة شبابية عادية جدًا"], ["shady", "Dishonest or not to be trusted.", "مش مضمون / مشبوه", "Don't buy a phone from that shady website.", "متشتريش موبايل من الموقع المشبوه ده.", "بتتقال كتير عن ناس ومواقع"], ["snitch", "A person who tells the police or teacher about others.", "فتّان / واشي", "Nobody likes a snitch.", "محدش بيحب الفتّان.", "ممكن تكون مهينة — خلي بالك"], ["no cap", "No lie; I'm being serious.", "من غير هزار / والله", "No cap, I saw the whole thing.", "والله شفت كل حاجة.", "سلانج أمريكاني حديث — للصحاب بس"]], "quiz": [{"q": "\"No cap, I saw him take it.\" means…", "o": ["I'm serious, I saw him take it.", "I lost my hat.", "I didn't see anything.", "I took the cap."], "a": 0}, {"q": "Someone acting strangely near your car is ___.", "o": ["sus", "no cap", "busted", "a slap"], "a": 0}, {"q": "He was caught cheating. He got ___.", "o": ["busted", "sus", "shady", "capped"], "a": 0}, {"q": "Where is slang OK?", "o": ["chatting with friends", "a job interview", "a formal email", "an exam essay"], "a": 0}]}, "story": {"title": "The Missing Painting", "ar": "اللوحة المختفية", "g": "f", "lines": [["On a quiet Monday morning, the Cairo Art Museum opened its doors as usual.", "في صباح يوم اتنين هادي، متحف القاهرة للفنون فتح أبوابه زي العادة."], ["But the guard, Mr. Fathy, immediately noticed an empty space on the wall. The famous painting \"The Nile at Sunset\" was gone!", "بس الحارس، أستاذ فتحي، لاحظ على طول مكان فاضي على الحيطة. اللوحة المشهورة \"النيل وقت الغروب\" اختفت!"], ["Detective Mona arrived within an hour. She looked carefully around the room.", "المحققة منى وصلت في خلال ساعة. بصّت بتركيز حوالين الأوضة."], ["\"The alarm didn't ring,\" she said, \"so the thief must have known the security code.\"", "\"الإنذار مارنّش،\" قالت، \"يبقى الحرامي أكيد كان عارف كود الأمان.\""], ["Only three people knew the code: the manager, the cleaner, and Mr. Fathy himself.", "تلات أشخاص بس كانوا عارفين الكود: المدير، وعامل النظافة، والأستاذ فتحي نفسه."], ["The manager had been in Paris all weekend, so he can't have taken it.", "المدير كان في باريس طول الويك إند، يبقى مستحيل يكون أخدها."], ["The cleaner said she had left at six o'clock, and the CCTV showed her walking out empty-handed.", "عاملة النظافة قالت إنها مشيت الساعة ستة، والكاميرا بيّنتها خارجة إيديها فاضية."], ["Then Mona noticed something strange: Mr. Fathy's shoes were covered in fresh paint.", "وبعدين منى لاحظت حاجة غريبة: جزمة الأستاذ فتحي كانت عليها بوية جديدة."], ["\"You might have thought nobody would notice,\" she said calmly, \"but you were caught red-handed — or should I say, red-footed!\"", "\"يمكن كنت فاكر إن محدش هياخد باله،\" قالت بهدوء، \"بس إنت اتمسكت متلبس — أو أقول متلبس برجليك!\""], ["Mr. Fathy admitted everything. The painting was found in his car, and justice was done.", "الأستاذ فتحي اعترف بكل حاجة. اللوحة اتلقت في عربيته، والعدالة أخدت مجراها."]], "quiz": [{"q": "What was missing from the museum?", "o": ["a famous painting", "a statue", "some money"], "a": 0}, {"q": "Why must the thief have known the code?", "o": ["The alarm didn't ring.", "The door was broken.", "The window was open."], "a": 0}, {"q": "Why can't the manager have taken it?", "o": ["He had been in Paris all weekend.", "He was sleeping.", "He was sick."], "a": 0}, {"q": "What clue did Detective Mona notice?", "o": ["fresh paint on Mr. Fathy's shoes", "a fingerprint", "a broken window"], "a": 0}, {"q": "Where was the painting found?", "o": ["in Mr. Fathy's car", "in Paris", "in the cleaner's bag"], "a": 0}]}, "challenge": {"title": "You Are the Detective!", "ar": "إنت المحقق! — جاوب وسجّل", "qs": ["Describe a famous crime or mystery you know about.", "What do you think the best way to stop crime in your city is?", "If you found a wallet full of money in the street, what would you do?", "Should young criminals go to prison or get a second chance? Why?", "Your phone disappeared from your desk. Who might have taken it? Make three deductions.", "Do you think online crime is more dangerous than street crime? Why?", "Would you like to be a detective or a lawyer? Why or why not?", "Is it ever OK to break the law? Give an example.", "How has technology helped the police?", "What punishment do you think is fair for cheating in exams?"]}, "games": {"pairs": [["🦹", "burglar"], ["🔍", "evidence"], ["☝️", "fingerprint"], ["👁️", "witness"], ["⚖️", "justice"], ["🧾", "alibi"]], "spell": [["🕵️", "detective"], ["🤫", "suspect"], ["🙋", "victim"], ["🏛️", "court"], ["👨‍⚖️", "judge"], ["✅", "guilty"], ["🔒", "prison"], ["🗂️", "clue"]], "speed": [["He must have climbed through the window.", true], ["He must have went home.", false], ["She can't have stolen it — she was in Cairo.", true], ["They might have seen the thief.", true], ["He mustn't have done it.", false], ["She must have been sleeping.", true], ["He might has taken it.", false], ["You can't have finished already!", true], ["The door could have been open.", true], ["He must have broke the window.", false], ["A witness sees a crime happen.", true], ["An innocent person is guilty.", false], ["Fingerprints are a kind of evidence.", true], ["\"Busted\" means caught doing something wrong.", true], ["\"Break into\" means to enter illegally.", true], ["\"A slap on the wrist\" is a very hard punishment.", false]]}, "test": {"pass": 60, "sections": [{"id": "voc", "title": "Vocabulary", "ar": "المفردات", "icon": "📚", "qs": [{"q": "A person who saw a crime = a ___.", "o": ["witness", "judge", "victim"], "a": 0, "pic": "👁️"}, {"q": "Proof that someone did something = ___.", "o": ["evidence", "alibi", "sentence"], "a": 0, "pic": "🔍"}, {"q": "Someone who suffered because of a crime = a ___.", "o": ["victim", "suspect", "lawyer"], "a": 0, "pic": "🙋"}, {"q": "Proof that you were somewhere else = an ___.", "o": ["alibi", "clue", "motive"], "a": 0, "pic": "🧾"}, {"q": "Not guilty = ___.", "o": ["innocent", "suspicious", "shady"], "a": 0, "pic": "❎"}, {"q": "\"المحكمة\" in English is…", "o": ["court", "prison", "theft"], "a": 0, "say": "Choose the correct word."}]}, {"id": "gra", "title": "Grammar", "ar": "القواعد", "icon": "📘", "qs": [{"q": "The floor is wet. Someone ___ water.", "o": ["must have spilled", "can't have spilled", "must spill"], "a": 0}, {"q": "He ___ the crime. He was in hospital that night.", "o": ["can't have committed", "must have committed", "might commit"], "a": 0}, {"q": "I'm not sure. She ___ the bus.", "o": ["might have missed", "must have miss", "can't missed"], "a": 0}, {"q": "The car is gone. The thief ___ the keys.", "o": ["must have found", "must have find", "must found"], "a": 0}, {"q": "They didn't reply. They ___ working.", "o": ["must have been", "must been", "must have be"], "a": 0}, {"q": "Which is correct?", "o": ["She couldn't have known the code.", "She couldn't has known the code.", "She couldn't have knew the code."], "a": 0}]}, {"id": "con", "title": "Conversation", "ar": "المحادثة", "icon": "💬", "qs": [{"q": "\"Someone broke into our neighbour's flat!\" — Best answer:", "o": ["Really? Did they take anything?", "Great, congratulations!", "Broke is a verb."], "a": 0}, {"q": "\"How did the burglar get in?\" — Best answer:", "o": ["He must have climbed through the window.", "He must climbed the window.", "Yes, he did."], "a": 0}, {"q": "\"Do the police have any evidence?\" — Best answer:", "o": ["Yes, they found a fingerprint.", "Yes, they are police.", "Evidence is good."], "a": 0}, {"q": "\"Who took my sandwich?\" — Best answer:", "o": ["It might have been Ahmed. He was hungry.", "It must be a sandwich.", "I am a sandwich."], "a": 0}, {"q": "\"He was caught red-handed.\" — Best answer:", "o": ["So he can't deny it!", "Red is my favourite colour.", "His hands are cold."], "a": 0}, {"q": "\"That website looks shady.\" — Best answer:", "o": ["You're right. Let's not buy anything there.", "Yes, it has a lot of shade.", "Shady is sunny."], "a": 0}]}, {"id": "rea", "title": "Reading", "ar": "القراءة", "icon": "📖", "passage": ["Last week, someone stole a bike from outside our school.", "The security guard said he had been at the gate all day, so the thief can't have walked through the main entrance.", "There is a small hole in the back fence, so the thief must have come in that way.", "The CCTV camera near the fence was broken. Someone might have damaged it on purpose.", "Luckily, a student had taken a photo of the bike thief, and the police caught him the next day."], "qs": [{"q": "What was stolen?", "o": ["a bike", "a phone", "a laptop"], "a": 0}, {"q": "Why can't the thief have used the main entrance?", "o": ["The guard was at the gate all day.", "It was locked forever.", "It was raining."], "a": 0}, {"q": "How must the thief have come in?", "o": ["through a hole in the back fence", "through the roof", "through the main door"], "a": 0}, {"q": "What might someone have done to the camera?", "o": ["damaged it on purpose", "painted it", "stolen it"], "a": 0}, {"q": "How was the thief caught?", "o": ["A student had taken a photo of him.", "He turned himself in.", "The camera recorded him."], "a": 0}]}, {"id": "wri", "title": "Writing", "ar": "الكتابة", "icon": "✍️", "writing": true, "prompt": "You are a detective. Write a short report (70–100 words) about a mystery: what happened, the evidence, and your conclusions. Use must have / might have / can't have.", "promptAr": "إنت محقق. اكتب تقرير قصير (٧٠–١٠٠ كلمة) عن لغز: إيه اللي حصل، والأدلة، واستنتاجاتك. استخدم must have / might have / can't have.", "checks": [["🕵️", "Crime words", "x", "\\b(crime|thief|burglar|police|evidence|witness|suspect|detective|clue|stolen|stole|victim|fingerprint|cctv)\\b"], ["🔍", "Past deduction", "x", "\\b(must|might|may|could|can't|couldn't)\\s+have\\s+\\w+"], ["🧠", "because / so", "x", "\\b(because|so|since)\\b"], ["💬", "At least 70 words", "len70"]]}]}, "watch": [{"yt": "e6WMasfPK6c", "title": "Crime Scene Investigation", "ar": "التحقيق في مسرح الجريمة — عالمة طب شرعي بتحكي قضية", "by": "Test-English", "lines": [["Welcome to Crime Uncovered. Today we have Dr Emily Carter, a forensic scientist, with us.", "أهلًا بيكم في \"الجريمة المكشوفة\". النهارده معانا دكتورة إميلي كارتر، عالمة طب شرعي."], ["One case involved a burglary that turned into a murder. At first, the police thought it was a robbery gone wrong.", "في قضية بدأت بسرقة واتحولت لجريمة قتل. في الأول، البوليس افتكرها سرقة باظت."], ["The crime scene looked staged. In a real burglary, thieves take valuable items, but here nothing valuable was missing.", "مسرح الجريمة كان شكله متفبرك. في السرقة الحقيقية، الحرامية بياخدوا حاجات غالية، بس هنا مفيش حاجة غالية اختفت."], ["We found fingerprints on the door and furniture, all belonging to people who knew him: family and friends.", "لقينا بصمات على الباب والعفش، كلها لناس يعرفوه: العيلة والصحاب."], ["There were no signs of forced entry, suggesting the victim probably knew the killer and let them inside.", "مكانش في أي علامات كسر، وده معناه إن الضحية غالبًا كان يعرف القاتل ودخّله بنفسه."], ["We had to check their alibis. For those without clear alibis, we did DNA tests, and none of them matched.", "كان لازم نتأكد من حجج غيابهم. واللي مكانش عنده حجة واضحة عملناله تحليل DNA، ومفيش ولا واحد طابق."], ["Security cameras showed a man parking his car nearby about two hours before the body was found.", "كاميرات المراقبة بيّنت راجل بيركن عربيته قريب قبل ما الجثة تتلاقى بساعتين تقريبًا."], ["The police checked the wife's phone records. She had been calling an unknown number again and again.", "البوليس راجع سجل مكالمات الزوجة. كانت بتكلم رقم مجهول مرة ورا مرة."], ["The number belonged to a man whose car matched the one on the security footage.", "الرقم كان لراجل عربيته طابقت العربية اللي في تسجيل الكاميرات."], ["A DNA test confirmed it. Once we had enough evidence, they both confessed.", "تحليل DNA أكّد ده. ولما بقى عندنا أدلة كفاية، الاتنين اعترفوا."], ["The trial lasted about three weeks, and both were found guilty.", "المحاكمة استمرت حوالي ٣ أسابيع، والاتنين اتحكم عليهم إنهم مذنبين."], ["Forensic science is about uncovering the truth, and every case brings us one step closer to justice.", "الطب الشرعي هدفه كشف الحقيقة، وكل قضية بتقربنا خطوة من العدالة."]], "words": ["forensic scientist", "burglary", "crime scene", "staged", "valuable", "fingerprints", "forced entry", "alibi", "security cameras", "evidence", "confessed", "guilty"], "quiz": [{"q": "What did the police think at first?", "o": ["It was a robbery gone wrong.", "It was an accident.", "Nothing had happened."], "a": 0}, {"q": "Why did the crime scene look staged?", "o": ["Nothing valuable was missing.", "The house was clean.", "The door was broken."], "a": 0}, {"q": "What did \"no signs of forced entry\" suggest?", "o": ["The victim probably knew the killer.", "The killer came through the roof.", "There was no crime."], "a": 0}, {"q": "What did the security cameras show?", "o": ["a man parking his car nearby", "the wife leaving", "nothing useful"], "a": 0}, {"q": "What did the wife's phone records show?", "o": ["She had been calling an unknown number.", "She never used her phone.", "She called the police."], "a": 0}, {"q": "What was the result of the trial?", "o": ["Both were found guilty.", "Both were innocent.", "There was no trial."], "a": 0}]}]}, "2": {"n": 2, "title": "Fame and Celebrity Culture", "ar": "الشهرة وعالم المشاهير — Reporting Verbs", "icon": "🌟", "cover": "img/b2/u2.jpg", "intro": "اتكلم عن الشهرة والمشاهير والإشاعات والسوشيال ميديا، واستخدم reporting verbs زي deny / admit / refuse / promise عشان تحكي اللي الناس قالوه.", "videos": [{"id": "b2v2", "title": "The Rumour", "ar": "الإشاعة — سلمى وآدم", "src": "video/b2/u2v1.mp4", "poster": "img/b2/u2v1.jpg", "sp": {"a": {"n": "Salma", "g": "f"}, "b": {"n": "Adam", "g": "m"}}, "lines": [["a", "Adam, have you seen the news about Zain? Everyone is talking about him.", "آدم، شفت أخبار زين؟ كل الناس بتتكلم عنه."], ["b", "The singer? I saw a headline saying he was leaving music forever. Is it true?", "المغني؟ شفت عنوان بيقول إنه هيسيب المزيكا للأبد. ده بجد؟"], ["a", "No! He denied leaving music. In an interview last night, he insisted that it was just a rumour.", "لأ! هو نفى إنه هيسيب المزيكا. في لقاء امبارح بالليل، أصرّ إن دي مجرد إشاعة."], ["b", "So why did the rumour start in the first place?", "طيب الإشاعة دي بدأت إزاي أصلًا؟"], ["a", "He admitted feeling exhausted after his world tour. He said fame had taken over his whole life.", "هو اعترف إنه حاسس بإرهاق بعد جولته العالمية. وقال إن الشهرة سيطرت على حياته كلها."], ["b", "I can imagine. Paparazzi follow him everywhere. He can't even go to a café without being recognised.", "أقدر أتخيل. المصورين بيمشوا وراه في كل حتة. ميقدرش حتى يروح كافيه من غير ما حد يعرفه."], ["a", "Exactly. He also refused to answer questions about his private life. He said his family was off-limits.", "بالظبط. ورفض كمان يجاوب على أسئلة عن حياته الخاصة. وقال إن عيلته خط أحمر."], ["b", "Good for him. Do you think fame is worth it, though? All that money and attention?", "برافو عليه. بس إنت شايفة إن الشهرة تستاهل؟ كل الفلوس والاهتمام ده؟"], ["a", "Not for me! I'd hate to lose my privacy. But Zain promised to release a new album next year, so his fans are happy.", "مش ليا! أكره إني أخسر خصوصيتي. بس زين وعد إنه ينزل ألبوم جديد السنة الجاية، فالفانز مبسوطين."], ["b", "Well, I'm a big fan too. I'll believe the rumours when he says them himself!", "وأنا كمان فان كبير. هصدق الإشاعات لما هو بنفسه يقولها!"]], "quiz": [{"q": "What was the rumour about Zain?", "o": ["He was leaving music forever.", "He was getting married.", "He was moving to London."], "a": 0}, {"q": "What did Zain deny?", "o": ["leaving music", "feeling tired", "having fans"], "a": 0}, {"q": "What did he admit?", "o": ["feeling exhausted after his world tour", "starting the rumour", "hating his fans"], "a": 0}, {"q": "What did he refuse to do?", "o": ["answer questions about his private life", "sing", "go on tour"], "a": 0}, {"q": "What did he promise?", "o": ["to release a new album next year", "to stop singing", "to buy a café"], "a": 0}], "fill": [[2, "denied"], [2, "insisted"], [2, "rumour"], [4, "admitted"], [4, "fame"], [5, "Paparazzi"], [5, "recognised"], [6, "refused"], [6, "private life"], [8, "privacy"], [8, "promised"], [9, "fan"]]}], "vocab": [{"t": "Fame", "ar": "الشهرة", "items": [["🌟", "celebrity", "She became a celebrity after one viral song."], ["🏆", "fame", "Fame changed his life completely."], ["📸", "paparazzi", "The paparazzi waited outside his house."], ["🙌", "fan", "Thousands of fans came to the concert."], ["🗞️", "headline", "His name was in every headline."], ["🗣️", "rumour", "Don't believe every rumour you hear."], ["🔒", "privacy", "Celebrities often lose their privacy."], ["💎", "glamorous", "Her life looks so glamorous on Instagram."]]}, {"t": "Being in the public eye", "ar": "تحت الأضواء", "items": [["👀", "recognise", "People recognise him everywhere."], ["🎤", "interview", "She gave an interview on TV."], ["🎬", "red carpet", "The stars walked on the red carpet."], ["🤝", "role model", "Footballers should be good role models."], ["📣", "publicity", "Any publicity is good publicity, they say."], ["🎭", "image", "Celebrities work hard to protect their image."], ["⚡", "scandal", "The scandal ruined his career."], ["🚀", "overnight success", "She became an overnight success."]]}, {"t": "Reporting verbs", "ar": "أفعال الحكي", "items": [["🙅", "deny", "He denied starting the rumour."], ["🙋", "admit", "She admitted feeling nervous."], ["✋", "refuse", "He refused to answer the question."], ["🤞", "promise", "She promised to visit her fans."], ["💪", "insist", "He insisted that it was a lie."], ["📢", "announce", "They announced their new album."], ["💡", "suggest", "Her manager suggested taking a break."], ["🙏", "apologise", "He apologised for being late."]]}], "talk": [{"title": "Let's Talk · Student A", "ar": "الطالب A", "list": [["Would you like to be famous? Why or why not?", "نفسك تبقى مشهور؟", "No, I'd hate to lose my privacy."], ["Who is a celebrity you admire, and why?", "مين المشهور اللي بتعجب بيه وليه؟", "Mohamed Salah, because he works hard and stays humble."], ["Should celebrities be role models for young people?", "المشاهير لازم يكونوا قدوة للشباب؟", "Yes, because young people copy them."], ["Do you believe celebrity rumours on social media?", "بتصدق إشاعات المشاهير على السوشيال ميديا؟", "Not usually. Many of them are fake."], ["What is the worst thing about being famous?", "إيه أسوأ حاجة في الشهرة؟", "You can never go anywhere without being recognised."]]}, {"title": "Let's Talk · Student B", "ar": "الطالب B", "list": [["Is it easier to become famous today than in the past? Why?", "الشهرة أسهل النهارده من زمان؟", "Yes, anyone can go viral on TikTok."], ["Do celebrities deserve their huge salaries?", "المشاهير يستاهلوا المرتبات الضخمة دي؟", "Some do, like doctors who are famous for saving lives!"], ["Should the paparazzi be allowed to follow celebrities?", "ينفع المصورين يمشوا ورا المشاهير؟", "No, everyone deserves privacy."], ["What would you do with fifteen minutes of fame?", "تعمل إيه لو اتشهرت لفترة قصيرة؟", "I'd use it to help a good cause."], ["Which is better: being famous or being respected?", "أحسن تبقى مشهور ولا محترم؟", "Being respected, definitely."]]}], "grammar": {"title": "Reporting Verbs", "ar": "أفعال الحكي — deny / admit / refuse / promise / suggest", "blocks": [{"type": "intro", "en": "Instead of always using 'say' and 'tell', we use reporting verbs to show HOW someone said something. Each verb has its own pattern: + -ing, + to + verb, or + that.", "ar": "بدل ما نقول said وtold على طول، بنستخدم أفعال بتوضح الشخص قال الكلام إزاي. وكل فعل ليه تركيبة: + ing أو + to + فعل أو + that."}, {"type": "big", "items": [{"v": "verb + -ing", "p": "deny · admit · suggest · recommend", "c": 1, "eg": ["He denied starting the rumour.", "She admitted feeling exhausted.", "Her manager suggested taking a break."]}, {"v": "verb + to + infinitive", "p": "refuse · promise · agree · offer · threaten", "c": 2, "eg": ["He refused to answer the question.", "She promised to release a new album.", "They agreed to do an interview."]}, {"v": "verb + object + to + infinitive", "p": "advise · warn · encourage · remind · ask", "c": 3, "eg": ["His lawyer advised him to stay quiet.", "She warned fans not to believe rumours.", "He encouraged us to follow our dreams."]}]}, {"type": "table", "title": "📋 Direct speech → reporting verb", "head": ["Direct speech", "Reported"], "rows": [["\"I didn't start the rumour.\"", "He denied starting the rumour."], ["\"Yes, I was tired.\"", "She admitted being tired."], ["\"No, I won't answer.\"", "He refused to answer."], ["\"I'll release an album.\"", "She promised to release an album."], ["\"Why don't you rest?\"", "He suggested resting."], ["\"Don't trust them!\"", "She warned me not to trust them."]]}, {"type": "uses", "title": "💡 Other useful patterns", "ar": "تركيبات تانية", "items": [["🙏", "apologise for + -ing", "He apologised for being late.", "اعتذر عن"], ["👉", "accuse sb of + -ing", "They accused him of lying.", "اتهمه بـ"], ["💪", "insist (that) + clause", "He insisted that it was a lie.", "أصرّ إن"], ["📢", "announce (that) + clause", "She announced that she was retiring.", "أعلن إن"]]}, {"type": "tip", "en": "Don't use 'to' after deny/admit/suggest: He denied to start ✖ → He denied starting ✔. And 'suggest' never takes an object + to: She suggested me to go ✖ → She suggested going / that I go ✔.", "ar": "متحطش to بعد deny / admit / suggest: denied starting مش denied to start. وsuggest مش بييجي بعدها شخص + to: suggested going."}]}, "exercises": [{"type": "mcq", "title": "Reporting Verbs — 10 MCQs", "ar": "اختار الصح", "speak": true, "items": [{"q": "He denied ___ the rumour.", "o": ["starting", "to start", "start", "started"], "a": 0}, {"q": "She refused ___ about her private life.", "o": ["to talk", "talking", "talk", "that she talk"], "a": 0}, {"q": "The singer promised ___ a new album.", "o": ["to release", "releasing", "release", "released"], "a": 0}, {"q": "He admitted ___ nervous before the show.", "o": ["feeling", "to feel", "feel", "that feel"], "a": 0}, {"q": "Her manager suggested ___ a break.", "o": ["taking", "to take", "her to take", "take"], "a": 0}, {"q": "His lawyer advised him ___ quiet.", "o": ["to stay", "staying", "stay", "stayed"], "a": 0}, {"q": "She apologised ___ late.", "o": ["for being", "to be", "being", "that be"], "a": 0}, {"q": "They accused him ___ lying.", "o": ["of", "for", "to", "about"], "a": 0}, {"q": "\"Don't believe the rumours!\" → She warned fans ___ the rumours.", "o": ["not to believe", "don't believe", "not believing", "to not believing"], "a": 0}, {"q": "Which sentence is correct?", "o": ["She suggested going to the concert.", "She suggested me to go to the concert.", "She suggested to go to the concert.", "She suggested go to the concert."], "a": 0}]}, {"type": "mcq", "title": "Which pattern?", "ar": "أنهي تركيبة؟", "items": [{"q": "deny + ___", "o": ["-ing", "to + verb"], "a": 0}, {"q": "refuse + ___", "o": ["to + verb", "-ing"], "a": 0}, {"q": "advise + ___", "o": ["object + to + verb", "-ing only"], "a": 0}, {"q": "\"I'll help you.\" → He offered ___ me.", "o": ["to help", "helping"], "a": 0}, {"q": "\"OK, I lied.\" → She admitted ___.", "o": ["lying", "to lie"], "a": 0}]}, {"type": "ord", "title": "Make sentences", "ar": "رتّب الكلمات", "items": [{"c": ["He", "denied", "starting", "the rumour"], "a": [0, 1, 2, 3]}, {"c": ["She", "refused", "to answer", "the question"], "a": [0, 1, 2, 3]}, {"c": ["They", "promised", "to release", "a new song"], "a": [0, 1, 2, 3]}, {"c": ["His manager", "advised him", "to take", "a break"], "a": [0, 1, 2, 3]}]}], "reading": {"title": "The Price of Fame", "ar": "تمن الشهرة", "g": "f", "lines": [["For many young people, becoming famous is the ultimate dream. In surveys, a surprising number of teenagers say that being famous is more important to them than being rich or successful.", "لشباب كتير، الشهرة هي الحلم الأكبر. في استطلاعات، عدد كبير بشكل مفاجئ من المراهقين بيقولوا إن الشهرة أهم ليهم من الغنى أو النجاح."], ["It's easy to see why. Celebrities seem to live glamorous lives, full of red carpets, luxury holidays and adoring fans.", "وده سهل نفهمه. المشاهير شكلهم عايشين حياة براقة، مليانة سجاجيد حمرا وإجازات فخمة ومعجبين بيعشقوهم."], ["But behind the photos, the reality can be very different.", "بس ورا الصور، الحقيقة ممكن تكون مختلفة جدًا."], ["The biggest cost of fame is the loss of privacy. Famous people are recognised wherever they go, and every mistake they make can become a headline.", "أكبر تمن للشهرة هو ضياع الخصوصية. المشاهير بيتعرفوا في أي مكان يروحوه، وأي غلطة بيعملوها ممكن تبقى عنوان رئيسي."], ["Many stars have admitted feeling lonely, because they never know who their real friends are.", "نجوم كتير اعترفوا إنهم بيحسوا بالوحدة، لأنهم عمرهم ما بيعرفوا مين صحابهم الحقيقيين."], ["Social media has made the pressure even greater. Today, a celebrity can receive thousands of comments in a single hour, and not all of them are kind.", "السوشيال ميديا زوّدت الضغط أكتر. النهارده، المشهور ممكن يجيله آلاف التعليقات في ساعة واحدة، ومش كلها لطيفة."], ["Some have refused to use social media at all, while others have taken long breaks to protect their mental health.", "بعضهم رفض يستخدم السوشيال ميديا خالص، وغيرهم خدوا بريكات طويلة عشان يحموا صحتهم النفسية."], ["On the other hand, fame can be a powerful tool for good. Many celebrities use their influence to raise money for charity or to speak about important issues.", "من ناحية تانية، الشهرة ممكن تكون أداة قوية للخير. مشاهير كتير بيستخدموا تأثيرهم عشان يجمعوا فلوس للخير أو يتكلموا عن قضايا مهمة."], ["So, is fame worth it? Perhaps the answer depends on why you want it.", "طيب، الشهرة تستاهل؟ يمكن الإجابة بتعتمد على إنت عايزها ليه."], ["As one actor put it, \"Fame is a great servant, but a terrible master.\"", "وزي ما قال ممثل: \"الشهرة خادم عظيم، بس سيّد فظيع.\""]], "keys": [["🎯", "ultimate", "the greatest or most important"], ["💎", "glamorous", "exciting and attractive, connected with money and success"], ["🔒", "privacy", "the right to keep your personal life private"], ["🗞️", "headline", "the title of a news story"], ["📣", "influence", "the power to affect what people think or do"], ["👑", "master", "a person who controls others"]], "quiz": [{"q": "What do many teenagers say in surveys?", "o": ["Being famous is more important than being rich.", "They hate celebrities.", "They want to be doctors."], "a": 0}, {"q": "What is the biggest cost of fame, according to the text?", "o": ["the loss of privacy", "paying taxes", "travelling a lot"], "a": 0}, {"q": "Why do many stars feel lonely?", "o": ["They never know who their real friends are.", "They live in the countryside.", "They have no fans."], "a": 0}, {"q": "How has social media affected celebrities?", "o": ["It has made the pressure greater.", "It has made them invisible.", "It has stopped all comments."], "a": 0}, {"q": "How can fame be a tool for good?", "o": ["Celebrities can raise money for charity.", "Celebrities can buy more cars.", "Celebrities can avoid fans."], "a": 0}, {"q": "\"Fame is a great servant, but a terrible master\" means…", "o": ["Fame is good if you control it, bad if it controls you.", "Famous people need servants.", "Fame is always bad."], "a": 0}]}, "idioms": {"items": [["fifteen minutes of fame", "A short period of being famous.", "شهرة قصيرة وبتخلص", "After his video went viral, he enjoyed his fifteen minutes of fame.", "بعد ما الفيديو بتاعه انتشر، استمتع بشهرته القصيرة."], ["in the limelight", "Receiving a lot of public attention.", "تحت الأضواء", "She has been in the limelight since she was a child actress.", "هي تحت الأضواء من ساعة ما كانت ممثلة طفلة."], ["rise to fame", "To become famous.", "يوصل للشهرة", "He rose to fame after winning a TV talent show.", "اتشهر بعد ما كسب برنامج مواهب."], ["steal the show", "To be the best or most noticed in an event.", "يخطف الأضواء", "The little girl stole the show with her amazing voice.", "البنت الصغيرة خطفت الأضواء بصوتها المذهل."]], "quiz": [{"q": "The young dancer was so good that she ___.", "o": ["stole the show", "rose to fame", "was in the limelight", "had fifteen minutes"], "a": 0}, {"q": "His viral video gave him his ___.", "o": ["fifteen minutes of fame", "limelight", "show", "rise"], "a": 0}, {"q": "\"In the limelight\" means…", "o": ["receiving public attention", "in a lemon shop", "in the dark", "on holiday"], "a": 0}, {"q": "She ___ after her first film in 2015.", "o": ["rose to fame", "stole the show", "was limelight", "fifteen minutes"], "a": 0}]}, "phrasal": {"items": [["show off", "To try to impress people with what you have or can do.", "يتمنظر / يستعرض", "He loves showing off his expensive cars on Instagram.", "بيحب يتمنظر بعربياته الغالية على إنستجرام."], ["look up to", "To admire and respect someone.", "يعتبره قدوة", "Many children look up to famous footballers.", "أطفال كتير بيعتبروا لاعيبة الكورة المشهورين قدوة."], ["live up to", "To be as good as people expect.", "يكون على قد التوقعات", "His second album didn't live up to the fans' expectations.", "ألبومه التاني مكانش على قد توقعات الفانز."], ["put up with", "To accept something unpleasant without complaining.", "يستحمل", "Celebrities have to put up with a lot of criticism.", "المشاهير لازم يستحملوا انتقاد كتير."]], "quiz": [{"q": "I ___ my older sister. She is so smart and kind.", "o": ["look up to", "show off", "put up with", "live up to"], "a": 0}, {"q": "Stop ___ your new phone! Nobody cares.", "o": ["showing off", "looking up to", "living up to", "putting up with"], "a": 0}, {"q": "How do you ___ all that noise? I'd go crazy!", "o": ["put up with", "look up to", "show off", "live up to"], "a": 0}, {"q": "The film didn't ___ the hype. It was boring.", "o": ["live up to", "put up with", "show off", "look up to"], "a": 0}]}, "slang": {"items": [["spill the tea", "To share gossip or secret information.", "احكي الفضايح / قول اللي حصل", "Come on, spill the tea! What happened at the party?", "يلا احكي! إيه اللي حصل في الحفلة؟", "بين الصحاب — بتتقال بهزار"], ["stan", "A very big, loyal fan.", "فان متعصب جدًا", "I'm a huge stan of that band — I know every song.", "أنا فان متعصب للفرقة دي — حافظ كل أغانيها.", "من السوشيال ميديا"], ["clout", "Popularity and influence, especially online.", "شهرة ونفوذ أونلاين", "He only did that crazy video for clout.", "عمل الفيديو المجنون ده عشان الشهرة وبس.", "غالبًا بمعنى سلبي"], ["slay", "To do something extremely well.", "كسّر الدنيا / أبدع", "She slayed on stage last night!", "كسّرت الدنيا على المسرح امبارح!", "مدح بين الصحاب"], ["it's giving…", "It looks / feels like… (a style or vibe).", "شكله / حاسس إنه…", "Your outfit? It's giving movie star.", "لبسك؟ شكلك نجمة سينما.", "سلانج حديث جدًا — للهزار"]], "quiz": [{"q": "\"Spill the tea!\" means…", "o": ["Tell me the gossip!", "Clean the table!", "Make me some tea!", "Stop talking!"], "a": 0}, {"q": "A fan who knows everything about a singer is a ___.", "o": ["stan", "clout", "tea", "slay"], "a": 0}, {"q": "\"He did it for clout.\" means he did it…", "o": ["to get popular online", "for money only", "to help people", "by mistake"], "a": 0}, {"q": "Your friend sang amazingly. You say: \"You ___!\"", "o": ["slayed", "spilled", "clouted", "stanned"], "a": 0}]}, "story": {"title": "Overnight Success", "ar": "النجاح اللي جه في ليلة", "g": "m", "lines": [["Nadia had been singing in her bedroom for years, but nobody outside her family had ever heard her.", "نادية كانت بتغني في أوضتها من سنين، بس محدش برة عيلتها سمعها قبل كده."], ["One evening, her little brother secretly recorded her and posted the video online.", "في ليلة، أخوها الصغير صوّرها من غير ما تعرف ونزل الفيديو أونلاين."], ["By the next morning, it had two million views. Nadia was an overnight success.", "تاني يوم الصبح، كان عليه ٢ مليون مشاهدة. نادية اتشهرت في ليلة."], ["TV shows invited her for interviews, and strangers recognised her in the street.", "برامج التليفزيون عزمتها على لقاءات، والناس الغريبة بقت تعرفها في الشارع."], ["At first, she loved being in the limelight. But soon, the comments started.", "في الأول، كانت مبسوطة إنها تحت الأضواء. بس بسرعة، التعليقات بدأت."], ["Some people accused her of copying other singers. Others said she would never live up to her first video.", "ناس اتهموها إنها بتقلد مطربين تانيين. وغيرهم قالوا إنها عمرها ما هتكون على قد أول فيديو."], ["Nadia stopped sleeping well. She admitted to her mother that fame was harder than she had imagined.", "نادية بطلت تنام كويس. واعترفت لمامتها إن الشهرة أصعب مما كانت متخيلة."], ["Her mother suggested taking a break from the internet, and Nadia agreed to try.", "مامتها اقترحت إنها تاخد بريك من الإنترنت، ونادية وافقت تجرّب."], ["For three months, she focused on her music, not on the comments. Then she released her first real song.", "لمدة ٣ شهور، ركزت على مزيكتها مش على التعليقات. وبعدين نزّلت أول أغنية حقيقية ليها."], ["It wasn't just fifteen minutes of fame anymore. This time, she was ready.", "المرة دي مكانتش شهرة قصيرة وخلاص. المرة دي، كانت جاهزة."]], "quiz": [{"q": "Who posted Nadia's video?", "o": ["her little brother", "her mother", "a TV show"], "a": 0}, {"q": "How many views did the video have the next morning?", "o": ["two million", "two hundred", "twenty"], "a": 0}, {"q": "What did some people accuse her of?", "o": ["copying other singers", "lying about her age", "stealing a song"], "a": 0}, {"q": "What did her mother suggest?", "o": ["taking a break from the internet", "stopping singing", "moving abroad"], "a": 0}, {"q": "How was Nadia different at the end?", "o": ["She was ready for fame.", "She hated music.", "She was still unknown."], "a": 0}]}, "challenge": {"title": "Fame: Dream or Nightmare?", "ar": "الشهرة: حلم ولا كابوس؟ — جاوب وسجّل", "qs": ["If you became famous tomorrow, what would you be famous for?", "Who is a famous person you look up to? Why?", "Report something a celebrity said recently. Use admit, deny, promise or refuse.", "Do you think celebrities should share their private lives online?", "Is it fair that some influencers earn more than doctors?", "What is the difference between being famous and being successful?", "Should famous people be punished more strictly when they break the law?", "How can fans support celebrities in a healthy way?", "Describe a time when someone \"stole the show\".", "Would you rather be famous for one day or respected for a lifetime? Why?"]}, "games": {"pairs": [["🌟", "celebrity"], ["📸", "paparazzi"], ["🗣️", "rumour"], ["🔒", "privacy"], ["⚡", "scandal"], ["🙌", "fan"]], "spell": [["🏆", "fame"], ["🗞️", "headline"], ["🎤", "interview"], ["🎭", "image"], ["📣", "publicity"], ["🙅", "deny"], ["🙋", "admit"], ["✋", "refuse"]], "speed": [["He denied starting the rumour.", true], ["She refused talking to the press.", false], ["They promised to release a new album.", true], ["He admitted feeling tired.", true], ["She suggested me to go.", false], ["His lawyer advised him to stay quiet.", true], ["He denied to steal it.", false], ["She apologised for being late.", true], ["They accused him of lying.", true], ["He promised coming early.", false], ["Paparazzi are photographers who follow celebrities.", true], ["A rumour is always true.", false], ["A stan is a very big fan.", true], ["\"Show off\" means to hide what you have.", false], ["\"Look up to\" means to admire someone.", true], ["\"Steal the show\" means to be the best in an event.", true]]}, "test": {"pass": 60, "sections": [{"id": "voc", "title": "Vocabulary", "ar": "المفردات", "icon": "📚", "qs": [{"q": "Photographers who follow famous people = ___.", "o": ["paparazzi", "fans", "judges"], "a": 0, "pic": "📸"}, {"q": "A story that may not be true = a ___.", "o": ["rumour", "headline", "privacy"], "a": 0, "pic": "🗣️"}, {"q": "Someone young people copy and admire = a role ___.", "o": ["model", "carpet", "success"], "a": 0, "pic": "🤝"}, {"q": "Something shocking that damages someone's reputation = a ___.", "o": ["scandal", "fan", "publicity"], "a": 0, "pic": "⚡"}, {"q": "Your right to a private life = ___.", "o": ["privacy", "image", "fame"], "a": 0, "pic": "🔒"}, {"q": "\"إشاعة\" in English is…", "o": ["rumour", "interview", "headline"], "a": 0, "say": "Choose the correct word."}]}, {"id": "gra", "title": "Grammar", "ar": "القواعد", "icon": "📘", "qs": [{"q": "\"I didn't take the money.\" → He denied ___ the money.", "o": ["taking", "to take", "take"], "a": 0}, {"q": "\"No, I won't sing.\" → She refused ___.", "o": ["to sing", "singing", "sing"], "a": 0}, {"q": "\"I'll call you.\" → He promised ___ me.", "o": ["to call", "calling", "call"], "a": 0}, {"q": "\"Let's go to the cinema.\" → She suggested ___ to the cinema.", "o": ["going", "to go", "me to go"], "a": 0}, {"q": "\"Don't be late!\" → Mum warned me ___ late.", "o": ["not to be", "don't be", "not being"], "a": 0}, {"q": "Which is correct?", "o": ["He apologised for missing the show.", "He apologised to miss the show.", "He apologised missing the show."], "a": 0}]}, {"id": "con", "title": "Conversation", "ar": "المحادثة", "icon": "💬", "qs": [{"q": "\"Is it true that Zain is leaving music?\" — Best answer:", "o": ["No, he denied it in an interview.", "Yes, he is music.", "Zain is a singer."], "a": 0}, {"q": "\"Would you like to be famous?\" — Best answer:", "o": ["Not really. I'd hate to lose my privacy.", "Yes, I am famous.", "Famous is a word."], "a": 0}, {"q": "\"Who do you look up to?\" — Best answer:", "o": ["My grandfather. He worked so hard.", "I look up at the sky.", "Up is a direction."], "a": 0}, {"q": "\"Spill the tea! What happened?\" — Best answer:", "o": ["OK, OK! You won't believe it…", "Sorry, I have no tea.", "I cleaned the table."], "a": 0}, {"q": "\"She stole the show last night.\" — Best answer:", "o": ["I know! She was amazing.", "Call the police!", "What did she steal?"], "a": 0}, {"q": "\"What did the singer say?\" — Best answer:", "o": ["She promised to visit Egypt next year.", "She promised visiting Egypt.", "She said me to visit."], "a": 0}]}, {"id": "rea", "title": "Reading", "ar": "القراءة", "icon": "📖", "passage": ["Karim is a 19-year-old YouTuber who rose to fame last year with his funny cooking videos.", "In a recent interview, he admitted feeling nervous before every new video.", "He denied paying for followers and insisted that his fans were all real.", "He refused to talk about his girlfriend, saying his private life was off-limits.", "At the end, he promised to open a small restaurant for students in Cairo next year."], "qs": [{"q": "How did Karim become famous?", "o": ["with funny cooking videos", "by singing", "by playing football"], "a": 0}, {"q": "What did he admit?", "o": ["feeling nervous before every video", "paying for followers", "hating cooking"], "a": 0}, {"q": "What did he deny?", "o": ["paying for followers", "making videos", "being a YouTuber"], "a": 0}, {"q": "What did he refuse to talk about?", "o": ["his girlfriend", "his recipes", "his fans"], "a": 0}, {"q": "What did he promise?", "o": ["to open a restaurant for students", "to stop YouTube", "to move abroad"], "a": 0}]}, {"id": "wri", "title": "Writing", "ar": "الكتابة", "icon": "✍️", "writing": true, "prompt": "Write a short news article (70–100 words) about a celebrity interview. Report what they said using at least three reporting verbs (deny, admit, refuse, promise, suggest…).", "promptAr": "اكتب خبر قصير (٧٠–١٠٠ كلمة) عن لقاء مع شخص مشهور، واحكي اللي قاله باستخدام ٣ reporting verbs على الأقل.", "checks": [["🌟", "Fame words", "x", "\\b(famous|fame|celebrity|fans|fan|interview|rumour|rumor|privacy|singer|actor|star)\\b"], ["📢", "Reporting verbs", "x", "\\b(denied|admitted|refused|promised|suggested|insisted|announced|apologised|apologized|warned|advised|agreed)\\b"], ["🧩", "verb + -ing / to", "x", "\\b(denied|admitted|suggested)\\s+\\w+ing\\b|\\b(refused|promised|agreed|offered)\\s+to\\s+\\w+"], ["💬", "At least 70 words", "len70"]]}]}, "watch": [{"yt": "rCh9MQibJ3c", "title": "How Fans Talk About Their Passions", "ar": "الفانز بيتكلموا إزاي عن شغفهم — 6 Minute English", "by": "BBC Learning English", "lines": [["If you really love something — a sport, a music band or a TV show — you might call yourself a fan.", "لو بتحب حاجة جدًا — رياضة أو فرقة مزيكا أو مسلسل — ممكن تسمي نفسك فان."], ["Thanks to the internet, fans from around the world can meet online, and this has led to a new word: fandom.", "بفضل الإنترنت، الفانز من كل العالم بيتقابلوا أونلاين، وده طلّع كلمة جديدة: fandom."], ["Fandom is more than being a fan. It's a whole culture created by a community of people who love the same thing.", "الـ fandom أكتر من إنك تبقى فان. ده ثقافة كاملة عاملها مجتمع ناس بيحبوا نفس الحاجة."], ["Fans are groups of like-minded people. They share similar opinions, ideas or interests.", "الفانز مجموعات ناس متشابهين في التفكير. بيشاركوا نفس الآراء والأفكار والاهتمامات."], ["They do weird and wonderful things together, like dressing up as Harry Potter characters.", "بيعملوا حاجات غريبة وجميلة مع بعض، زي إنهم يلبسوا زي شخصيات هاري بوتر."], ["This behaviour might be called quirky — odd or unusual, but in an interesting way.", "التصرف ده ممكن يتسمى quirky — غريب أو مختلف، بس بشكل ممتع."], ["Unfortunately, fans sometimes get mocked — people laugh at them in an unkind way.", "للأسف، الفانز أحيانًا بيتريقوا عليهم — الناس بتضحك عليهم بشكل مش لطيف."], ["BIRGing means \"Basking in Reflected Glory\": feeling good about yourself when your team wins.", "BIRGing يعني إنك تحس بالفخر بنفسك لما فريقك يكسب."], ["Fans say \"WE won!\", even though it was the players, not the fans, who scored the goal.", "الفانز بيقولوا \"إحنا كسبنا!\"، رغم إن اللاعيبة هما اللي جابوا الجول، مش الفانز."], ["The opposite is CORFing — \"Cutting Off Reflected Failure\": distancing yourself from your team when they lose.", "العكس هو CORFing — إنك تبعد نفسك عن فريقك لما يخسر."], ["Instead of saying \"We won\", you say, \"They played rubbish!\" Of course, true fans never CORF.", "بدل ما تقول \"إحنا كسبنا\"، بتقول \"هما لعبوا وحش!\" وطبعًا الفانز الحقيقيين عمرهم ما بيعملوا كده."], ["The original word 'fan' was first used about American baseball fans — or 'fanatics'.", "كلمة fan استُخدمت أول مرة عن مشجعين البيسبول الأمريكان — أو \"المتعصبين\"."]], "words": ["fan", "fandom", "passion", "community", "like-minded", "quirky", "mock", "dress up", "celebrations", "a piece of the action", "distancing", "fanatics"], "quiz": [{"q": "What is \"fandom\"?", "o": ["a culture created by a community of fans", "a type of sport", "a TV channel"], "a": 0}, {"q": "What does \"like-minded\" mean?", "o": ["sharing similar opinions and interests", "very intelligent", "unkind"], "a": 0}, {"q": "What does \"quirky\" mean?", "o": ["odd or unusual in an interesting way", "very boring", "very rich"], "a": 0}, {"q": "What is BIRGing?", "o": ["feeling good when your team wins", "leaving your team", "buying tickets"], "a": 0}, {"q": "What do fans say when they are CORFing?", "o": ["\"They played rubbish!\"", "\"We won!\"", "\"I love my team!\""], "a": 0}, {"q": "Who was the word 'fan' first used about?", "o": ["baseball fans", "movie stars", "Disney fans"], "a": 0}]}]}, "3": {"n": 3, "title": "Volunteering and Charity", "ar": "التطوع والعمل الخيري — Future Perfect & Future Perfect Continuous", "icon": "🤲", "cover": "img/b2/u3.jpg", "intro": "اتكلم عن التطوع ومساعدة الناس والمشاريع الخيرية، واستخدم will have done و will have been doing عشان تتكلم عن اللي هيكون خلص أو مستمر لحد وقت في المستقبل.", "videos": [{"id": "b2v3", "title": "The Charity Project", "ar": "المشروع الخيري — نور وكريم", "src": "video/b2/u3v1.mp4", "poster": "img/b2/u3v1.jpg", "sp": {"a": {"n": "Nour", "g": "f"}, "b": {"n": "Karim", "g": "m"}}, "lines": [["a", "Karim! You're just in time. We're packing food boxes for families in need.", "كريم! جيت في وقتك بالظبط. بنجهز كراتين أكل للأسر المحتاجة."], ["b", "Great, I'm happy to help out. How long have you been volunteering here?", "جميل، مبسوط إني أساعد. بقالك قد إيه بتتطوعي هنا؟"], ["a", "By the end of this month, I'll have been volunteering here for two years. Time flies!", "مع آخر الشهر ده، هيكون بقالي سنتين متطوعة هنا. الوقت بيجري!"], ["b", "Wow. And how many boxes are we preparing today?", "واو. وهنجهز كام كرتونة النهارده؟"], ["a", "Five hundred. If everyone keeps working at this speed, we'll have finished them by six o'clock.", "خمسمية. لو كله فضل شغال بالسرعة دي، هنكون خلصناهم الساعة ستة."], ["b", "That's amazing. What's the bigger goal of the charity?", "ده تحفة. إيه الهدف الأكبر للجمعية؟"], ["a", "We want to set up a free learning centre for children. By next summer, we'll have raised enough money to open it.", "عايزين نعمل مركز تعليم مجاني للأطفال. مع الصيف الجاي، هنكون جمعنا فلوس كفاية نفتحه."], ["b", "I'd love to be part of that. Can I sign up as a regular volunteer?", "نفسي أبقى جزء من ده. ينفع أسجّل متطوع بشكل منتظم؟"], ["a", "Of course! Just fill in this form. It doesn't matter how much time you give — every hour makes a difference.", "طبعًا! املا الاستمارة دي بس. مش مهم هتدي وقت قد إيه — كل ساعة بتفرق."], ["b", "Honestly, helping others feels better than anything I've done this year.", "بصراحة، مساعدة الناس إحساسها أحلى من أي حاجة عملتها السنة دي."], ["a", "That's the secret! When you give back, you get so much more in return.", "ده السر! لما تدّي، بتاخد أكتر بكتير في المقابل."]], "quiz": [{"q": "What are they doing?", "o": ["packing food boxes for families in need", "cooking at a restaurant", "cleaning the park"], "a": 0}, {"q": "How long will Nour have been volunteering by the end of the month?", "o": ["two years", "two months", "ten years"], "a": 0}, {"q": "By what time will they have finished the boxes?", "o": ["six o'clock", "midnight", "next week"], "a": 0}, {"q": "What is the bigger goal of the charity?", "o": ["a free learning centre for children", "a new hospital", "a football club"], "a": 0}, {"q": "What does Karim want to do?", "o": ["sign up as a regular volunteer", "leave early", "become a manager"], "a": 0}], "fill": [[0, "in need"], [1, "help out"], [1, "volunteering"], [2, "I'll have been volunteering"], [4, "we'll have finished"], [5, "charity"], [6, "set up"], [6, "raised"], [7, "sign up"], [8, "makes a difference"], [10, "give back"]]}], "vocab": [{"t": "Helping others", "ar": "مساعدة الناس", "items": [["🤲", "volunteer", "She volunteers at an animal shelter."], ["❤️", "charity", "He gives money to charity every month."], ["💰", "donate", "We donated clothes to the orphanage."], ["🎁", "donation", "Thank you for your generous donation."], ["🏠", "shelter", "The shelter helps homeless people."], ["👨‍👩‍👧", "families in need", "We collect food for families in need."], ["🙏", "generous", "It's very generous of you to help."], ["🤝", "make a difference", "Small actions can make a difference."]]}, {"t": "Social problems", "ar": "مشاكل المجتمع", "items": [["🏚️", "poverty", "Poverty is still a big problem."], ["🛏️", "homeless", "Thousands of people are homeless."], ["🍞", "hunger", "The charity fights hunger in villages."], ["🧒", "orphan", "The orphans need love and education."], ["♿", "disability", "People with disabilities need equal chances."], ["🩺", "healthcare", "Many villages have poor healthcare."], ["🎓", "education", "Education is the key to ending poverty."], ["😔", "lonely", "Many elderly people feel lonely."]]}, {"t": "Charity work", "ar": "العمل الخيري", "items": [["💸", "raise money", "We raised money for the hospital."], ["📦", "fundraising", "The school held a fundraising event."], ["🧑‍🤝‍🧑", "community", "Volunteers make the community stronger."], ["🎯", "cause", "Animal rights is an important cause."], ["🌱", "non-profit", "It is a non-profit organisation."], ["📋", "campaign", "They started a campaign to plant trees."], ["⏳", "spare time", "I volunteer in my spare time."], ["😊", "rewarding", "Volunteering is very rewarding."]]}], "talk": [{"title": "Let's Talk · Student A", "ar": "الطالب A", "list": [["Have you ever volunteered? What did you do?", "اتطوعت قبل كده؟ عملت إيه؟", "Yes, I helped clean a beach last summer."], ["Why do people volunteer without getting paid?", "ليه الناس بتتطوع من غير مقابل؟", "Because it makes them feel useful and happy."], ["Which cause is most important to you?", "أنهي قضية أهم بالنسبالك؟", "Education for poor children."], ["Is it better to donate money or time? Why?", "أحسن تتبرع بفلوس ولا بوقت؟", "Time, because you see the difference yourself."], ["What will you have achieved by the time you are 30?", "هتكون حققت إيه لما توصل ٣٠ سنة؟", "I'll have finished my master's degree."]]}, {"title": "Let's Talk · Student B", "ar": "الطالب B", "list": [["Should volunteering be part of the school curriculum?", "التطوع لازم يبقى جزء من المنهج المدرسي؟", "Yes, it teaches responsibility."], ["Do you trust charities to use donations well?", "بتثق في الجمعيات إنها تستخدم التبرعات صح؟", "Some of them. I always check first."], ["How do people in your community help each other?", "الناس في منطقتك بتساعد بعض إزاي؟", "During Ramadan, everyone shares food."], ["What social problem would you like to solve?", "نفسك تحل أنهي مشكلة في المجتمع؟", "Homelessness, because everyone deserves a home."], ["How can young people help without money?", "الشباب يقدروا يساعدوا إزاي من غير فلوس؟", "By teaching, visiting elderly people or cleaning parks."]]}], "grammar": {"title": "Future Perfect & Future Perfect Continuous", "ar": "المستقبل التام — will have done / will have been doing", "blocks": [{"type": "intro", "en": "We imagine ourselves at a point in the future and look BACK. The Future Perfect shows what will be finished by then; the Future Perfect Continuous shows how long something will have been happening until then.", "ar": "بنتخيل نفسنا في وقت في المستقبل ونبص لورا. Future Perfect = الحاجة هتكون خلصت قبل الوقت ده. Future Perfect Continuous = الحاجة هيكون بقالها قد إيه مستمرة لحد الوقت ده."}, {"type": "big", "items": [{"v": "will have + p.p.", "p": "Future Perfect — finished before a future time", "c": 1, "eg": ["By six o'clock, we'll have packed 500 boxes.", "By next summer, they will have raised enough money.", "I won't have finished my project by Friday."]}, {"v": "will have been + -ing", "p": "Future Perfect Continuous — duration until a future time", "c": 2, "eg": ["By the end of this month, I'll have been volunteering for two years.", "In June, she will have been teaching for ten years.", "By 9 p.m., we'll have been working for twelve hours!"]}]}, {"type": "table", "title": "⏱️ Key time expressions", "head": ["Expression", "Example"], "rows": [["by + time", "By 2030, we'll have planted a million trees."], ["by the time + present simple", "By the time you arrive, we will have finished."], ["by the end of…", "By the end of the year, I will have saved $500."], ["for + period (FPC)", "By May, I will have been studying English for 5 years."], ["in + time", "In two years, they will have built the school."]]}, {"type": "table", "title": "➕ ➖ ❓ Forms", "head": ["", "Future Perfect", "Future Perfect Continuous"], "rows": [["➕", "She will have finished.", "She will have been working."], ["➖", "She won't have finished.", "She won't have been working."], ["❓", "Will she have finished?", "How long will she have been working?"]]}, {"type": "tip", "en": "After 'by the time', use the PRESENT simple, not 'will': By the time you will arrive ✖ → By the time you arrive ✔. Stative verbs (know, like, own) don't use the continuous form: I'll have been knowing ✖ → I'll have known ✔.", "ar": "بعد by the time استخدم المضارع البسيط مش will. والأفعال الحالية زي know وlike مش بتيجي continuous: I'll have known."}]}, "exercises": [{"type": "mcq", "title": "Future Perfect (Continuous) — 10 MCQs", "ar": "اختار الصح", "speak": true, "items": [{"q": "By six o'clock, we ___ all the boxes.", "o": ["will have packed", "will pack", "have packed", "will be packed"], "a": 0}, {"q": "By the end of this month, I ___ here for two years.", "o": ["will have been volunteering", "will volunteer", "am volunteering", "will have volunteer"], "a": 0}, {"q": "By next summer, they ___ enough money to open the centre.", "o": ["will have raised", "will raise", "raised", "have been raising"], "a": 0}, {"q": "By the time you ___, we will have finished.", "o": ["arrive", "will arrive", "arrived", "will have arrived"], "a": 0}, {"q": "I ___ my project by Friday. I need more time.", "o": ["won't have finished", "won't finish yet", "haven't finished", "will not finishing"], "a": 0}, {"q": "In June, she ___ English for ten years.", "o": ["will have been teaching", "will teach", "teaches", "will have taught being"], "a": 0}, {"q": "How many trees ___ by 2030?", "o": ["will they have planted", "they will have planted", "will they plant have", "have they planted"], "a": 0}, {"q": "By 9 p.m., we'll have been ___ for twelve hours!", "o": ["working", "worked", "work", "works"], "a": 0}, {"q": "Which sentence is correct?", "o": ["By next year, I'll have known her for ten years.", "By next year, I'll have been knowing her for ten years.", "By next year, I will know her since ten years.", "By next year, I have known her for ten years."], "a": 0}, {"q": "Future Perfect Continuous focuses on ___.", "o": ["how long an action continues until a future time", "a finished past action", "a habit in the present", "a plan for tonight"], "a": 0}]}, {"type": "mcq", "title": "Finished or duration?", "ar": "خلص ولا مدة؟", "items": [{"q": "\"By 2030, we ___ 1,000 houses.\" (finished result)", "o": ["will have built", "will have been building"], "a": 0}, {"q": "\"By May, I ___ here for 3 years.\" (duration)", "o": ["will have been working", "will have worked being"], "a": 0}, {"q": "by the time + ___", "o": ["present simple", "will"], "a": 0}, {"q": "Stative verbs (know, own) use ___.", "o": ["Future Perfect", "Future Perfect Continuous"], "a": 0}, {"q": "\"By 10 p.m., she ___ for 8 hours.\" (duration)", "o": ["will have been studying", "will studying"], "a": 0}]}, {"type": "ord", "title": "Make sentences", "ar": "رتّب الكلمات", "items": [{"c": ["By six o'clock,", "we", "will have packed", "all the boxes"], "a": [0, 1, 2, 3]}, {"c": ["By June,", "I", "will have been volunteering", "for two years"], "a": [0, 1, 2, 3]}, {"c": ["By the time", "you arrive,", "we will have", "finished"], "a": [0, 1, 2, 3]}, {"c": ["They", "won't have", "raised", "enough money"], "a": [0, 1, 2, 3]}]}], "reading": {"title": "Why Helping Others Helps You", "ar": "ليه مساعدة الناس بتساعدك إنت", "g": "f", "lines": [["When we think about volunteering, we usually think about the people who receive help. But scientists have discovered that volunteers benefit too.", "لما بنفكر في التطوع، غالبًا بنفكر في الناس اللي بتاخد المساعدة. بس العلماء اكتشفوا إن المتطوعين كمان بيستفيدوا."], ["Studies show that people who volunteer regularly are often happier, less stressed and even healthier than those who don't.", "الدراسات بتوضح إن اللي بيتطوعوا بانتظام غالبًا أسعد وأقل توتر وحتى صحتهم أحسن من اللي مش بيتطوعوا."], ["One reason is something researchers call the \"helper's high\" — a warm, positive feeling that comes from doing something kind.", "من الأسباب حاجة الباحثين بيسموها \"نشوة المساعد\" — إحساس دافي وإيجابي بييجي من إنك تعمل حاجة لطيفة."], ["When we help others, our brains release chemicals that improve our mood and reduce stress.", "لما بنساعد غيرنا، المخ بيفرز مواد كيميائية بتحسن المزاج وبتقلل التوتر."], ["Volunteering also gives people a sense of purpose. Retired people, for example, often say that volunteering helps them feel useful again.", "التطوع كمان بيدي الناس إحساس بالهدف. المتقاعدين مثلًا كتير بيقولوا إن التطوع بيخليهم يحسوا إنهم مفيدين تاني."], ["For young people, it can be a great way to develop skills such as teamwork, leadership and communication — skills that employers value.", "وللشباب، ممكن يكون طريقة ممتازة لتطوير مهارات زي العمل الجماعي والقيادة والتواصل — مهارات أصحاب الشغل بيقدّروها."], ["It also helps people build new friendships and feel part of their community.", "وكمان بيساعد الناس يبنوا صداقات جديدة ويحسوا إنهم جزء من مجتمعهم."], ["Of course, volunteering shouldn't become another source of stress. Experts suggest choosing a cause you really care about and starting with just a few hours a month.", "طبعًا، التطوع مينفعش يتحول لمصدر توتر تاني. الخبراء بيقترحوا تختار قضية تهمك فعلًا وتبدأ بكام ساعة بس في الشهر."], ["Imagine yourself in five years. If you start today, you will have helped hundreds of people by then — and you will have changed yourself too.", "تخيل نفسك بعد ٥ سنين. لو بدأت النهارده، هتكون ساعدت مئات الناس — وهتكون غيرت نفسك كمان."]], "keys": [["📈", "benefit", "to get something good from something"], ["🌟", "helper's high", "the happy feeling you get from helping others"], ["🧠", "release", "to let something out"], ["🎯", "sense of purpose", "the feeling that your life has meaning"], ["👴", "retired", "no longer working because of age"], ["🧑‍🤝‍🧑", "community", "the people who live in one area"]], "quiz": [{"q": "What have scientists discovered about volunteers?", "o": ["They benefit too.", "They are always tired.", "They earn a lot of money."], "a": 0}, {"q": "What is the \"helper's high\"?", "o": ["a positive feeling from doing something kind", "a tall building", "a type of medicine"], "a": 0}, {"q": "What happens in our brains when we help others?", "o": ["They release chemicals that improve our mood.", "They stop working.", "They get smaller."], "a": 0}, {"q": "Why do retired people like volunteering?", "o": ["It helps them feel useful again.", "It pays well.", "It is easy."], "a": 0}, {"q": "Which skills can young people develop?", "o": ["teamwork, leadership and communication", "cooking only", "driving"], "a": 0}, {"q": "What do experts suggest?", "o": ["choosing a cause you care about and starting small", "volunteering every day", "never volunteering"], "a": 0}]}, "idioms": {"items": [["lend a hand", "To help someone.", "يمد إيده بالمساعدة", "Can you lend me a hand with these boxes?", "ممكن تساعدني في الكراتين دي؟"], ["give back", "To help the community that helped you.", "يرد الجميل للمجتمع", "After he became successful, he wanted to give back to his village.", "بعد ما نجح، كان عايز يرد الجميل لقريته."], ["go the extra mile", "To do more than what is expected.", "يعمل أكتر من المطلوب", "Our volunteers always go the extra mile for the children.", "المتطوعين بتوعنا دايمًا بيعملوا أكتر من المطلوب عشان الأطفال."], ["from the bottom of my heart", "Very sincerely.", "من كل قلبي", "Thank you from the bottom of my heart.", "شكرًا من كل قلبي."]], "quiz": [{"q": "The boxes are heavy. Could you ___?", "o": ["lend a hand", "give back", "go the extra mile", "from the bottom"], "a": 0}, {"q": "She stayed until midnight to help. She always ___.", "o": ["goes the extra mile", "lends back", "gives a hand", "bottom of heart"], "a": 0}, {"q": "\"I want to give back to my community\" means…", "o": ["help the community that helped me", "return something I bought", "leave the community", "take money back"], "a": 0}, {"q": "\"Thank you from the bottom of my heart\" means…", "o": ["thank you very sincerely", "my heart hurts", "thank you a little", "goodbye"], "a": 0}]}, "phrasal": {"items": [["help out", "To help someone, especially in a busy situation.", "يساعد / يمد إيده", "I'm happy to help out at the food bank.", "مبسوط إني أساعد في بنك الطعام."], ["sign up", "To register for an activity.", "يسجّل في نشاط", "Can I sign up as a regular volunteer?", "ينفع أسجّل متطوع بشكل منتظم؟"], ["set up", "To start an organisation or project.", "يأسس / يعمل مشروع", "They want to set up a free learning centre.", "عايزين يأسسوا مركز تعليم مجاني."], ["give away", "To give something for free.", "يدّي حاجة ببلاش", "She gave away all her old books to the library.", "ادّت كل كتبها القديمة للمكتبة ببلاش."]], "quiz": [{"q": "More than 50 students ___ for the beach clean-up.", "o": ["signed up", "gave away", "set up", "helped out"], "a": 0}, {"q": "My grandfather ___ a small school in his village in 1990.", "o": ["set up", "signed up", "gave away", "helped out"], "a": 0}, {"q": "We're ___ free meals to anyone who needs one.", "o": ["giving away", "setting up", "signing up", "helping"], "a": 0}, {"q": "My neighbour is old, so I ___ with her shopping.", "o": ["help out", "sign up", "set up", "give away"], "a": 0}]}, "slang": {"items": [["I'm down", "I agree / I'm happy to join.", "أنا معاك / موافق", "Volunteering on Saturday? I'm down!", "تطوع يوم السبت؟ أنا معاكم!", "للصحاب — رد سريع"], ["lowkey", "A little; secretly; not openly.", "بيني وبينك / شوية", "I lowkey loved helping at the shelter.", "بيني وبينك، حبيت جدًا المساعدة في الملجأ.", "من سلانج الشباب الحديث"], ["wholesome", "Kind, positive and makes you feel good.", "لطيف ويفرّح القلب", "That video of the kids helping the old man is so wholesome.", "فيديو الأطفال وهما بيساعدوا الراجل الكبير لطيف جدًا.", "بتتقال كتير على السوشيال ميديا"], ["hit me up", "Contact me.", "كلمني / ابعتلي", "If you need volunteers, hit me up.", "لو محتاجين متطوعين، كلمني.", "للصحاب — مش للإيميلات الرسمية"], ["good vibes", "A positive feeling or atmosphere.", "طاقة حلوة", "The charity event had such good vibes.", "الحفلة الخيرية كان فيها طاقة حلوة جدًا.", "عادي جدًا بين الصحاب"]], "quiz": [{"q": "\"Want to help at the food bank?\" — \"___!\"", "o": ["I'm down", "Hit me", "Lowkey", "Wholesome"], "a": 0}, {"q": "\"Hit me up\" means…", "o": ["contact me", "hit me", "wake me up", "pick me up"], "a": 0}, {"q": "A video of a kid sharing his lunch is ___.", "o": ["wholesome", "sus", "shady", "busted"], "a": 0}, {"q": "\"I lowkey want to volunteer every weekend.\" means…", "o": ["I secretly / a little want to", "I don't want to", "I want to sleep", "I hate volunteering"], "a": 0}]}, "story": {"title": "The Thousand-Book Library", "ar": "مكتبة الألف كتاب", "g": "f", "lines": [["When twelve-year-old Ziad visited his grandmother's village, he noticed something sad: the children had no books to read.", "لما زياد ابن ١٢ سنة زار قرية جدته، لاحظ حاجة تزعّل: الأطفال معندهمش كتب يقروها."], ["\"By the time I come back next summer,\" he promised, \"this village will have its own library.\"", "\"لما أرجع الصيف الجاي،\" وعد، \"القرية دي هيبقى عندها مكتبتها.\""], ["Back in Cairo, he set up a small campaign. He asked his classmates to give away books they had already read.", "لما رجع القاهرة، عمل حملة صغيرة. طلب من زمايله في الفصل يدّوا الكتب اللي قروها."], ["At first, only a few people helped out. But then his teacher shared the idea online, and it went viral.", "في الأول، كام واحد بس ساعدوا. بس بعدين المدرسة بتاعته نشرت الفكرة أونلاين، وانتشرت جدًا."], ["Boxes of books arrived every day — from schools, families, and even a famous writer.", "كراتين كتب كانت بتوصل كل يوم — من مدارس وعيلات وحتى كاتب مشهور."], ["\"If this continues,\" Ziad told his mum, \"by June we'll have collected a thousand books!\"", "\"لو ده فضل كده،\" قال زياد لمامته، \"مع يونيو هنكون جمعنا ألف كتاب!\""], ["Local carpenters volunteered to build shelves, and a painter decorated the walls for free.", "نجارين من المنطقة اتطوعوا يعملوا رفوف، ورسّام زيّن الحيطان ببلاش."], ["The next summer, Ziad returned to the village. A bright little room was full of children, all reading quietly.", "الصيف اللي بعده، زياد رجع القرية. أوضة صغيرة منورة كانت مليانة أطفال، كلهم بيقروا في هدوء."], ["A girl ran up to him and said, \"Thank you from the bottom of my heart. I've read twenty books already!\"", "بنت جريت عليه وقالت: \"شكرًا من كل قلبي. أنا قريت ٢٠ كتاب خلاص!\""], ["Ziad smiled. He had kept his promise — and he had learned that one small idea can change a whole village.", "زياد ابتسم. كان وفّى بوعده — واتعلم إن فكرة صغيرة ممكن تغيّر قرية كاملة."]], "quiz": [{"q": "What did Ziad notice in the village?", "o": ["The children had no books.", "There was no water.", "The school was closed."], "a": 0}, {"q": "What did he promise?", "o": ["The village would have its own library.", "He would move to the village.", "He would write a book."], "a": 0}, {"q": "What happened when his teacher shared the idea online?", "o": ["It went viral.", "Nobody saw it.", "The school closed."], "a": 0}, {"q": "Who built the shelves?", "o": ["local carpenters", "Ziad's classmates", "a famous writer"], "a": 0}, {"q": "What did Ziad learn?", "o": ["One small idea can change a whole village.", "Books are expensive.", "Villages are boring."], "a": 0}]}, "challenge": {"title": "Make a Difference", "ar": "اعمل فرق — جاوب وسجّل", "qs": ["If you could start a charity, what cause would it support?", "Describe a time when you helped someone. How did you feel?", "By the time you are 40, what will you have done to help your community?", "Should rich people be expected to give more to charity?", "Is it better to help people in your country or around the world? Why?", "What can schools do to encourage students to volunteer?", "How long will you have been studying English by the end of this year?", "Is helping animals as important as helping people?", "What is the most \"wholesome\" thing you have seen recently?", "Plan a one-day volunteer event. What will you have achieved by the end of the day?"]}, "games": {"pairs": [["🤲", "volunteer"], ["💰", "donate"], ["🏚️", "poverty"], ["🏠", "shelter"], ["🎯", "cause"], ["💸", "raise money"]], "spell": [["❤️", "charity"], ["🙏", "generous"], ["🍞", "hunger"], ["🧒", "orphan"], ["📋", "campaign"], ["🧑‍🤝‍🧑", "community"], ["😊", "rewarding"], ["🛏️", "homeless"]], "speed": [["By six, we'll have packed 500 boxes.", true], ["By the time you will arrive, we will finish.", false], ["By June, I'll have been volunteering for two years.", true], ["They will have raise the money.", false], ["I won't have finished by Friday.", true], ["By next year, I'll have been knowing him for 10 years.", false], ["How long will you have been working here?", true], ["By 2030, they will have built the school.", true], ["By tonight, she will has finished.", false], ["In June, he will have been teaching for 20 years.", true], ["A volunteer works without pay.", true], ["To donate means to take money.", false], ["A shelter helps homeless people.", true], ["\"Lend a hand\" means to help.", true], ["\"Sign up\" means to register for an activity.", true], ["\"Give away\" means to sell something.", false]]}, "test": {"pass": 60, "sections": [{"id": "voc", "title": "Vocabulary", "ar": "المفردات", "icon": "📚", "qs": [{"q": "A person who works for free to help others = a ___.", "o": ["volunteer", "victim", "manager"], "a": 0, "pic": "🤲"}, {"q": "To give money or things to help people = to ___.", "o": ["donate", "refuse", "deny"], "a": 0, "pic": "💰"}, {"q": "The state of being very poor = ___.", "o": ["poverty", "charity", "shelter"], "a": 0, "pic": "🏚️"}, {"q": "Giving you a good feeling = ___.", "o": ["rewarding", "lonely", "homeless"], "a": 0, "pic": "😊"}, {"q": "A child whose parents have died = an ___.", "o": ["orphan", "adult", "volunteer"], "a": 0, "pic": "🧒"}, {"q": "\"جمعية خيرية\" in English is…", "o": ["charity", "campaign", "cause"], "a": 0, "say": "Choose the correct word."}]}, {"id": "gra", "title": "Grammar", "ar": "القواعد", "icon": "📘", "qs": [{"q": "By 2030, we ___ a million trees.", "o": ["will have planted", "will plant", "planted"], "a": 0}, {"q": "By December, I ___ here for five years.", "o": ["will have been working", "will work", "am working"], "a": 0}, {"q": "By the time you ___, I will have left.", "o": ["come", "will come", "came"], "a": 0}, {"q": "She ___ her degree by next summer. She needs one more year.", "o": ["won't have finished", "won't finish already", "hasn't finished"], "a": 0}, {"q": "How long ___ English by the end of the year?", "o": ["will you have been studying", "will you study", "do you study"], "a": 0}, {"q": "Which is correct?", "o": ["By tomorrow, they'll have finished the project.", "By tomorrow, they'll have finish the project.", "By tomorrow, they have finished the project."], "a": 0}]}, {"id": "con", "title": "Conversation", "ar": "المحادثة", "icon": "💬", "qs": [{"q": "\"Can you lend me a hand?\" — Best answer:", "o": ["Sure! What do you need?", "Here is my hand.", "I have two hands."], "a": 0}, {"q": "\"How long have you been volunteering?\" — Best answer:", "o": ["By May, I'll have been doing it for a year.", "I am volunteer.", "Volunteering is free."], "a": 0}, {"q": "\"Want to help at the food bank this weekend?\" — Best answer:", "o": ["I'm down! What time?", "I am down the stairs.", "Food is good."], "a": 0}, {"q": "\"Thank you from the bottom of my heart.\" — Best answer:", "o": ["You're welcome. I'm happy to help.", "Is your heart OK?", "The bottom is low."], "a": 0}, {"q": "\"Will you have finished by six?\" — Best answer:", "o": ["Yes, I think so.", "Yes, I will finish yesterday.", "Six is a number."], "a": 0}, {"q": "\"Why do you volunteer?\" — Best answer:", "o": ["Because it makes me feel useful and happy.", "Because I am volunteer.", "Yes, I do."], "a": 0}]}, {"id": "rea", "title": "Reading", "ar": "القراءة", "icon": "📖", "passage": ["Hi, I'm Laila. I've been volunteering at an animal shelter since I was sixteen.", "Every Saturday, I help out by feeding the dogs and cleaning their rooms.", "By next March, I'll have been volunteering there for three years.", "Our shelter is trying to raise money for a new clinic. By the end of the year, we will have collected enough to build it.", "Volunteering is very rewarding. The dogs always make me smile!"], "qs": [{"q": "Where does Laila volunteer?", "o": ["at an animal shelter", "at a hospital", "at a school"], "a": 0}, {"q": "What does she do every Saturday?", "o": ["feeds the dogs and cleans their rooms", "sells food", "teaches children"], "a": 0}, {"q": "How long will she have been volunteering by next March?", "o": ["three years", "three months", "sixteen years"], "a": 0}, {"q": "What is the shelter raising money for?", "o": ["a new clinic", "a new car", "a party"], "a": 0}, {"q": "How does volunteering make Laila feel?", "o": ["It makes her smile.", "It makes her tired.", "It makes her angry."], "a": 0}]}, {"id": "wri", "title": "Writing", "ar": "الكتابة", "icon": "✍️", "writing": true, "prompt": "Write about a charity project you would like to start (70–100 words). What will you have achieved in five years? Use the Future Perfect and Future Perfect Continuous.", "promptAr": "اكتب عن مشروع خيري نفسك تعمله (٧٠–١٠٠ كلمة). هتكون حققت إيه بعد ٥ سنين؟ استخدم will have done و will have been doing.", "checks": [["🤲", "Charity words", "x", "\\b(charity|volunteer|volunteers|volunteering|donate|donation|help|community|poverty|raise|cause|families)\\b"], ["🔮", "Future Perfect", "x", "\\b(will|won't|'ll)\\s+have\\s+\\w+(ed|en|wn|ne|ght|lt|nt|ade|ot|un|ung|ilt)\\b"], ["⏳", "Future Perfect Continuous", "x", "\\b(will|won't|'ll)\\s+have\\s+been\\s+\\w+ing\\b"], ["💬", "At least 70 words", "len70"]]}]}, "watch": [{"yt": "Kmc7TtKkTs4", "title": "Is Being Kind Good for You?", "ar": "هل اللطف مفيد ليك؟ — 6 Minute English", "by": "BBC Learning English", "lines": [["When was the last time you did something kind for someone else? I gave my mum flowers last week.", "آخر مرة عملت حاجة لطيفة لحد كانت إمتى؟ أنا اديت مامتي ورد الأسبوع اللي فات."], ["It felt good knowing I had made her happy.", "كان إحساس حلو إني عارفة إني فرحتها."], ["We feel just as good being kind to someone else as when someone is kind to us.", "بنحس بنفس السعادة لما نكون لطيفين مع حد زي لما حد يكون لطيف معانا."], ["A random act of kindness is a small, everyday thing people do to help others, like helping a stranger cross the road.", "فعل اللطف العشوائي حاجة صغيرة الناس بتعملها كل يوم عشان تساعد غيرها، زي مساعدة حد غريب يعدّي الشارع."], ["When we are kind to others, the parts of our brain that make us feel rewarded become active.", "لما بنكون لطيفين مع غيرنا، أجزاء المخ اللي بتخلينا نحس بالمكافأة بتشتغل."], ["Scientists call this pleasant feeling of happiness \"a warm glow\".", "العلماء بيسموا إحساس السعادة اللطيف ده \"توهج دافي\"."], ["For some people, being kind seems counter-intuitive, because giving something away means losing it.", "لبعض الناس، اللطف شكله عكس المنطق، لأن إنك تدّي حاجة معناه إنك تخسرها."], ["But for our brain, being kind feels as good as eating something yummy.", "بس بالنسبة للمخ، اللطف إحساسه حلو زي ما تاكل حاجة لذيذة."], ["Some people believe politics should be based on compassion — a strong wish to help those who are suffering.", "في ناس شايفين إن السياسة لازم تقوم على التعاطف — رغبة قوية في مساعدة اللي بيعانوا."], ["Kindness is sometimes dismissed as fluffy — soft and not serious.", "اللطف أحيانًا بيتشاف إنه حاجة ناعمة ومش جدية."], ["But in fact, acting with compassion is not easy. It takes courage.", "بس في الحقيقة، إنك تتصرف بتعاطف مش سهل. ده محتاج شجاعة."], ["In a global survey, the number one random act of kindness was… giving someone a smile.", "في استطلاع عالمي، أول فعل لطف عشوائي كان… إنك تدّي حد ابتسامة."]], "words": ["kindness", "random act of kindness", "stranger", "benefits", "reward", "warm glow", "counter-intuitive", "yummy", "compassion", "suffering", "fluffy", "courage"], "quiz": [{"q": "What did Sam give her mum?", "o": ["flowers", "a hug", "a cake"], "a": 0}, {"q": "What is a \"random act of kindness\"?", "o": ["a small everyday thing to help others", "a big donation", "a type of game"], "a": 0}, {"q": "What happens in the brain when we are kind?", "o": ["The reward parts become active.", "It stops working.", "We feel sad."], "a": 0}, {"q": "What is \"a warm glow\"?", "o": ["a pleasant feeling of happiness", "a hot day", "a type of light"], "a": 0}, {"q": "What does acting with compassion take, according to Jennifer?", "o": ["courage", "money", "time only"], "a": 0}, {"q": "What was the number one random act of kindness?", "o": ["giving someone a smile", "giving someone a hug", "listening to someone"], "a": 0}]}]}, "4": {"n": 4, "title": "Adventure and Risk-Taking", "ar": "المغامرة والمخاطرة — Mixed Conditionals", "icon": "🪂", "cover": "img/b2/u4.jpg", "intro": "اتكلم عن المغامرات والرياضات الخطيرة واختيارات المخاطرة، واستخدم الـ Mixed Conditionals عشان تربط الماضي بالحاضر: لو كنت عملت كده زمان، كنت هبقى كده دلوقتي.", "videos": [{"id": "b2v4", "title": "The Skydive", "ar": "القفز بالمظلة — يوسف ومريم", "src": "video/b2/u4v1.mp4", "poster": "img/b2/u4v1.jpg", "sp": {"a": {"n": "Mariam", "g": "f"}, "b": {"n": "Youssef", "g": "m"}}, "lines": [["a", "Youssef! I saw your photos. You actually went skydiving? Are you crazy?", "يوسف! شفت صورك. إنت فعلًا نطيت بالمظلة؟ إنت مجنون؟"], ["b", "Maybe a little! It was on my bucket list for years, so I finally took the plunge.", "يمكن شوية! كانت في قايمة أحلامي من سنين، فأخيرًا خدت الخطوة."], ["a", "Weren't you terrified when you jumped out of the plane?", "مكنتش مرعوب لما نطيت من الطيارة؟"], ["b", "Honestly, I almost chickened out at the last minute. But my instructor said, 'Trust the parachute and enjoy the view.'", "بصراحة، كنت هتراجع في آخر لحظة. بس المدرب قالي: \"اتق في الباراشوت واستمتع بالمنظر.\""], ["a", "I could never do that. If I were braver, I would have tried bungee jumping in Dubai last year.", "أنا عمري ما أقدر أعمل كده. لو كنت أشجع، كنت جربت البانجي جمبينج في دبي السنة اللي فاتت."], ["b", "It's not about being brave. If I hadn't started with small challenges, I wouldn't be so confident now.", "المسألة مش شجاعة. لو مكنتش بدأت بتحديات صغيرة، مكنتش هبقى واثق كده دلوقتي."], ["a", "Small challenges like what?", "تحديات صغيرة زي إيه؟"], ["b", "Rock climbing, hiking in Sinai, swimming in the open sea. Each one pushed me out of my comfort zone.", "تسلق الصخور، والمشي في سيناء، والعوم في البحر المفتوح. كل واحدة خرجتني من منطقة الراحة بتاعتي."], ["a", "But isn't it risky? You could get seriously injured.", "بس مش خطر؟ ممكن تتعور جامد."], ["b", "Every adventure has some risk, but we follow strict safety rules. If the instructors weren't so experienced, I would never have jumped.", "كل مغامرة فيها مخاطرة، بس إحنا بنمشي على قواعد أمان صارمة. لو المدربين مكانوش خبرة كده، عمري ما كنت هنط."], ["a", "OK, you've convinced me. Maybe I'll start with something smaller — like a zip line?", "خلاص، إقنعتني. يمكن أبدأ بحاجة أصغر — زي الزيب لاين؟"], ["b", "Perfect! Life begins at the end of your comfort zone. Let's go next weekend!", "تمام! الحياة بتبدأ عند آخر منطقة الراحة بتاعتك. يلا نروح الويك إند الجاي!"]], "quiz": [{"q": "What did Youssef do?", "o": ["He went skydiving.", "He went bungee jumping.", "He climbed Everest."], "a": 0}, {"q": "What almost happened at the last minute?", "o": ["He almost chickened out.", "The plane broke down.", "He lost his phone."], "a": 0}, {"q": "Why is Youssef confident now?", "o": ["because he started with small challenges", "because he is rich", "because he never felt afraid"], "a": 0}, {"q": "Which small challenges did he try?", "o": ["rock climbing, hiking and open-sea swimming", "chess and reading", "cooking"], "a": 0}, {"q": "What will Mariam try first?", "o": ["a zip line", "skydiving", "shark diving"], "a": 0}], "fill": [[1, "bucket list"], [1, "took the plunge"], [2, "terrified"], [3, "chickened out"], [3, "parachute"], [4, "braver"], [5, "confident"], [7, "comfort zone"], [8, "risky"], [8, "injured"], [9, "safety"], [9, "experienced"]]}], "vocab": [{"t": "Adventure", "ar": "المغامرة", "items": [["🪂", "skydiving", "Skydiving is on my bucket list."], ["🧗", "rock climbing", "Rock climbing needs strong arms."], ["🪢", "bungee jumping", "Bungee jumping is terrifying!"], ["🏔️", "expedition", "They went on an expedition to the Arctic."], ["🥾", "hiking", "We went hiking in Sinai."], ["🌊", "scuba diving", "Scuba diving in the Red Sea is amazing."], ["📋", "bucket list", "Visiting Japan is on my bucket list."], ["🌄", "breathtaking", "The view from the top was breathtaking."]]}, {"t": "Risk & danger", "ar": "المخاطرة والخطر", "items": [["⚠️", "risky", "Riding without a helmet is risky."], ["🎲", "take a risk", "Sometimes you need to take a risk."], ["🛡️", "safety", "Safety always comes first."], ["🤕", "injured", "He was injured while climbing."], ["🪖", "helmet", "Always wear a helmet."], ["⚡", "adrenaline", "I felt the adrenaline when I jumped."], ["😱", "terrified", "I was terrified of the height."], ["🧯", "emergency", "In an emergency, stay calm."]]}, {"t": "Personality & feelings", "ar": "الشخصية والمشاعر", "items": [["🦁", "brave", "You have to be brave to go diving with sharks."], ["🙈", "cautious", "My mum is a very cautious driver."], ["🔥", "thrill", "He loves the thrill of speed."], ["🎢", "thrill-seeker", "Thrill-seekers love extreme sports."], ["🛋️", "comfort zone", "Step out of your comfort zone."], ["💪", "confident", "She felt confident after the course."], ["🤔", "reckless", "Driving that fast is reckless."], ["🏅", "challenge", "The marathon was a big challenge."]]}], "talk": [{"title": "Let's Talk · Student A", "ar": "الطالب A", "list": [["What's the most adventurous thing you've ever done?", "إيه أجرأ حاجة عملتها في حياتك؟", "I swam with dolphins in Hurghada."], ["What's on your bucket list?", "إيه اللي في قايمة أحلامك؟", "Seeing the Northern Lights."], ["Are you a thrill-seeker or a cautious person?", "إنت بتحب الإثارة ولا حذر؟", "I'm cautious, but I like small adventures."], ["Why do some people love dangerous sports?", "ليه في ناس بتحب الرياضات الخطيرة؟", "They love the adrenaline."], ["If you had been braver as a child, what would you be doing now?", "لو كنت أشجع وإنت صغير، كنت هتعمل إيه دلوقتي؟", "I'd probably be a professional diver."]]}, {"title": "Let's Talk · Student B", "ar": "الطالب B", "list": [["Should parents let teenagers do extreme sports?", "الأهل يسيبوا المراهقين يعملوا رياضات خطيرة؟", "Yes, with proper training and safety."], ["Is taking risks important for success?", "المخاطرة مهمة للنجاح؟", "Yes, successful people usually take smart risks."], ["What is the difference between being brave and being reckless?", "إيه الفرق بين الشجاعة والتهور؟", "Brave people think about safety; reckless people don't."], ["Would you travel alone to a country you know nothing about?", "تسافر لوحدك لبلد متعرفش عنها حاجة؟", "Maybe, if I learned the language first."], ["When did you last step out of your comfort zone?", "آخر مرة خرجت من منطقة الراحة كانت إمتى؟", "When I gave a presentation in English."]]}], "grammar": {"title": "Mixed Conditionals", "ar": "الـ Mixed Conditionals — بنربط الماضي بالحاضر", "blocks": [{"type": "intro", "en": "Mixed conditionals mix two different times. Usually, an unreal PAST situation has a result in the PRESENT — or an unreal PRESENT situation explains a PAST result.", "ar": "الـ Mixed Conditional بيخلط زمنين. غالبًا حاجة ماحصلتش في الماضي ونتيجتها في الحاضر — أو حاجة مش حقيقية دلوقتي بتفسّر نتيجة في الماضي."}, {"type": "big", "items": [{"v": "If + had + p.p., would + verb (now)", "p": "past condition → present result", "c": 1, "eg": ["If I hadn't started with small challenges, I wouldn't be so confident now.", "If she had taken the job, she would be living in Dubai now.", "If we had left earlier, we wouldn't be stuck in traffic."]}, {"v": "If + past simple, would have + p.p.", "p": "present situation → past result", "c": 2, "eg": ["If I were braver, I would have tried bungee jumping last year.", "If he weren't so cautious, he would have gone skydiving with us.", "If I spoke French, I would have understood the guide."]}]}, {"type": "table", "title": "📋 Compare", "head": ["Type", "Structure", "Example"], "rows": [["Second", "If + past, would + verb", "If I were brave, I would jump."], ["Third", "If + had p.p., would have p.p.", "If I had been brave, I would have jumped."], ["Mixed (past → now)", "If + had p.p., would + verb", "If I had trained, I would be fit now."], ["Mixed (now → past)", "If + past, would have p.p.", "If I weren't afraid of heights, I would have climbed it."]]}, {"type": "uses", "title": "💡 Real-life examples", "ar": "أمثلة من الحياة", "items": [["🎓", "past choice → present life", "If I had studied medicine, I would be a doctor now.", "كنت هبقى دكتور دلوقتي"], ["🗺️", "past mistake → present problem", "If I hadn't lost the map, we wouldn't be lost.", "مكناش هنبقى تايهين"], ["😨", "personality → past result", "If I weren't scared of water, I would have gone diving.", "كنت غطست"], ["💪", "general truth → past", "If she were less busy, she would have come.", "كانت جت"]]}, {"type": "tip", "en": "Look at the TIME words: 'now', 'today' → would + verb; 'yesterday', 'last year' → would have + p.p. Never use 'would' in the if-clause.", "ar": "بص على كلمات الوقت: now / today ← would + فعل، yesterday / last year ← would have + p.p. ومتحطش would بعد if أبدًا."}]}, "exercises": [{"type": "mcq", "title": "Mixed Conditionals — 10 MCQs", "ar": "اختار الصح", "speak": true, "items": [{"q": "If I hadn't started with small challenges, I ___ so confident now.", "o": ["wouldn't be", "wouldn't have been", "won't be", "am not"], "a": 0}, {"q": "If I were braver, I ___ bungee jumping last year.", "o": ["would have tried", "would try", "will try", "tried"], "a": 0}, {"q": "If she had taken the job in Dubai, she ___ there now.", "o": ["would be living", "would have lived", "will live", "lived"], "a": 0}, {"q": "If we ___ the map, we wouldn't be lost now.", "o": ["hadn't lost", "didn't lose", "wouldn't lose", "haven't lost"], "a": 0}, {"q": "If he weren't so cautious, he ___ skydiving with us yesterday.", "o": ["would have gone", "would go", "will go", "had gone"], "a": 0}, {"q": "If I had studied harder at school, I ___ a better job now.", "o": ["would have", "would have had", "will have", "had"], "a": 0}, {"q": "If I ___ afraid of heights, I would have climbed the tower.", "o": ["weren't", "hadn't been", "wouldn't be", "am not"], "a": 0}, {"q": "If you had worn a helmet, you ___ in hospital now.", "o": ["wouldn't be", "wouldn't have been", "won't be", "aren't"], "a": 0}, {"q": "Which sentence is correct?", "o": ["If I had trained, I would be fit now.", "If I would train, I had been fit now.", "If I trained, I would have be fit now.", "If I had train, I would be fit now."], "a": 0}, {"q": "\"If I spoke French, I would have understood the guide.\" means…", "o": ["I don't speak French, so I didn't understand.", "I speak French and I understood.", "I will learn French.", "The guide spoke Arabic."], "a": 0}]}, {"type": "mcq", "title": "Which time?", "ar": "أنهي زمن؟", "items": [{"q": "\"…, I would be rich NOW.\" → the result is ___", "o": ["present", "past"], "a": 0}, {"q": "\"…, I would have gone YESTERDAY.\" → the result is ___", "o": ["past", "present"], "a": 0}, {"q": "If I ___ (be) taller, I would have joined the basketball team.", "o": ["were", "had been"], "a": 0}, {"q": "If I ___ (not eat) so much, I wouldn't feel sick now.", "o": ["hadn't eaten", "didn't eat"], "a": 0}, {"q": "Mixed conditionals mix ___.", "o": ["two different times", "two languages"], "a": 0}]}, {"type": "ord", "title": "Make sentences", "ar": "رتّب الكلمات", "items": [{"c": ["If I", "had trained harder,", "I would be", "fitter now"], "a": [0, 1, 2, 3]}, {"c": ["If I", "were braver,", "I would have", "jumped"], "a": [0, 1, 2, 3]}, {"c": ["If we", "hadn't lost the map,", "we wouldn't be", "lost now"], "a": [0, 1, 2, 3]}, {"c": ["If she", "weren't so busy,", "she would have", "come"], "a": [0, 1, 2, 3]}]}], "reading": {"title": "Why Do We Love Danger?", "ar": "ليه بنحب الخطر؟", "g": "m", "lines": [["Every year, thousands of people pay a lot of money to jump out of planes, climb frozen mountains or swim with sharks. Why would anyone choose to be afraid?", "كل سنة، آلاف الناس بيدفعوا فلوس كتير عشان ينطوا من طيارات، أو يتسلقوا جبال متجمدة، أو يعوموا مع أسماك القرش. ليه حد يختار يخاف؟"], ["Psychologists say that the answer is partly in our brains. When we face danger, our body releases adrenaline, which makes our heart beat faster and gives us a rush of energy.", "علماء النفس بيقولوا إن الإجابة جزء منها في المخ. لما بنواجه خطر، الجسم بيفرز أدرينالين، وده بيخلي القلب يدق أسرع ويدينا دفعة طاقة."], ["After the danger passes, the brain rewards us with chemicals that make us feel happy and relaxed. For some people, this feeling is addictive.", "وبعد ما الخطر يعدّي، المخ بيكافئنا بمواد كيميائية بتخلينا نحس بسعادة واسترخاء. ولبعض الناس، الإحساس ده بيبقى إدمان."], ["Scientists also believe that people are born with different levels of \"sensation-seeking\". Thrill-seekers need more excitement to feel satisfied, while others feel stressed by even small risks.", "العلماء كمان شايفين إن الناس بتتولد بمستويات مختلفة من \"حب الإثارة\". محبين الإثارة محتاجين حماس أكتر عشان يحسوا بالرضا، وغيرهم بيتوتروا من أصغر مخاطرة."], ["But adventure is not only about chemicals. Many people say that facing their fears has made them stronger and more confident in everyday life.", "بس المغامرة مش بس مواد كيميائية. ناس كتير بيقولوا إن مواجهة مخاوفهم خلتهم أقوى وأكتر ثقة في الحياة العادية."], ["\"If I hadn't climbed Kilimanjaro,\" one climber said, \"I wouldn't believe in myself the way I do now.\"", "\"لو مكنتش طلعت كليمنجارو،\" قال متسلق، \"مكنتش هبقى مؤمن بنفسي بالشكل ده دلوقتي.\""], ["Of course, there is a difference between taking a smart risk and being reckless.", "طبعًا، في فرق بين إنك تاخد مخاطرة ذكية وإنك تبقى متهور."], ["Professional adventurers train for months, check the weather carefully and always have an emergency plan.", "المغامرين المحترفين بيتدربوا شهور، ويراجعوا الطقس بعناية، ويبقى عندهم دايمًا خطة طوارئ."], ["The goal is not to avoid fear, but to control it.", "الهدف مش إنك تتجنب الخوف، لكن إنك تتحكم فيه."], ["So, next time you feel your heart racing, remember: a little fear might be exactly what you need to grow.", "فالمرة الجاية لما تحس قلبك بيدق بسرعة، افتكر: شوية خوف يمكن يكونوا بالظبط اللي محتاجه عشان تكبر."]], "keys": [["⚡", "adrenaline", "a chemical that makes your heart beat faster in danger"], ["🎁", "reward", "to give something good in return"], ["🌀", "addictive", "making you want to do it again and again"], ["🎢", "sensation-seeking", "looking for exciting experiences"], ["🤪", "reckless", "doing dangerous things without thinking"], ["🧯", "emergency plan", "what to do if something goes wrong"]], "quiz": [{"q": "What happens when we face danger?", "o": ["Our body releases adrenaline.", "We fall asleep.", "Our heart stops."], "a": 0}, {"q": "How does the brain reward us after danger?", "o": ["with chemicals that make us feel happy", "with money", "with pain"], "a": 0}, {"q": "What is true about \"sensation-seeking\"?", "o": ["People are born with different levels of it.", "Everyone has the same level.", "It only exists in children."], "a": 0}, {"q": "What did the climber say about Kilimanjaro?", "o": ["Climbing it made him believe in himself.", "He hated it.", "He never reached the top."], "a": 0}, {"q": "What do professional adventurers do?", "o": ["train for months and have an emergency plan", "go without planning", "never check the weather"], "a": 0}, {"q": "What is the main goal, according to the text?", "o": ["to control fear, not avoid it", "to never feel afraid", "to take as many risks as possible"], "a": 0}]}, "idioms": {"items": [["take the plunge", "To finally decide to do something difficult or risky.", "ياخد الخطوة / يغامر", "After years of thinking about it, he finally took the plunge and went skydiving.", "بعد سنين من التفكير، أخيرًا خد الخطوة ونط بالمظلة."], ["push your luck", "To take too many risks when things are going well.", "يغامر زيادة عن اللزوم", "You've won three times already. Don't push your luck!", "إنت كسبت ٣ مرات خلاص. متغامرش زيادة!"], ["out of your comfort zone", "Doing something new and uncomfortable.", "برة منطقة الراحة", "Speaking in public took me out of my comfort zone.", "الكلام قدام الناس خرّجني برة منطقة الراحة."], ["live on the edge", "To live in an exciting and risky way.", "يعيش على الحافة / بيحب الخطر", "My cousin loves to live on the edge — he races motorbikes.", "ابن عمي بيحب يعيش على الحافة — بيسابق بالموتوسيكلات."]], "quiz": [{"q": "He finally ___ and moved to Canada alone.", "o": ["took the plunge", "pushed his luck", "lived on the edge", "comfort zone"], "a": 0}, {"q": "You got away with it once. Don't ___!", "o": ["push your luck", "take the plunge", "live the edge", "comfort zone"], "a": 0}, {"q": "\"Out of your comfort zone\" means…", "o": ["doing something new and uncomfortable", "sleeping on a sofa", "staying at home", "feeling relaxed"], "a": 0}, {"q": "Someone who loves racing cars and skydiving likes to ___.", "o": ["live on the edge", "push the plunge", "take the luck", "stay comfortable"], "a": 0}]}, "phrasal": {"items": [["take up", "To start a new hobby or activity.", "يبدأ هواية جديدة", "She took up rock climbing last year.", "بدأت تسلق الصخور السنة اللي فاتت."], ["chicken out", "To decide not to do something because you are afraid.", "يتراجع من الخوف", "I almost chickened out at the last minute.", "كنت هتراجع من الخوف في آخر لحظة."], ["set off", "To start a journey.", "ينطلق في رحلة", "We set off for the mountain at 4 a.m.", "انطلقنا للجبل الساعة ٤ الفجر."], ["back out", "To decide not to do something you agreed to do.", "ينسحب من اتفاق", "He backed out of the trip two days before we left.", "انسحب من الرحلة قبل ما نسافر بيومين."]], "quiz": [{"q": "I want to ___ a new sport this year — maybe surfing.", "o": ["take up", "chicken out", "set off", "back out"], "a": 0}, {"q": "He was going to jump, but he ___ at the last second.", "o": ["chickened out", "took up", "set off", "backed up"], "a": 0}, {"q": "The expedition ___ early in the morning.", "o": ["set off", "took up", "chickened out", "backed out"], "a": 0}, {"q": "She promised to come with us, but then she ___.", "o": ["backed out", "set off", "took up", "chickened up"], "a": 0}]}, "slang": {"items": [["YOLO", "You Only Live Once — so do it!", "إنت عايش مرة واحدة", "Skydiving? YOLO! Let's do it.", "نط بالمظلة؟ إحنا عايشين مرة واحدة! يلا.", "بهزار — بس متستخدمهاش كمبرر للتهور"], ["epic", "Amazing and impressive.", "أسطوري / جامد جدًا", "That trip to Sinai was epic!", "رحلة سيناء دي كانت أسطورية!", "شائعة جدًا بين الشباب"], ["hyped", "Very excited.", "متحمس جدًا", "I'm so hyped for the diving trip!", "أنا متحمس جدًا لرحلة الغطس!", "للصحاب"], ["send it", "Go for it with full energy (especially in sports).", "روح لها / اعملها بكل قوتك", "The jump looks scary, but just send it!", "النطة شكلها مرعبة، بس اعملها!", "سلانج رياضي"], ["sketchy", "Looks unsafe or not trustworthy.", "مش مضمون / شكله خطر", "That old rope looks sketchy. Don't use it.", "الحبل القديم ده شكله مش مضمون. متستخدموش.", "مهمة جدًا في الأمان!"]], "quiz": [{"q": "\"That bridge looks sketchy.\" means…", "o": ["It looks unsafe.", "It looks beautiful.", "It looks new.", "It looks like a drawing."], "a": 0}, {"q": "\"I'm so hyped!\" means…", "o": ["I'm very excited!", "I'm very tired!", "I'm very hungry!", "I'm angry!"], "a": 0}, {"q": "The concert was amazing. It was ___!", "o": ["epic", "sketchy", "YOLO", "send"], "a": 0}, {"q": "\"YOLO\" stands for…", "o": ["You Only Live Once", "Your Old Life Over", "You Owe Lots Of", "Yes Or Leave Out"], "a": 0}]}, "story": {"title": "The Last Hundred Metres", "ar": "آخر ميت متر", "g": "m", "lines": [["Tarek had always been afraid of heights. Even standing on a chair made his legs shake.", "طارق طول عمره بيخاف من الأماكن العالية. حتى الوقوف على كرسي كان بيخلي رجليه تترعش."], ["So when his friends invited him to climb Mount Sinai at night to watch the sunrise, he almost backed out.", "فلما صحابه عزموه يطلعوا جبل سيناء بالليل عشان يشوفوا الشروق، كان هينسحب."], ["\"If I don't go now,\" he thought, \"I'll regret it forever.\" So he took the plunge.", "\"لو مرحتش دلوقتي،\" فكّر، \"هندم طول عمري.\" فخد الخطوة."], ["They set off at two in the morning. The path was dark, rocky and steep.", "انطلقوا الساعة ٢ الفجر. الطريق كان ضلمة، ومليان صخور، وطالع لفوق."], ["After three hours, Tarek's legs were burning. With only a hundred metres left, he sat down and said, \"I can't do it.\"", "بعد ٣ ساعات، رجلين طارق كانوا مولعين. وفاضل ميت متر بس، قعد وقال: \"مش قادر.\""], ["His friend Hana sat next to him. \"If you had stopped at the beginning, I'd understand. But look how far you've come!\"", "صاحبته هنا قعدت جنبه. \"لو كنت وقفت في الأول، كنت هفهم. بس بص إنت وصلت لحد فين!\""], ["Tarek looked down. The lights of the village were tiny, far below. He couldn't believe he had climbed so high.", "طارق بص لتحت. نور القرية كان صغير جدًا، بعيد تحت. مكانش مصدق إنه طلع العلو ده كله."], ["Slowly, step by step, he climbed the last hundred metres.", "ببطء، خطوة خطوة، طلع آخر ميت متر."], ["When the sun appeared over the mountains, painting the sky orange and pink, Tarek had tears in his eyes.", "لما الشمس ظهرت فوق الجبال، ولونت السما برتقالي وبينك، عينين طارق دمعت."], ["Today, Tarek is a mountain guide. \"If I hadn't climbed that night,\" he says, \"I wouldn't be the person I am now.\"", "النهارده، طارق مرشد جبال. \"لو مكنتش طلعت الليلة دي،\" بيقول، \"مكنتش هبقى الشخص اللي أنا عليه دلوقتي.\""]], "quiz": [{"q": "What was Tarek afraid of?", "o": ["heights", "the dark", "water"], "a": 0}, {"q": "Why did they climb at night?", "o": ["to watch the sunrise", "because it was cooler only", "to see the stars"], "a": 0}, {"q": "What happened with a hundred metres left?", "o": ["He sat down and said he couldn't do it.", "He fell.", "He ran to the top."], "a": 0}, {"q": "How did Hana encourage him?", "o": ["She reminded him how far he had come.", "She carried him.", "She called a doctor."], "a": 0}, {"q": "What is Tarek's job today?", "o": ["a mountain guide", "a pilot", "a teacher"], "a": 0}]}, "challenge": {"title": "Into the Unknown", "ar": "المجهول — جاوب وسجّل", "qs": ["Describe the most exciting adventure you've had or would like to have.", "If you had been born in a different country, what adventures would you be doing now?", "Would you rather go to space or to the deepest part of the ocean? Why?", "When did you last chicken out of something? What happened?", "Is it worth risking your life for an adventure?", "What would you take on a one-week expedition into the desert?", "If you were braver, what would you have done last year?", "Should extreme sports be banned for people under 18?", "What did you learn from a time you stepped out of your comfort zone?", "What's one thing you will take up this year?"]}, "games": {"pairs": [["🪂", "skydiving"], ["🧗", "rock climbing"], ["⚡", "adrenaline"], ["🪖", "helmet"], ["📋", "bucket list"], ["🛋️", "comfort zone"]], "spell": [["⚠️", "risky"], ["🛡️", "safety"], ["🦁", "brave"], ["🙈", "cautious"], ["🤕", "injured"], ["🔥", "thrill"], ["🏅", "challenge"], ["😱", "terrified"]], "speed": [["If I had trained, I would be fit now.", true], ["If I would have trained, I am fit now.", false], ["If I were braver, I would have jumped.", true], ["If we hadn't lost the map, we wouldn't be lost.", true], ["If I had studied medicine, I will be a doctor now.", false], ["If he weren't so cautious, he would have come.", true], ["If she had taken the job, she would live in Dubai now.", true], ["If I was had money, I would bought it.", false], ["If you'd worn a helmet, you wouldn't be hurt now.", true], ["If I spoke French, I would have understood.", true], ["Adrenaline makes your heart beat faster.", true], ["A cautious person loves danger.", false], ["\"Chicken out\" means to stop because you are afraid.", true], ["\"Take the plunge\" means to decide to do something risky.", true], ["\"Sketchy\" means very safe.", false], ["A bucket list is a list of things to do in your life.", true]]}, "test": {"pass": 60, "sections": [{"id": "voc", "title": "Vocabulary", "ar": "المفردات", "icon": "📚", "qs": [{"q": "A list of things you want to do before you die = a ___.", "o": ["bucket list", "to-do list", "menu"], "a": 0, "pic": "📋"}, {"q": "Very careful to avoid danger = ___.", "o": ["cautious", "reckless", "brave"], "a": 0, "pic": "🙈"}, {"q": "The chemical your body releases in danger = ___.", "o": ["adrenaline", "helmet", "thrill"], "a": 0, "pic": "⚡"}, {"q": "Taking stupid risks without thinking = ___.", "o": ["reckless", "cautious", "confident"], "a": 0, "pic": "🤪"}, {"q": "Extremely beautiful (a view) = ___.", "o": ["breathtaking", "injured", "risky"], "a": 0, "pic": "🌄"}, {"q": "\"منطقة الراحة\" in English is…", "o": ["comfort zone", "safety zone", "free time"], "a": 0, "say": "Choose the correct word."}]}, {"id": "gra", "title": "Grammar", "ar": "القواعد", "icon": "📘", "qs": [{"q": "If I had saved money, I ___ a car now.", "o": ["would have", "would have had", "will have"], "a": 0}, {"q": "If she were more confident, she ___ for the job last week.", "o": ["would have applied", "would apply", "applied"], "a": 0}, {"q": "If we ___ earlier, we wouldn't be late now.", "o": ["had left", "left", "would leave"], "a": 0}, {"q": "If I ___ scared of water, I would have gone diving.", "o": ["weren't", "hadn't", "wouldn't be"], "a": 0}, {"q": "If he had listened to the instructor, he ___ injured now.", "o": ["wouldn't be", "won't be", "hadn't been"], "a": 0}, {"q": "Which is correct?", "o": ["If I had learned to swim, I would enjoy the beach more now.", "If I learned to swim, I would have enjoy the beach now.", "If I would learn to swim, I enjoy the beach now."], "a": 0}]}, {"id": "con", "title": "Conversation", "ar": "المحادثة", "icon": "💬", "qs": [{"q": "\"Weren't you scared when you jumped?\" — Best answer:", "o": ["Terrified! I almost chickened out.", "Yes, I jumped.", "Scared is an adjective."], "a": 0}, {"q": "\"What's on your bucket list?\" — Best answer:", "o": ["Diving with dolphins in the Red Sea.", "Water and soap.", "My bucket is empty."], "a": 0}, {"q": "\"Isn't skydiving dangerous?\" — Best answer:", "o": ["A bit, but we follow strict safety rules.", "Yes, I am dangerous.", "Sky is blue."], "a": 0}, {"q": "\"That rope looks sketchy.\" — Best answer:", "o": ["You're right. Let's check it first.", "Yes, it is a nice drawing.", "Sketchy is my friend."], "a": 0}, {"q": "\"Let's try rock climbing next weekend!\" — Best answer:", "o": ["I'm hyped! Count me in.", "Rock is hard.", "Weekend is two days."], "a": 0}, {"q": "\"I've won three times. One more?\" — Best answer:", "o": ["Don't push your luck!", "Take the plunge in the pool.", "Live on the edge of the table."], "a": 0}]}, {"id": "rea", "title": "Reading", "ar": "القراءة", "icon": "📖", "passage": ["Hi, I'm Dina. Two years ago, I was terrified of water, so I never went to the beach with my friends.", "Then my cousin, a diving instructor, offered to teach me. I almost chickened out, but I finally took the plunge.", "We started in a swimming pool, then moved to the sea in Dahab.", "If I hadn't accepted her offer, I wouldn't be a qualified diver now.", "Last month, I saw a sea turtle up close. It was epic!"], "qs": [{"q": "What was Dina afraid of?", "o": ["water", "heights", "flying"], "a": 0}, {"q": "Who taught her?", "o": ["her cousin", "her father", "a famous diver"], "a": 0}, {"q": "Where did they start?", "o": ["in a swimming pool", "in the deep sea", "in a lake"], "a": 0}, {"q": "What would Dina not be if she hadn't accepted?", "o": ["a qualified diver", "a teacher", "a swimmer in a pool"], "a": 0}, {"q": "What did she see last month?", "o": ["a sea turtle", "a shark", "a whale"], "a": 0}]}, {"id": "wri", "title": "Writing", "ar": "الكتابة", "icon": "✍️", "writing": true, "prompt": "Write about an important decision or a risk you took — or didn't take (70–100 words). How is your life different now because of it? Use at least two mixed conditionals.", "promptAr": "اكتب عن قرار مهم أو مخاطرة خدتها — أو مخدتهاش (٧٠–١٠٠ كلمة). حياتك مختلفة إزاي دلوقتي بسببها؟ استخدم ٢ mixed conditionals على الأقل.", "checks": [["🪂", "Adventure / risk words", "x", "\\b(risk|risky|adventure|brave|afraid|scared|challenge|comfort zone|danger|dangerous|plunge|decision)\\b"], ["🔀", "Past → present", "x", "\\bif\\b[^.?!]*\\bhad\\b[^.?!]*\\b(would|wouldn't|'d)\\s+(?!have)\\w+"], ["🔁", "Present → past", "x", "\\bif\\b[^.?!]*\\b(were|was|weren't|didn't|spoke|had)\\b[^.?!]*\\b(would|wouldn't|'d)\\s+have\\b"], ["💬", "At least 70 words", "len70"]]}]}, "watch": [{"yt": "WAaAoXsIHvI", "title": "How Much Risk Are You Prepared to Take?", "ar": "مستعد تخاطر قد إيه؟ — 6 Minute English", "by": "BBC Learning English", "lines": [["What's the most dangerous thing you've ever chosen to do? Probably bungee jumping in New Zealand.", "إيه أخطر حاجة اخترت تعملها؟ غالبًا البانجي جمبينج في نيوزيلندا."], ["Did you enjoy it? No, not really. I won't do it again!", "استمتعت؟ لأ، مش أوي. مش هعملها تاني!"], ["Today our topic is risk and how different people react to different levels of risk.", "موضوعنا النهارده المخاطرة، وإزاي الناس المختلفين بيتفاعلوا مع مستويات مختلفة منها."], ["Would you be happy to be in a driverless car? Absolutely not! I don't trust anybody's driving — even a computer's.", "تكون مبسوط تركب عربية من غير سواق؟ أبدًا! مش بثق في سواقة حد — حتى لو كمبيوتر."], ["Some people are quite risk-averse and really don't want to take any decisions where there's risk involved.", "بعض الناس بيكرهوا المخاطرة جدًا ومش عايزين ياخدوا أي قرار فيه مخاطرة."], ["Others are fairly risk-tolerant, and some are even risk-seeking — they actively look for risk.", "وغيرهم بيتقبلوا المخاطرة، وبعضهم حتى بيدوروا عليها."], ["Research found differences in brain structure between people who avoid risk and people who like it.", "البحث لقى فروق في تركيب المخ بين اللي بيتجنبوا المخاطرة واللي بيحبوها."], ["This could help develop better ways to assess who is likely to take risks.", "وده ممكن يساعد في طرق أحسن لتقييم مين غالبًا هياخد مخاطرة."], ["Financial advisors want to know your tolerance for risk when you save money for retirement.", "المستشارين الماليين عايزين يعرفوا قد إيه بتتحمل المخاطرة لما تحوّش فلوس للمعاش."], ["To assess means to make a judgement or decision based on information.", "Assess يعني تحكم أو تقرر بناءً على معلومات."], ["To put money away means to save it, so you can't spend it and it can grow.", "Put money away يعني تحوّش الفلوس، عشان متصرفهاش وتكبر."], ["The first driverless car was demonstrated on a public road in the 1920s!", "أول عربية من غير سواق اتعرضت في شارع عام في العشرينات!"]], "words": ["dangerous", "risky", "bungee jumping", "risk", "driverless car", "trust", "risk-averse", "risk-tolerant", "risk-seeking", "assess", "financial advisor", "retirement"], "quiz": [{"q": "What is the most risky thing Rob has done?", "o": ["bungee jumping in New Zealand", "skydiving", "driving fast"], "a": 0}, {"q": "Would Rob go in a driverless car?", "o": ["No, he doesn't trust anybody's driving.", "Yes, he loves them.", "Only at night."], "a": 0}, {"q": "What does \"risk-averse\" mean?", "o": ["not liking risk", "loving risk", "not knowing about risk"], "a": 0}, {"q": "Who actively look for risk?", "o": ["risk-seekers", "risk-averse people", "financial advisors"], "a": 0}, {"q": "Who would find this research useful?", "o": ["financial advisors", "cooks", "teachers"], "a": 0}, {"q": "When was the first driverless car demonstrated?", "o": ["the 1920s", "the 1970s", "the 1950s"], "a": 0}]}]}, "5": {"n": 5, "title": "Body Language and Communication", "ar": "لغة الجسد والتواصل — Advanced Linkers", "icon": "🤝", "cover": "img/b2/u5.jpg", "intro": "اتعلم تقرا لغة الجسد وتتواصل بثقة، واستخدم أدوات الربط المتقدمة زي despite / whereas / provided that / so as to عشان كلامك يبقى مترابط واحترافي.", "videos": [{"id": "b2v5", "title": "After the Presentation", "ar": "بعد العرض — هنا وعلي", "src": "video/b2/u5v1.mp4", "poster": "img/b2/u5v1.jpg", "sp": {"a": {"n": "Hana", "g": "f"}, "b": {"n": "Ali", "g": "m"}}, "lines": [["a", "Ali, how do you think my presentation went? Be honest.", "علي، شايف العرض بتاعي كان عامل إيه؟ قول بصراحة."], ["b", "Your ideas were excellent. However, your body language was sending a different message.", "أفكارك كانت ممتازة. لكن لغة جسمك كانت بتبعت رسالة مختلفة."], ["a", "Really? What do you mean?", "بجد؟ تقصد إيه؟"], ["b", "Well, despite knowing the topic perfectly, you kept looking at the floor. It made you seem nervous.", "يعني، رغم إنك عارفة الموضوع كويس جدًا، كنتي بتبصي على الأرض طول الوقت. ده خلاكي باينة متوترة."], ["a", "That's because I was nervous! Whereas you always look so relaxed when you speak.", "ده لأني كنت متوترة فعلًا! إنما إنت دايمًا باين عليك مرتاح لما بتتكلم."], ["b", "I practise in front of a mirror so as to notice my gestures. You should try it.", "أنا بتمرن قدام المراية عشان آخد بالي من حركاتي. لازم تجربي."], ["a", "Good idea. Anything else?", "فكرة حلوة. حاجة تانية؟"], ["b", "You crossed your arms during the questions. People might read that as defensive, even though you were just cold!", "كنتي مكتفة إيديكي وقت الأسئلة. الناس ممكن يفهموا ده إنك بتدافعي عن نفسك، مع إنك كنتي بردانة بس!"], ["a", "Ha! The air conditioning was freezing. So, what should I do next time?", "هههه! التكييف كان ساقعة جدًا. طب أعمل إيه المرة الجاية؟"], ["b", "Make eye contact, smile, and keep your hands open. Provided that you do those three things, you'll look much more confident.", "بصي في عيون الناس، وابتسمي، وخلي إيديكي مفتوحة. طالما عملتي التلات حاجات دول، هتبقي باينة واثقة أكتر بكتير."], ["a", "Thanks, Ali. Honestly, I appreciate the feedback, even if it hurts a little!", "شكرًا يا علي. بصراحة مقدّرة الملاحظات، حتى لو بتوجع شوية!"], ["b", "That's what friends are for. Next time, you'll nail it!", "ده دور الصحاب. المرة الجاية، هتكسّري الدنيا!"]], "quiz": [{"q": "What was the problem with Hana's presentation?", "o": ["her body language", "her ideas", "her English"], "a": 0}, {"q": "Where did Hana keep looking?", "o": ["at the floor", "at the ceiling", "at her phone"], "a": 0}, {"q": "Why does Ali practise in front of a mirror?", "o": ["to notice his gestures", "to check his hair", "to sing"], "a": 0}, {"q": "Why did Hana cross her arms?", "o": ["She was cold.", "She was angry.", "She was bored."], "a": 0}, {"q": "What three things does Ali advise?", "o": ["eye contact, smiling and open hands", "talking fast, looking down and frowning", "reading notes, sitting and whispering"], "a": 0}], "fill": [[1, "However"], [1, "body language"], [3, "despite"], [3, "nervous"], [4, "Whereas"], [5, "so as to"], [5, "gestures"], [7, "crossed your arms"], [7, "defensive"], [7, "even though"], [9, "eye contact"], [9, "Provided that"], [10, "feedback"]]}], "vocab": [{"t": "Body language", "ar": "لغة الجسد", "items": [["👀", "eye contact", "Make eye contact when you speak."], ["🙆", "gesture", "He made a gesture to show he agreed."], ["🙂", "facial expression", "Her facial expression showed she was surprised."], ["🧍", "posture", "Good posture makes you look confident."], ["🙅", "cross your arms", "Crossing your arms can look defensive."], ["👍", "nod", "He nodded to show he understood."], ["🤷", "shrug", "She shrugged as if she didn't care."], ["🤝", "handshake", "A firm handshake shows confidence."]]}, {"t": "Communication", "ar": "التواصل", "items": [["💬", "communicate", "We communicate with words and actions."], ["🗣️", "tone of voice", "It's not what you say, it's your tone of voice."], ["👂", "active listening", "Active listening means really paying attention."], ["📝", "feedback", "Thanks for your honest feedback."], ["🔄", "misunderstanding", "It was all a misunderstanding."], ["🎯", "clear", "Try to make your message clear."], ["🤐", "interrupt", "Don't interrupt people when they speak."], ["😬", "awkward", "There was an awkward silence."]]}, {"t": "How people seem", "ar": "الناس بتبان إزاي", "items": [["😎", "confident", "She looked confident on stage."], ["😰", "nervous", "He seemed nervous during the interview."], ["🛡️", "defensive", "Don't be so defensive — I'm only trying to help."], ["😊", "friendly", "A smile makes you look friendly."], ["🤨", "suspicious", "He gave me a suspicious look."], ["🙄", "bored", "She looked bored during the meeting."], ["😤", "aggressive", "Pointing your finger can seem aggressive."], ["🧘", "relaxed", "You seem very relaxed today."]]}], "talk": [{"title": "Let's Talk · Student A", "ar": "الطالب A", "list": [["Can you tell how someone feels just by looking at them?", "تقدر تعرف حد حاسس بإيه من مجرد شكله؟", "Usually, yes. Their face shows a lot."], ["What gestures are common in your country?", "إيه الحركات المنتشرة في بلدك؟", "We move our hands a lot when we talk."], ["How do you show someone that you are listening?", "بتوضح لحد إنك سامعه إزاي؟", "I nod and make eye contact."], ["Have you ever been misunderstood because of your body language?", "حد فهمك غلط بسبب لغة جسمك قبل كده؟", "Yes, people thought I was angry when I was tired."], ["Is it easier to communicate by text or face to face?", "التواصل أسهل بالرسايل ولا وش لوش؟", "Face to face, despite being more stressful."]]}, {"title": "Let's Talk · Student B", "ar": "الطالب B", "list": [["Which is more important: what you say or how you say it?", "الأهم اللي بتقوله ولا إزاي بتقوله؟", "How you say it, because tone changes everything."], ["How can body language help in a job interview?", "لغة الجسد ممكن تساعد إزاي في الإنترفيو؟", "Good posture and a smile show confidence."], ["Do emojis help us communicate better online?", "الإيموجي بتساعدنا نتواصل أحسن أونلاين؟", "Yes, they show our tone."], ["Why do misunderstandings happen between people from different cultures?", "ليه بيحصل سوء فهم بين ناس من ثقافات مختلفة؟", "Because gestures have different meanings."], ["How can someone become a better listener?", "إزاي الواحد يبقى مستمع أحسن؟", "By not interrupting and asking questions."]]}], "grammar": {"title": "Advanced Linkers", "ar": "أدوات الربط المتقدمة — despite / whereas / provided that / so as to", "blocks": [{"type": "intro", "en": "Linkers connect ideas and make your English sound fluent and organised. At B2, we go beyond \"and, but, so\" and use more precise linkers for contrast, condition, purpose and addition.", "ar": "أدوات الربط بتوصل الأفكار ببعض وبتخلي إنجليزيك سلس ومنظم. في B2 بنعدّي and / but / so ونستخدم أدوات أدق للتضاد والشرط والهدف والإضافة."}, {"type": "big", "items": [{"v": "despite / in spite of + noun / -ing", "p": "contrast", "c": 1, "eg": ["Despite knowing the topic, she looked nervous.", "In spite of the rain, we went hiking.", "He passed despite not studying much."]}, {"v": "although / even though / whereas + clause", "p": "contrast", "c": 2, "eg": ["Even though she was cold, she smiled.", "I love speaking, whereas my brother hates it.", "Although he was tired, he finished the report."]}, {"v": "provided that / as long as / unless", "p": "condition", "c": 3, "eg": ["Provided that you practise, you'll improve.", "You can borrow it as long as you return it.", "Unless you make eye contact, people won't trust you."]}, {"v": "so as to / in order to / so that", "p": "purpose", "c": 4, "eg": ["I practise in front of a mirror so as to notice my gestures.", "She spoke slowly in order to be clear.", "Smile so that people feel welcome."]}]}, {"type": "table", "title": "📋 Linkers by function", "head": ["Function", "Linkers"], "rows": [["Contrast", "however · nevertheless · despite · although · whereas · on the other hand"], ["Condition", "provided that · as long as · unless · in case"], ["Purpose", "so as to · in order to · so that"], ["Addition", "moreover · furthermore · in addition · as well as"], ["Result", "therefore · as a result · consequently"]]}, {"type": "uses", "title": "🔧 Grammar after each linker", "ar": "بييجي بعدها إيه", "items": [["🧱", "despite + noun / -ing", "despite the noise / despite feeling tired", "اسم أو ing"], ["📄", "although + subject + verb", "although it was noisy", "جملة كاملة"], ["📍", "However, + sentence", "It was cold. However, we went out.", "في أول جملة جديدة"], ["🎯", "so as to + base verb", "so as to save time", "فعل مجرد"]]}, {"type": "tip", "en": "Never say 'despite of' — it's 'despite' or 'in spite of'. And 'despite' is not followed by a full clause: Despite she was tired ✖ → Despite being tired ✔ / Although she was tired ✔.", "ar": "متقولش despite of — يا despite يا in spite of. وdespite مش بييجي بعدها جملة كاملة: Despite being tired أو Although she was tired."}]}, "exercises": [{"type": "mcq", "title": "Advanced Linkers — 10 MCQs", "ar": "اختار الصح", "speak": true, "items": [{"q": "___ knowing the topic perfectly, she looked nervous.", "o": ["Despite", "Although", "However", "Unless"], "a": 0}, {"q": "I love public speaking, ___ my brother hates it.", "o": ["whereas", "despite", "so as to", "unless"], "a": 0}, {"q": "I practise in front of a mirror ___ notice my gestures.", "o": ["so as to", "despite", "whereas", "although"], "a": 0}, {"q": "___ you make eye contact, you'll look confident.", "o": ["Provided that", "Despite", "However", "Whereas"], "a": 0}, {"q": "She smiled ___ she was very cold.", "o": ["even though", "despite", "in spite of", "so as to"], "a": 0}, {"q": "The presentation was long. ___, everyone enjoyed it.", "o": ["However", "Although", "Despite", "Unless"], "a": 0}, {"q": "___ you speak clearly, people won't understand you.", "o": ["Unless", "Provided that", "Despite", "So as to"], "a": 0}, {"q": "He went to work in spite of ___ ill.", "o": ["feeling", "he felt", "feel", "felt"], "a": 0}, {"q": "Which sentence is correct?", "o": ["Despite the noise, we heard her clearly.", "Despite of the noise, we heard her clearly.", "Despite it was noisy, we heard her clearly.", "Although the noise, we heard her clearly."], "a": 0}, {"q": "Which linker shows PURPOSE?", "o": ["in order to", "whereas", "nevertheless", "unless"], "a": 0}]}, {"type": "mcq", "title": "What follows?", "ar": "بييجي بعدها إيه؟", "items": [{"q": "despite + ___", "o": ["noun / -ing", "subject + verb"], "a": 0}, {"q": "although + ___", "o": ["subject + verb", "noun only"], "a": 0}, {"q": "so as to + ___", "o": ["base verb", "-ing"], "a": 0}, {"q": "\"Unless\" means ___", "o": ["if not", "because"], "a": 0}, {"q": "\"Whereas\" shows ___", "o": ["contrast", "purpose"], "a": 0}]}, {"type": "ord", "title": "Make sentences", "ar": "رتّب الكلمات", "items": [{"c": ["Despite", "feeling nervous,", "she", "spoke clearly"], "a": [0, 1, 2, 3]}, {"c": ["I practise", "every day", "so as to", "improve"], "a": [0, 1, 2, 3]}, {"c": ["Provided that", "you smile,", "people will", "trust you"], "a": [0, 1, 2, 3]}, {"c": ["He loves talking,", "whereas", "his sister", "is very quiet"], "a": [0, 1, 2, 3]}]}], "reading": {"title": "The Silent Language", "ar": "اللغة الصامتة", "g": "f", "lines": [["When we think about communication, we usually think about words. However, experts believe that a large part of our message is sent without speaking at all.", "لما بنفكر في التواصل، غالبًا بنفكر في الكلام. لكن الخبراء شايفين إن جزء كبير من رسالتنا بيتبعت من غير ما نتكلم خالص."], ["Our faces, hands, posture and tone of voice all communicate feelings that words sometimes try to hide.", "وشوشنا وإيدينا ووقفتنا ونبرة صوتنا كلهم بيوصلوا مشاعر الكلام أحيانًا بيحاول يخبّيها."], ["Some signals seem to be universal. People all over the world smile when they are happy and frown when they are worried, even if they have never seen another culture.", "بعض الإشارات شكلها عالمية. الناس في كل العالم بتبتسم لما تبقى مبسوطة وبتكشّر لما تبقى قلقانة، حتى لو عمرهم ما شافوا ثقافة تانية."], ["Many other gestures, whereas, change their meaning from one country to another.", "لكن حركات تانية كتير معناها بيتغير من بلد للتانية."], ["The thumbs-up sign, for instance, means \"great\" in many countries, whereas in some places it can be considered rude.", "علامة الإبهام لفوق مثلًا، معناها \"تمام\" في بلاد كتير، بينما في بعض الأماكن ممكن تتعتبر قلة ذوق."], ["In Bulgaria, shaking your head can mean \"yes\" — a fact that has confused many tourists.", "في بلغاريا، هز الراس ممكن يعني \"أيوه\" — ودي حاجة لخبطت سياح كتير."], ["Body language matters in professional life too. Studies show that interviewers often form an opinion about a candidate within the first few seconds, before any question is answered.", "لغة الجسد مهمة في الشغل كمان. دراسات بتوضح إن اللي بيعملوا الإنترفيو غالبًا بيكوّنوا رأي عن المتقدم في أول كام ثانية، قبل ما يجاوب أي سؤال."], ["A firm handshake, good posture and natural eye contact can make you seem confident, even though you may feel nervous inside.", "السلام بإيد ثابتة، والوقفة الكويسة، والنظر الطبيعي في العين ممكن يخلوك تبان واثق، حتى لو كنت متوتر من جوه."], ["Nevertheless, we should be careful not to judge too quickly. Crossed arms might mean someone is defensive — or simply that the room is cold!", "ومع ذلك، لازم ناخد بالنا منحكمش بسرعة. الإيدين المتكتفة ممكن تعني إن الشخص بيدافع عن نفسه — أو ببساطة إن الأوضة ساقعة!"], ["The best communicators pay attention to the whole picture: words, gestures and context together.", "أحسن ناس في التواصل بياخدوا بالهم من الصورة كاملة: الكلام والحركات والموقف مع بعض."]], "keys": [["🌍", "universal", "the same everywhere in the world"], ["😟", "frown", "to make an unhappy face by moving your eyebrows together"], ["👍", "thumbs-up", "a gesture with the thumb pointing up"], ["🙊", "rude", "not polite"], ["⚖️", "judge", "to form an opinion about someone"], ["🖼️", "context", "the situation in which something happens"]], "quiz": [{"q": "How is a large part of our message sent, according to experts?", "o": ["without speaking", "by email", "only with words"], "a": 0}, {"q": "Which signal seems to be universal?", "o": ["smiling when happy", "the thumbs-up sign", "shaking your head for \"no\""], "a": 0}, {"q": "What can shaking your head mean in Bulgaria?", "o": ["\"yes\"", "\"no\"", "\"hello\""], "a": 0}, {"q": "When do interviewers often form an opinion?", "o": ["within the first few seconds", "after one hour", "the next day"], "a": 0}, {"q": "What might crossed arms mean?", "o": ["being defensive or simply feeling cold", "being very happy", "wanting to dance"], "a": 0}, {"q": "What do the best communicators do?", "o": ["pay attention to words, gestures and context", "only listen to words", "judge quickly"], "a": 0}]}, "idioms": {"items": [["read between the lines", "To understand the hidden meaning.", "يفهم اللي ورا الكلام", "She said she was fine, but I read between the lines — she was upset.", "قالت إنها كويسة، بس أنا فهمت اللي ورا الكلام — كانت زعلانة."], ["keep a straight face", "To not laugh even when something is funny.", "يمسك نفسه من الضحك", "It was hard to keep a straight face when he fell off the chair.", "كان صعب أمسك نفسي من الضحك لما وقع من على الكرسي."], ["give someone the cold shoulder", "To ignore someone on purpose.", "يطنّش حد عن قصد", "After our argument, she gave me the cold shoulder all week.", "بعد خناقتنا، طنّشتني الأسبوع كله."], ["get the wrong end of the stick", "To misunderstand something.", "يفهم الموضوع غلط", "You've got the wrong end of the stick — I wasn't angry, just tired.", "إنت فهمت غلط — مكنتش زعلان، كنت تعبان بس."]], "quiz": [{"q": "He didn't say it directly, but if you ___, he wants to quit.", "o": ["read between the lines", "keep a straight face", "give the cold shoulder", "get the stick"], "a": 0}, {"q": "She won't talk to me. She's giving me ___.", "o": ["the cold shoulder", "a straight face", "the wrong stick", "the lines"], "a": 0}, {"q": "\"Get the wrong end of the stick\" means…", "o": ["misunderstand", "hold a stick", "be lucky", "arrive late"], "a": 0}, {"q": "The joke was so funny, I couldn't ___.", "o": ["keep a straight face", "read the lines", "give the shoulder", "end the stick"], "a": 0}]}, "phrasal": {"items": [["pick up on", "To notice something that is not obvious.", "ياخد باله من حاجة مش واضحة", "Good teachers pick up on students' feelings quickly.", "المدرسين الكويسين بياخدوا بالهم من مشاعر الطلاب بسرعة."], ["come across as", "To seem to be a certain type of person.", "يبان كأنه…", "He comes across as shy, but he is very funny.", "باين عليه خجول، بس هو دمه خفيف جدًا."], ["brush off", "To ignore or refuse to listen to something.", "يتجاهل / ميهتمش بـ", "She brushed off my advice and did it her way.", "اتجاهلت نصيحتي وعملتها على طريقتها."], ["open up", "To start talking about your feelings.", "يفتح قلبه ويتكلم", "It took months before he opened up about his problems.", "أخد شهور قبل ما يفتح قلبه ويتكلم عن مشاكله."]], "quiz": [{"q": "In the interview, try not to ___ arrogant.", "o": ["come across as", "pick up on", "brush off", "open up"], "a": 0}, {"q": "My mum always ___ my mood, even when I hide it.", "o": ["picks up on", "brushes off", "comes across", "opens up"], "a": 0}, {"q": "I told him he looked tired, but he just ___ it ___.", "o": ["brushed / off", "picked / up", "opened / up", "came / across"], "a": 0}, {"q": "After a long talk, she finally ___ about her fears.", "o": ["opened up", "brushed off", "picked up", "came across"], "a": 0}]}, "slang": {"items": [["side-eye", "A look from the corner of your eye that shows doubt or disapproval.", "بصّة جانبية (فيها شك)", "When he said he was \"almost ready\", she gave him the side-eye.", "لما قال إنه \"تقريبًا جاهز\"، بصتله بصّة جانبية.", "بتتقال بهزار كتير"], ["cringe", "Very embarrassing or awkward.", "محرج / بيكسف", "My old Facebook photos are so cringe.", "صوري القديمة على فيسبوك محرجة جدًا.", "منتشرة جدًا بين الشباب"], ["throw shade", "To criticise someone indirectly or secretly.", "يلقّح الكلام / يتريق من غير ما يقول صريح", "\"Nice shoes… for a five-year-old.\" — Wow, she's throwing shade.", "\"جزمة حلوة… لطفل عنده ٥ سنين.\" — يا ساتر، بتلقّح.", "خليك لطيف ومترميش shade 😉"], ["read the room", "Understand the mood of the people around you.", "افهم الجو", "He told a joke at the funeral. He really can't read the room.", "قال نكتة في العزا. هو فعلًا مش بيفهم الجو.", "تعبير مهم جدًا للتواصل"], ["vibe", "The feeling or atmosphere someone gives.", "الطاقة / الإحساس", "I like her vibe — she seems really kind.", "بحب الطاقة بتاعتها — شكلها طيبة جدًا.", "عادي جدًا بين الصحاب"]], "quiz": [{"q": "\"Read the room\" means…", "o": ["understand the mood of people around you", "read a book in your room", "clean the room", "count the people"], "a": 0}, {"q": "Watching yourself dance in an old video is ___.", "o": ["cringe", "vibe", "side-eye", "shade"], "a": 0}, {"q": "She looked at him from the corner of her eye, doubting him. She gave him ___.", "o": ["the side-eye", "the vibe", "the shade", "the room"], "a": 0}, {"q": "\"She's throwing shade.\" means she is…", "o": ["criticising someone indirectly", "standing in the shade", "throwing a ball", "being very kind"], "a": 0}]}, "story": {"title": "The Interview Without Words", "ar": "الإنترفيو من غير كلام", "g": "f", "lines": [["Salma had prepared for weeks for her interview at a big design company. She knew every answer by heart.", "سلمى جهزت أسابيع للإنترفيو في شركة تصميم كبيرة. كانت حافظة كل الإجابات."], ["However, when she walked into the room, the manager didn't ask a single question. He simply said, \"Wait here, please,\" and left.", "لكن لما دخلت الأوضة، المدير مسألش ولا سؤال. قال بس: \"استني هنا لو سمحتي،\" ومشي."], ["Salma sat down, confused. Despite feeling nervous, she kept her back straight and her hands relaxed on the table.", "سلمى قعدت مستغربة. ورغم إنها كانت متوترة، فضلت ضهرها مفرود وإيديها مرتاحة على الترابيزة."], ["A cleaner came in and dropped a pile of papers. Salma immediately stood up so as to help her collect them, smiling warmly.", "عاملة نظافة دخلت ووقعت كومة ورق. سلمى قامت على طول عشان تساعدها تلمهم، وهي بتبتسم بود."], ["Then a young man entered, sat in the corner and started looking at his phone. Salma said hello politely, although he didn't answer.", "وبعدين شاب دخل، وقعد في الركن وبدأ يبص في موبايله. سلمى قالتله أهلًا بأدب، رغم إنه ماردش."], ["After twenty minutes, the manager returned with a big smile. \"Congratulations,\" he said. \"You've got the job.\"", "بعد عشرين دقيقة، المدير رجع بابتسامة كبيرة. \"مبروك،\" قال. \"إنتي اتقبلتي.\""], ["\"But… you didn't ask me anything!\" Salma said.", "\"بس… إنت مسألتنيش أي حاجة!\" قالت سلمى."], ["\"Words are easy to prepare,\" he explained. \"Body language isn't. The cleaner and the young man work for us. We wanted to see how you treat people when you think nobody is watching.\"", "\"الكلام سهل يتحضّر،\" شرح. \"لغة الجسد لأ. عاملة النظافة والشاب بيشتغلوا معانا. كنا عايزين نشوف بتعاملي الناس إزاي لما تفتكري إن محدش شايفك.\""], ["Salma laughed. She had prepared every answer, whereas the real test had been silent all along.", "سلمى ضحكت. كانت محضّرة كل الإجابات، بينما الامتحان الحقيقي كان صامت من الأول."]], "quiz": [{"q": "What did the manager do when Salma arrived?", "o": ["He asked her to wait and left.", "He asked many questions.", "He gave her a test paper."], "a": 0}, {"q": "What did Salma do when the cleaner dropped the papers?", "o": ["She helped her collect them.", "She ignored her.", "She laughed."], "a": 0}, {"q": "How did the young man react when she said hello?", "o": ["He didn't answer.", "He shook her hand.", "He left."], "a": 0}, {"q": "Why did the company do this?", "o": ["to see how she treats people when nobody is watching", "because they forgot the questions", "because the manager was busy"], "a": 0}, {"q": "What was \"the real test\"?", "o": ["her body language and behaviour", "her CV", "her English grammar"], "a": 0}]}, "challenge": {"title": "Say It Without Words", "ar": "قولها من غير كلام — جاوب وسجّل", "qs": ["Describe the body language of a confident person.", "Tell a story about a misunderstanding you had with someone. How did you solve it?", "Despite being shy, how can someone give a great presentation?", "Compare how people greet each other in Egypt and in another country. Use whereas.", "Is it rude to look at your phone while someone is talking to you?", "What would you do so as to make a good first impression?", "Do you think body language can be faked? How?", "Which emoji do you use the most, and what does it mean to you?", "Provided that you had one minute, how would you introduce yourself to a famous person?", "What makes someone a great communicator?"]}, "games": {"pairs": [["👀", "eye contact"], ["🧍", "posture"], ["🤷", "shrug"], ["👍", "nod"], ["🤝", "handshake"], ["🙆", "gesture"]], "spell": [["💬", "communicate"], ["📝", "feedback"], ["😬", "awkward"], ["🛡️", "defensive"], ["😰", "nervous"], ["🤐", "interrupt"], ["😎", "confident"], ["🧘", "relaxed"]], "speed": [["Despite feeling nervous, she spoke well.", true], ["Despite of the rain, we went out.", false], ["I love tea, whereas my sister loves coffee.", true], ["I practise so as to improve.", true], ["Despite she was tired, she worked.", false], ["Unless you study, you won't pass.", true], ["Provided that you practise, you will improve.", true], ["Although the noise, we heard her.", false], ["She went in spite of feeling ill.", true], ["However it was cold, we went swimming.", false], ["Eye contact can show confidence.", true], ["Crossing your arms always means you are happy.", false], ["\"Read the room\" means understand the mood.", true], ["\"Cringe\" means very embarrassing.", true], ["\"Open up\" means to talk about your feelings.", true], ["\"Give someone the cold shoulder\" means to hug them.", false]]}, "test": {"pass": 60, "sections": [{"id": "voc", "title": "Vocabulary", "ar": "المفردات", "icon": "📚", "qs": [{"q": "The way you stand or sit = your ___.", "o": ["posture", "gesture", "tone"], "a": 0, "pic": "🧍"}, {"q": "Looking into someone's eyes = eye ___.", "o": ["contact", "shrug", "nod"], "a": 0, "pic": "👀"}, {"q": "Comments about how well you did something = ___.", "o": ["feedback", "handshake", "misunderstanding"], "a": 0, "pic": "📝"}, {"q": "Uncomfortable and embarrassing = ___.", "o": ["awkward", "relaxed", "friendly"], "a": 0, "pic": "😬"}, {"q": "To move your head up and down = to ___.", "o": ["nod", "shrug", "frown"], "a": 0, "pic": "👍"}, {"q": "\"لغة الجسد\" in English is…", "o": ["body language", "tone of voice", "sign language"], "a": 0, "say": "Choose the correct word."}]}, {"id": "gra", "title": "Grammar", "ar": "القواعد", "icon": "📘", "qs": [{"q": "___ the noise, we enjoyed the concert.", "o": ["Despite", "Although", "Unless"], "a": 0}, {"q": "He is very talkative, ___ his wife is quiet.", "o": ["whereas", "despite", "so as to"], "a": 0}, {"q": "She left early ___ catch the train.", "o": ["so as to", "whereas", "despite"], "a": 0}, {"q": "___ you apologise, she won't talk to you.", "o": ["Unless", "Provided", "Despite"], "a": 0}, {"q": "___ he was tired, he finished the report.", "o": ["Although", "Despite", "However"], "a": 0}, {"q": "Which is correct?", "o": ["In spite of being late, he got the job.", "In spite of he was late, he got the job.", "In spite being late, he got the job."], "a": 0}]}, {"id": "con", "title": "Conversation", "ar": "المحادثة", "icon": "💬", "qs": [{"q": "\"How did my presentation go?\" — Best answer:", "o": ["Your ideas were great. However, try to make more eye contact.", "It went to the office.", "Presentation is long word."], "a": 0}, {"q": "\"You look nervous.\" — Best answer:", "o": ["I am a bit, despite preparing a lot.", "I look at the window.", "Nervous is good."], "a": 0}, {"q": "\"She gave me the cold shoulder.\" — Best answer:", "o": ["Oh no, did you have an argument?", "Was it cold outside?", "Give her a jacket."], "a": 0}, {"q": "\"I think you got the wrong end of the stick.\" — Best answer:", "o": ["Oh, sorry! What did you mean?", "Which stick?", "The stick is long."], "a": 0}, {"q": "\"He told jokes at the meeting about job cuts.\" — Best answer:", "o": ["He really can't read the room.", "He reads a lot.", "Jokes are funny."], "a": 0}, {"q": "\"Thanks for the honest feedback.\" — Best answer:", "o": ["You're welcome. I hope it helps.", "Feed the back.", "I am honest feedback."], "a": 0}]}, {"id": "rea", "title": "Reading", "ar": "القراءة", "icon": "📖", "passage": ["Hi, I'm Omar. I'm a teacher, and I've learned a lot about body language in the classroom.", "When students cross their arms and look away, they are often confused, even though they say \"I understand\".", "So as to check, I ask them to explain the idea in their own words.", "Some students talk a lot, whereas others are quiet but very thoughtful.", "Provided that I watch carefully, I can usually pick up on how my students feel."], "qs": [{"q": "What is Omar's job?", "o": ["teacher", "doctor", "actor"], "a": 0}, {"q": "What does crossing arms and looking away often mean in his class?", "o": ["confusion", "happiness", "hunger"], "a": 0}, {"q": "What does he do so as to check?", "o": ["asks students to explain in their own words", "gives a test", "calls their parents"], "a": 0}, {"q": "How are the quiet students?", "o": ["thoughtful", "lazy", "angry"], "a": 0}, {"q": "What can he usually pick up on?", "o": ["how his students feel", "their phone numbers", "their grades"], "a": 0}]}, {"id": "wri", "title": "Writing", "ar": "الكتابة", "icon": "✍️", "writing": true, "prompt": "Write advice for a friend who has a job interview tomorrow (70–100 words). Tell them about body language and communication. Use at least four advanced linkers.", "promptAr": "اكتب نصايح لصاحبك اللي عنده إنترفيو بكرة (٧٠–١٠٠ كلمة) عن لغة الجسد والتواصل. استخدم ٤ أدوات ربط متقدمة على الأقل.", "checks": [["🤝", "Body language words", "x", "\\b(eye contact|posture|gesture|gestures|smile|handshake|body language|confident|nervous|arms|tone)\\b"], ["⚖️", "Contrast linker", "x", "\\b(despite|in spite of|although|even though|whereas|however|nevertheless)\\b"], ["🎯", "Purpose / condition", "x", "\\b(so as to|in order to|so that|provided that|as long as|unless)\\b"], ["💬", "At least 70 words", "len70"]]}]}, "watch": [{"yt": "oTPZWpQ9pbA", "title": "Cultural Differences and Body Language", "ar": "الاختلافات الثقافية ولغة الجسد — 6 Minute English", "by": "BBC Learning English", "lines": [["We had an argument just before we started the show. But no hard feelings?", "اتخانقنا قبل البرنامج ما يبدأ. بس مفيش زعل؟"], ["\"No hard feelings\" is something you say to show you still want to be friends after an argument.", "\"No hard feelings\" بنقولها عشان نوضح إننا لسه عايزين نفضل صحاب بعد الخناقة."], ["To fall out with somebody means to argue or disagree with them.", "Fall out with somebody يعني تتخانق أو تختلف معاه."], ["You wave your arms around a lot when you argue. That isn't very British!", "إنت بتحرك إيديك كتير لما بتتخانق. ده مش طبع البريطانيين!"], ["Gestures are movements you make with your hands or your head to express what you are thinking or feeling.", "الإيماءات حركات بتعملها بإيديك أو راسك عشان تعبر عن تفكيرك أو مشاعرك."], ["Shaking your head mostly means \"no\", but in some countries it can mean the opposite.", "هز الراس غالبًا معناه \"لأ\"، بس في بعض البلاد ممكن يعني العكس."], ["A faux pas means saying or doing something embarrassing in a social situation.", "Faux pas يعني تقول أو تعمل حاجة محرجة في موقف اجتماعي."], ["The thumbs-up sign might offend people from some parts of the Middle East.", "علامة الإبهام لفوق ممكن تضايق ناس من بعض مناطق الشرق الأوسط."], ["In Dubai, a professor saw two people shouting and gesticulating, and thought they were having a huge fight.", "في دبي، أستاذة شافت اتنين بيزعقوا ويشاوروا بإيديهم، وافتكرت إنهم بيتخانقوا خناقة كبيرة."], ["In fact, the man was just giving directions to the hotel! They were being emotionally expressive.", "في الحقيقة، الراجل كان بيوصف الطريق للفندق بس! كانوا بيعبروا عن مشاعرهم بحماس."], ["Expressive means showing what you think or feel.", "Expressive يعني بتبيّن إنت بتفكر أو حاسس بإيه."], ["In Bulgaria, shaking your head means \"yes\" — and nodding can mean \"no\"!", "في بلغاريا، هز الراس يعني \"أيوه\" — والإيماء بالراس ممكن يعني \"لأ\"!"]], "words": ["argument", "no hard feelings", "fall out with", "wave your arms", "gestures", "shaking your head", "faux pas", "offend", "misunderstand", "gesticulate", "expressive", "nodding"], "quiz": [{"q": "What does \"no hard feelings\" mean?", "o": ["I still want to be friends.", "I'm very angry.", "I'm tired."], "a": 0}, {"q": "What does \"fall out with\" mean?", "o": ["argue with someone", "fall down", "go outside"], "a": 0}, {"q": "What is a faux pas?", "o": ["something embarrassing in a social situation", "a type of dance", "a French dish"], "a": 0}, {"q": "Which gesture might offend people in some parts of the Middle East?", "o": ["the thumbs-up sign", "smiling", "waving hello"], "a": 0}, {"q": "What were the two people in Dubai really doing?", "o": ["giving directions to the hotel", "having a fight", "selling cloth"], "a": 0}, {"q": "In which country does shaking your head mean \"yes\"?", "o": ["Bulgaria", "Greece", "Japan"], "a": 0}]}]}, "6": {"n": 6, "title": "Sleep and Dreams", "ar": "النوم والأحلام — Past Perfect Continuous", "icon": "😴", "cover": "img/b2/u6.jpg", "intro": "اتكلم عن النوم والأرق والأحلام الغريبة وعادات النوم الصحية، واستخدم had been + ing عشان تقول حاجة كانت مستمرة قد إيه قبل حاجة تانية في الماضي.", "videos": [{"id": "b2v6", "title": "The Strange Dream", "ar": "الحلم الغريب — سارة وعمر", "src": "video/b2/u6v1.mp4", "poster": "img/b2/u6v1.jpg", "sp": {"a": {"n": "Sara", "g": "f"}, "b": {"n": "Omar", "g": "m"}}, "lines": [["b", "Morning, Sara. You look exhausted. Didn't you sleep?", "صباح الخير يا سارة. شكلك مرهقة جدًا. منمتيش؟"], ["a", "Not really. I'd been tossing and turning for hours before I finally fell asleep at four.", "مش أوي. كنت بتقلب في السرير بقالي ساعات قبل ما أنام أخيرًا الساعة ٤."], ["b", "Four? What were you doing?", "الساعة ٤؟ كنتي بتعملي إيه؟"], ["a", "That's the problem. I'd been scrolling on my phone since midnight, so my brain just wouldn't switch off.", "دي المشكلة. كنت بعمل سكرول على الموبايل من نص الليل، فمخي مرضيش يفصل."], ["b", "The blue light from screens keeps you awake. You should put your phone away an hour before bed.", "الضوء الأزرق من الشاشات بيخليكي صاحية. لازم تبعدي الموبايل ساعة قبل النوم."], ["a", "I know, I know. And when I finally dozed off, I had the weirdest dream!", "عارفة، عارفة. ولما أخيرًا غفلت، حلمت أغرب حلم!"], ["b", "Go on, tell me!", "احكي!"], ["a", "I was in an exam, but I had been studying the wrong subject all year! Everyone else was writing, and I was just staring at the paper.", "كنت في امتحان، بس كنت بذاكر المادة الغلط طول السنة! كل الناس بتكتب، وأنا قاعدة باصة في الورقة."], ["b", "Ha! That's a classic stress dream. Have you got exams soon?", "هههه! ده حلم توتر مشهور. عندك امتحانات قريب؟"], ["a", "Next week. I'd been worrying about them all day before I went to bed.", "الأسبوع الجاي. كنت قلقانة منهم طول اليوم قبل ما أنام."], ["b", "That explains it. Try to get eight hours tonight. Sleep actually helps your memory.", "ده بيفسر كل حاجة. حاولي تنامي ٨ ساعات النهارده. النوم فعلًا بيساعد الذاكرة."], ["a", "Deal. No phone, a warm drink, and I'll be in bed by eleven. Wish me sweet dreams!", "اتفقنا. من غير موبايل، ومشروب دافي، وهكون في السرير الساعة ١١. اتمنالي أحلام سعيدة!"]], "quiz": [{"q": "What time did Sara finally fall asleep?", "o": ["at four", "at eleven", "at midnight"], "a": 0}, {"q": "What had she been doing since midnight?", "o": ["scrolling on her phone", "studying", "watching TV"], "a": 0}, {"q": "What does Omar say keeps you awake?", "o": ["the blue light from screens", "warm drinks", "reading books"], "a": 0}, {"q": "What was her dream about?", "o": ["an exam where she had studied the wrong subject", "flying", "a scary monster"], "a": 0}, {"q": "What will Sara do tonight?", "o": ["no phone, a warm drink and bed by eleven", "study all night", "watch a film"], "a": 0}], "fill": [[0, "exhausted"], [1, "tossing and turning"], [1, "fell asleep"], [3, "scrolling"], [3, "switch off"], [4, "awake"], [5, "dozed off"], [5, "weirdest"], [7, "had been studying"], [8, "stress dream"], [9, "worrying"], [10, "memory"]]}], "vocab": [{"t": "Sleep", "ar": "النوم", "items": [["😴", "fall asleep", "I fell asleep on the sofa."], ["🥱", "exhausted", "I'm exhausted after the trip."], ["🌙", "insomnia", "Insomnia means you can't sleep."], ["🛌", "nap", "I took a short nap after lunch."], ["😪", "drowsy", "This medicine might make you drowsy."], ["⏰", "oversleep", "I overslept and missed the bus."], ["💤", "snore", "My dad snores really loudly."], ["🔄", "toss and turn", "I tossed and turned all night."]]}, {"t": "Dreams", "ar": "الأحلام", "items": [["💭", "dream", "I had a strange dream last night."], ["😱", "nightmare", "The film gave me nightmares."], ["🌀", "vivid", "Her dreams are always very vivid."], ["🧠", "subconscious", "Dreams come from your subconscious."], ["✨", "lucid dream", "In a lucid dream, you know you are dreaming."], ["🔁", "recurring", "I have a recurring dream about flying."], ["🛸", "weird", "That was the weirdest dream ever."], ["🔮", "interpret", "Some people try to interpret their dreams."]]}, {"t": "Healthy sleep", "ar": "النوم الصحي", "items": [["📱", "screen time", "Reduce screen time before bed."], ["💡", "blue light", "Blue light keeps your brain awake."], ["🕰️", "routine", "A bedtime routine helps you relax."], ["☕", "caffeine", "Avoid caffeine in the evening."], ["🧘", "unwind", "I read a book to unwind."], ["🌑", "dark", "Keep your bedroom dark and quiet."], ["🩺", "sleep deprivation", "Sleep deprivation affects your health."], ["🔋", "recharge", "Sleep helps your body recharge."]]}], "talk": [{"title": "Let's Talk · Student A", "ar": "الطالب A", "list": [["How many hours do you usually sleep?", "بتنام كام ساعة عادةً؟", "About seven hours on school days."], ["Are you a morning person or a night owl?", "إنت بتاع الصبح ولا السهر؟", "I'm definitely a night owl."], ["What do you do when you can't fall asleep?", "بتعمل إيه لما مش بتعرف تنام؟", "I read a boring book!"], ["Do you remember your dreams? Tell me about one.", "بتفتكر أحلامك؟ احكيلي واحد.", "I once dreamed I could speak every language."], ["Do you use your phone in bed?", "بتستخدم الموبايل في السرير؟", "Yes, although I know it's bad."]]}, {"title": "Let's Talk · Student B", "ar": "الطالب B", "list": [["Do you think dreams have meanings?", "شايف إن الأحلام ليها معنى؟", "Sometimes they show what we are worried about."], ["Should schools start later so that teenagers can sleep more?", "المدارس تبدأ متأخر عشان المراهقين يناموا أكتر؟", "Yes, teenagers need more sleep."], ["Is napping during the day a good idea?", "القيلولة فكرة كويسة؟", "A short nap, yes. A long one, no."], ["How does lack of sleep affect your mood?", "قلة النوم بتأثر على مزاجك إزاي؟", "I get angry and can't concentrate."], ["What had you been doing before you went to bed last night?", "كنت بتعمل إيه قبل ما تنام امبارح؟", "I had been watching a series for two hours."]]}], "grammar": {"title": "Past Perfect Continuous", "ar": "الماضي التام المستمر — had been + ing", "blocks": [{"type": "intro", "en": "We use the Past Perfect Continuous to talk about an action that was in progress for some time BEFORE another moment or action in the past. It often explains a past result.", "ar": "بنستخدمه لحاجة كانت مستمرة فترة قبل لحظة أو حاجة تانية في الماضي. وكتير بيفسّر نتيجة في الماضي."}, {"type": "big", "items": [{"v": "had been + verb-ing", "p": "duration before a past moment", "c": 1, "eg": ["I'd been tossing and turning for hours before I fell asleep.", "She had been studying for three hours when the power went off.", "They'd been waiting since 8 o'clock."]}, {"v": "hadn't been + verb-ing", "p": "negative", "c": 2, "eg": ["He hadn't been sleeping well, so he felt tired.", "We hadn't been waiting long when the bus arrived.", "I hadn't been feeling well for days."]}]}, {"type": "table", "title": "📋 Uses", "head": ["Use", "Example"], "rows": [["How long before a past event (for / since)", "I had been sleeping for two hours when the phone rang."], ["Cause of a past result", "Her eyes were red because she had been crying."], ["➖ Negative", "He hadn't been eating well."], ["❓ Question", "How long had you been waiting when she arrived?"]]}, {"type": "table", "title": "⚖️ Past Perfect vs Past Perfect Continuous", "head": ["Past Perfect (result / finished)", "Past Perfect Continuous (activity / duration)"], "rows": [["I had read three chapters before bed.", "I had been reading for an hour before bed."], ["She had finished her homework.", "She had been doing her homework all evening."], ["He had written two emails.", "He had been writing emails since lunch."]]}, {"type": "tip", "en": "Don't use stative verbs (know, believe, own, like) in the continuous: I had been knowing him ✖ → I had known him ✔. Use 'for' with a period (for two hours) and 'since' with a starting point (since midnight).", "ar": "متستخدمش الأفعال الحالية زي know وlike في continuous: I had known him. واستخدم for مع مدة، وsince مع نقطة بداية."}]}, "exercises": [{"type": "mcq", "title": "Past Perfect Continuous — 10 MCQs", "ar": "اختار الصح", "speak": true, "items": [{"q": "I ___ for hours before I finally fell asleep.", "o": ["had been tossing and turning", "have been tossing", "was tossed", "had toss"], "a": 0}, {"q": "She ___ on her phone since midnight.", "o": ["had been scrolling", "has scrolled", "had scroll", "was been scrolling"], "a": 0}, {"q": "His eyes were red because he ___.", "o": ["had been crying", "has cried", "cries", "had been cry"], "a": 0}, {"q": "We ___ for long when the bus arrived.", "o": ["hadn't been waiting", "haven't waited", "didn't been waiting", "hadn't wait"], "a": 0}, {"q": "How long ___ when the alarm went off?", "o": ["had you been sleeping", "have you slept", "you had been sleeping", "did you been sleeping"], "a": 0}, {"q": "He was tired because he ___ well for weeks.", "o": ["hadn't been sleeping", "isn't sleeping", "hasn't slept", "hadn't slept being"], "a": 0}, {"q": "I had been studying ___ three hours when the power went off.", "o": ["for", "since", "from", "during"], "a": 0}, {"q": "They had been working ___ 8 a.m.", "o": ["since", "for", "ago", "during"], "a": 0}, {"q": "Which sentence is correct?", "o": ["I had known him for years.", "I had been knowing him for years.", "I have been knowing him for years before.", "I had been know him for years."], "a": 0}, {"q": "\"The ground was wet. It had been raining.\" The rain happened ___.", "o": ["before the moment I saw the ground", "after I saw the ground", "tomorrow", "never"], "a": 0}]}, {"type": "mcq", "title": "Simple or continuous?", "ar": "بسيط ولا مستمر؟", "items": [{"q": "I ___ three chapters before bed. (result)", "o": ["had read", "had been reading"], "a": 0}, {"q": "I ___ for an hour before bed. (duration)", "o": ["had been reading", "had read"], "a": 0}, {"q": "She was out of breath because she ___.", "o": ["had been running", "had run three"], "a": 0}, {"q": "By 10 p.m., he ___ two essays.", "o": ["had written", "had been writing"], "a": 0}, {"q": "I ___ her since childhood. (know)", "o": ["had known", "had been knowing"], "a": 0}]}, {"type": "ord", "title": "Make sentences", "ar": "رتّب الكلمات", "items": [{"c": ["I", "had been scrolling", "for hours", "before I slept"], "a": [0, 1, 2, 3]}, {"c": ["Her eyes were red", "because", "she had been", "crying"], "a": [0, 1, 2, 3]}, {"c": ["How long", "had you been", "waiting", "for the bus?"], "a": [0, 1, 2, 3]}, {"c": ["He", "hadn't been", "sleeping", "well"], "a": [0, 1, 2, 3]}]}], "reading": {"title": "The Secret Life of Sleep", "ar": "الحياة السرية للنوم", "g": "f", "lines": [["We spend about a third of our lives asleep. For a long time, people thought that sleep was simply a time when the body and brain switched off. Today, we know the opposite is true.", "إحنا بنقضي تقريبًا تلت حياتنا نايمين. لفترة طويلة، الناس كانوا فاكرين إن النوم مجرد وقت الجسم والمخ بيفصلوا فيه. النهارده عارفين إن العكس هو الصح."], ["During sleep, the brain is extremely busy. It sorts the information we have collected during the day and moves important memories from short-term to long-term storage.", "أثناء النوم، المخ بيبقى مشغول جدًا. بيرتب المعلومات اللي جمعناها طول اليوم، وبينقل الذكريات المهمة من الذاكرة القصيرة للطويلة."], ["That is why students who sleep well after studying often remember more than those who stay up all night.", "وعشان كده الطلاب اللي بيناموا كويس بعد المذاكرة غالبًا بيفتكروا أكتر من اللي بيسهروا طول الليل."], ["Sleep also cleans the brain. Scientists have discovered that, while we sleep, a special fluid washes away waste products that build up during the day.", "النوم كمان بينضف المخ. العلماء اكتشفوا إن وإحنا نايمين، سائل خاص بيغسل الفضلات اللي بتتجمع طول اليوم."], ["Most of our dreams happen during a stage called REM sleep, when our eyes move quickly under our eyelids.", "أغلب أحلامنا بتحصل في مرحلة اسمها نوم الـ REM، لما عينينا بتتحرك بسرعة تحت جفوننا."], ["Some experts believe dreams help us process emotions. If you had been feeling stressed before bed, you are more likely to have anxious dreams.", "بعض الخبراء شايفين إن الأحلام بتساعدنا نتعامل مع مشاعرنا. لو كنت متوتر قبل النوم، احتمال أكبر تحلم أحلام قلق."], ["Unfortunately, modern life is making it harder to sleep. Screens, caffeine and late-night work all interrupt our natural rhythm.", "للأسف، الحياة الحديثة بتخلي النوم أصعب. الشاشات والكافيين والشغل لآخر الليل كلهم بيلخبطوا الإيقاع الطبيعي."], ["Long-term sleep deprivation has been linked to weight gain, poor concentration and a weaker immune system.", "قلة النوم على المدى الطويل اترتبطت بزيادة الوزن وضعف التركيز وضعف المناعة."], ["The good news is that small changes can help: a regular bedtime, a dark and cool room, and no screens for an hour before sleep.", "الخبر الحلو إن تغييرات صغيرة ممكن تساعد: ميعاد نوم ثابت، وأوضة ضلمة وباردة، ومن غير شاشات لمدة ساعة قبل النوم."], ["So tonight, instead of one more episode, why not give your brain the rest it deserves?", "فالنهارده، بدل حلقة كمان، ليه متديش مخك الراحة اللي يستاهلها؟"]], "keys": [["🗄️", "storage", "a place where things are kept"], ["🧽", "waste products", "useless substances the body needs to remove"], ["👁️", "REM sleep", "the stage of sleep when we dream most"], ["🎭", "process emotions", "to deal with and understand feelings"], ["🥁", "rhythm", "a regular repeated pattern"], ["🛡️", "immune system", "the system that protects your body from illness"]], "quiz": [{"q": "What did people use to think about sleep?", "o": ["that the body and brain simply switched off", "that it was dangerous", "that it was not needed"], "a": 0}, {"q": "What does the brain do with memories during sleep?", "o": ["moves important ones to long-term storage", "deletes all of them", "nothing"], "a": 0}, {"q": "What cleans the brain during sleep?", "o": ["a special fluid", "blue light", "caffeine"], "a": 0}, {"q": "When do most dreams happen?", "o": ["during REM sleep", "just before waking up only", "during the day"], "a": 0}, {"q": "What is linked to long-term sleep deprivation?", "o": ["weight gain and a weaker immune system", "better memory", "more energy"], "a": 0}, {"q": "Which tip does the text give?", "o": ["no screens for an hour before sleep", "drink coffee at night", "sleep in a bright room"], "a": 0}]}, "idioms": {"items": [["sleep like a log", "To sleep very deeply.", "ينام زي القتيل", "After the hike, I slept like a log.", "بعد المشي الطويل، نمت زي القتيل."], ["a night owl", "A person who likes staying up late.", "بتاع سهر", "I'm a night owl — I do my best work after midnight.", "أنا بتاع سهر — بشتغل أحسن بعد نص الليل."], ["burn the midnight oil", "To work or study late into the night.", "يسهر يشتغل أو يذاكر", "She burned the midnight oil before her final exams.", "سهرت تذاكر قبل امتحاناتها النهائية."], ["sleep on it", "To wait until tomorrow before making a decision.", "يأجل القرار لبكرة", "Don't decide now. Sleep on it and tell me tomorrow.", "متقررش دلوقتي. فكّر فيها لبكرة وقولّي."]], "quiz": [{"q": "It's a big decision. Why don't you ___?", "o": ["sleep on it", "sleep like a log", "burn the oil", "be a night owl"], "a": 0}, {"q": "I was so tired that I ___ — I didn't hear the storm!", "o": ["slept like a log", "slept on it", "burned the midnight oil", "was a night owl"], "a": 0}, {"q": "\"Burn the midnight oil\" means…", "o": ["work or study late at night", "cook at night", "light a candle", "go to bed early"], "a": 0}, {"q": "My sister loves staying up late. She's ___.", "o": ["a night owl", "a log", "midnight oil", "an early bird"], "a": 0}]}, "phrasal": {"items": [["doze off", "To fall asleep, especially without meaning to.", "يغفل / ينعس", "I dozed off in the middle of the film.", "غفلت في نص الفيلم."], ["sleep in", "To sleep later than usual in the morning.", "ينام لحد متأخر", "On Fridays, I like to sleep in until ten.", "يوم الجمعة، بحب أنام لحد الساعة ١٠."], ["stay up", "To not go to bed.", "يسهر", "We stayed up all night talking.", "سهرنا طول الليل نتكلم."], ["drift off", "To fall asleep slowly.", "ينام بالراحة / يروح في النوم", "I drifted off listening to the rain.", "رحت في النوم وأنا بسمع صوت المطر."]], "quiz": [{"q": "Don't ___ too late — you have school tomorrow.", "o": ["stay up", "sleep in", "doze off", "drift off"], "a": 0}, {"q": "It's the weekend, so I can ___.", "o": ["sleep in", "stay up early", "doze on", "drift up"], "a": 0}, {"q": "The lecture was so boring that I ___.", "o": ["dozed off", "stayed up", "slept in", "drifted up"], "a": 0}, {"q": "The soft music helped the baby ___.", "o": ["drift off", "stay up", "sleep in", "doze up"], "a": 0}]}, "slang": {"items": [["crash", "To go to sleep suddenly because you are very tired.", "يقع من التعب وينام", "I'm going to crash. Goodnight!", "أنا هقع من التعب وأنام. تصبحوا على خير!", "للصحاب"], ["pull an all-nighter", "To stay awake all night, usually to study or work.", "يسهر الليل كله", "I pulled an all-nighter before the exam.", "سهرت الليل كله قبل الامتحان.", "شائعة جدًا بين الطلاب"], ["knackered", "Extremely tired (British).", "مهدود / خلصان", "I'm absolutely knackered after work.", "أنا مهدود خالص بعد الشغل.", "سلانج بريطاني"], ["wiped out", "Completely exhausted.", "تعبان خالص", "The trip wiped me out.", "الرحلة هدّتني خالص.", "عادي جدًا"], ["catch some Zs", "To get some sleep.", "ياخد له تعسيلة", "I need to catch some Zs before the party.", "محتاج أخد تعسيلة قبل الحفلة.", "بهزار"]], "quiz": [{"q": "\"I'm knackered.\" means…", "o": ["I'm extremely tired.", "I'm very hungry.", "I'm excited.", "I'm angry."], "a": 0}, {"q": "Studying all night = ___.", "o": ["pulling an all-nighter", "catching some Zs", "crashing", "sleeping in"], "a": 0}, {"q": "\"Catch some Zs\" means…", "o": ["get some sleep", "learn the alphabet", "catch a ball", "watch TV"], "a": 0}, {"q": "After a 12-hour shift, she was ___.", "o": ["wiped out", "hyped", "sus", "epic"], "a": 0}]}, "story": {"title": "The Dream That Came True", "ar": "الحلم اللي اتحقق", "g": "m", "lines": [["For weeks, Hossam had been having the same recurring dream.", "لأسابيع، حسام كان بيحلم نفس الحلم بيتكرر."], ["In it, he was standing on a stage in front of thousands of people, playing an oud his grandfather had given him.", "فيه، كان واقف على مسرح قدام آلاف الناس، بيعزف على عود جده كان اداهوله."], ["Every time, he woke up just as the audience started clapping.", "كل مرة، كان بيصحى أول ما الجمهور بيبدأ يسقف."], ["The strange thing was that Hossam had never played music in public. He had been practising alone in his room for years, too shy to let anyone listen.", "الغريب إن حسام عمره ما عزف قدام الناس. كان بيتمرن لوحده في أوضته من سنين، مكسوف يخلي حد يسمعه."], ["One night, after he had been burning the midnight oil for an exam, he dozed off at his desk.", "في ليلة، بعد ما كان سهران يذاكر لامتحان، غفل على مكتبه."], ["This time, the dream was different. His grandfather was in the front row, smiling and nodding.", "المرة دي، الحلم كان مختلف. جده كان في الصف الأول، بيبتسم وبيهز راسه."], ["When Hossam woke up, he decided to sleep on it. The next morning, he signed up for his university's talent show.", "لما حسام صحي، قرر يفكر فيها لبكرة. تاني يوم الصبح، سجّل في مسابقة المواهب بتاعة الجامعة."], ["On the night of the show, his hands were shaking. But as soon as he started playing, the fear disappeared.", "ليلة المسابقة، إيديه كانت بتترعش. بس أول ما بدأ يعزف، الخوف اختفى."], ["When he finished, the hall exploded with applause — exactly like in his dream. This time, he didn't wake up.", "لما خلص، القاعة انفجرت بالتصفيق — بالظبط زي الحلم. المرة دي، مصحيش."], ["\"Sometimes,\" Hossam later said, \"a dream is just your heart telling you what you've been waiting for.\"", "\"أحيانًا،\" قال حسام بعدها، \"الحلم بيبقى قلبك بيقولك إنت مستني إيه.\""]], "quiz": [{"q": "What was Hossam's recurring dream about?", "o": ["playing the oud on a stage", "flying", "an exam"], "a": 0}, {"q": "Why had he never played in public?", "o": ["He was too shy.", "He couldn't play.", "He had no oud."], "a": 0}, {"q": "Who was in the front row in the new dream?", "o": ["his grandfather", "his teacher", "his best friend"], "a": 0}, {"q": "What did he do the next morning?", "o": ["signed up for the university's talent show", "sold his oud", "stopped studying"], "a": 0}, {"q": "What happened when he finished playing?", "o": ["The hall exploded with applause.", "Everyone left.", "He woke up."], "a": 0}]}, "challenge": {"title": "Sweet Dreams", "ar": "أحلام سعيدة — جاوب وسجّل", "qs": ["Describe your perfect bedtime routine.", "Tell me about the strangest dream you have ever had.", "What had you been doing before you went to bed last night?", "Do you think teenagers sleep enough? Why or why not?", "Have you ever pulled an all-nighter? Was it worth it?", "If you could control your dreams, what would you dream about?", "Should companies allow employees to take naps at work?", "What advice would you give someone with insomnia?", "Do you believe that dreams can predict the future?", "Describe a time when you were so tired that you dozed off somewhere funny."]}, "games": {"pairs": [["😱", "nightmare"], ["🛌", "nap"], ["💤", "snore"], ["☕", "caffeine"], ["🌙", "insomnia"], ["🕰️", "routine"]], "spell": [["💭", "dream"], ["🥱", "exhausted"], ["😪", "drowsy"], ["🌀", "vivid"], ["🔁", "recurring"], ["🧘", "unwind"], ["🔋", "recharge"], ["⏰", "oversleep"]], "speed": [["I'd been tossing and turning for hours.", true], ["She had been knowing him for years.", false], ["His eyes were red because he had been crying.", true], ["We hadn't been waiting long when it arrived.", true], ["How long had you been sleeping?", true], ["I had been study since 8.", false], ["They had been working for 8 a.m.", false], ["She had been reading for an hour before bed.", true], ["He has been slept well.", false], ["The ground was wet. It had been raining.", true], ["Insomnia means you sleep too much.", false], ["A nightmare is a bad dream.", true], ["\"Sleep in\" means to sleep later than usual.", true], ["\"Burn the midnight oil\" means to work late at night.", true], ["\"Knackered\" means very excited.", false], ["Blue light can keep you awake.", true]]}, "test": {"pass": 60, "sections": [{"id": "voc", "title": "Vocabulary", "ar": "المفردات", "icon": "📚", "qs": [{"q": "Not being able to sleep = ___.", "o": ["insomnia", "nightmare", "nap"], "a": 0, "pic": "🌙"}, {"q": "A frightening dream = a ___.", "o": ["nightmare", "routine", "recharge"], "a": 0, "pic": "😱"}, {"q": "A short sleep during the day = a ___.", "o": ["nap", "snore", "dream"], "a": 0, "pic": "🛌"}, {"q": "To relax after work = to ___.", "o": ["unwind", "oversleep", "snore"], "a": 0, "pic": "🧘"}, {"q": "A dream that happens again and again = a ___ dream.", "o": ["recurring", "vivid", "lucid"], "a": 0, "pic": "🔁"}, {"q": "\"مرهق جدًا\" in English is…", "o": ["exhausted", "drowsy", "awake"], "a": 0, "say": "Choose the correct word."}]}, {"id": "gra", "title": "Grammar", "ar": "القواعد", "icon": "📘", "qs": [{"q": "She was tired because she ___ all night.", "o": ["had been studying", "has studied", "studies"], "a": 0}, {"q": "How long ___ when the phone rang?", "o": ["had you been sleeping", "have you slept", "did you sleep"], "a": 0}, {"q": "He ___ well for weeks, so he went to the doctor.", "o": ["hadn't been sleeping", "hasn't slept", "doesn't sleep"], "a": 0}, {"q": "I had been waiting ___ two hours.", "o": ["for", "since", "ago"], "a": 0}, {"q": "The streets were wet. It ___.", "o": ["had been raining", "has rained", "rains"], "a": 0}, {"q": "Which is correct?", "o": ["I had been working for ten hours before I stopped.", "I had been worked for ten hours before I stopped.", "I have been working for ten hours before I stopped."], "a": 0}]}, {"id": "con", "title": "Conversation", "ar": "المحادثة", "icon": "💬", "qs": [{"q": "\"You look exhausted!\" — Best answer:", "o": ["I know. I'd been tossing and turning all night.", "Thank you!", "Exhausted is long."], "a": 0}, {"q": "\"Are you a night owl?\" — Best answer:", "o": ["Yes, I love staying up late.", "No, I am a person.", "Owls are birds."], "a": 0}, {"q": "\"Should I accept the job offer?\" — Best answer:", "o": ["Sleep on it and decide tomorrow.", "Sleep like a log.", "Burn the oil."], "a": 0}, {"q": "\"I had a weird dream last night.\" — Best answer:", "o": ["Really? Tell me about it!", "Dreams are at night.", "I am weird."], "a": 0}, {"q": "\"I'm knackered.\" — Best answer:", "o": ["Go and get some rest!", "Let's go running!", "Knackered is a car."], "a": 0}, {"q": "\"How did you sleep?\" — Best answer:", "o": ["Like a log! I feel great.", "In my bed.", "With my eyes."], "a": 0}]}, {"id": "rea", "title": "Reading", "ar": "القراءة", "icon": "📖", "passage": ["Hi, I'm Mona. Last year, I had serious insomnia.", "I had been using my phone in bed every night for months, and I hadn't been exercising at all.", "My doctor suggested a new routine: no screens after 10 p.m., a short walk every evening, and no coffee after lunch.", "At first it was hard, but after two weeks I was sleeping like a log.", "Now I wake up full of energy — and I even remember my dreams!"], "qs": [{"q": "What problem did Mona have?", "o": ["insomnia", "a broken leg", "a cold"], "a": 0}, {"q": "What had she been doing every night?", "o": ["using her phone in bed", "studying", "running"], "a": 0}, {"q": "What did her doctor suggest?", "o": ["no screens after 10 p.m., walking and no coffee after lunch", "sleeping pills", "more coffee"], "a": 0}, {"q": "How was she sleeping after two weeks?", "o": ["like a log", "badly", "for one hour"], "a": 0}, {"q": "How does she feel now?", "o": ["full of energy", "tired", "sad"], "a": 0}]}, {"id": "wri", "title": "Writing", "ar": "الكتابة", "icon": "✍️", "writing": true, "prompt": "Write about a night when you couldn't sleep OR a very strange dream (70–100 words). Explain what had been happening before. Use the Past Perfect Continuous at least twice.", "promptAr": "اكتب عن ليلة منمتش فيها أو حلم غريب جدًا (٧٠–١٠٠ كلمة). اشرح إيه اللي كان بيحصل قبلها. استخدم had been + ing مرتين على الأقل.", "checks": [["😴", "Sleep words", "x", "\\b(sleep|slept|asleep|dream|dreamed|dreamt|nightmare|bed|tired|awake|insomnia|night)\\b"], ["⏪", "Past Perfect Continuous", "x", "\\b(had|hadn't|'d)\\s+been\\s+\\w+ing\\b"], ["⏱️", "for / since / before / when", "x", "\\b(for|since|before|when|until)\\b"], ["💬", "At least 70 words", "len70"]]}]}, "watch": [{"yt": "j2PdEQpu5js", "title": "Why You Need a Good Night's Sleep", "ar": "ليه محتاج نومة كويسة — 6 Minute English", "by": "BBC Learning English", "lines": [["Sorry, I was just catching 40 winks — you know, getting some shut-eye, taking a nap.", "آسف، كنت بخطف تعسيلة — يعني بنام شوية، باخد قيلولة."], ["People who get enough sleep live about five years longer than people who don't.", "الناس اللي بتنام كفاية بتعيش حوالي ٥ سنين أكتر من اللي مش بتنام كفاية."], ["Why would it make sense to go unconscious every night, leaving yourself open to danger?", "ليه يبقى منطقي إنك تغيب عن الوعي كل ليلة وتسيب نفسك معرّض للخطر؟"], ["It can only mean that the benefits of sleep are huge.", "ده معناه بس إن فوايد النوم ضخمة."], ["After a bad night's sleep, you just can't concentrate. Your brain can't take in new information.", "بعد ليلة نوم وحشة، مش بتقدر تركز. مخك مش بيقدر يستوعب معلومات جديدة."], ["We also need to sleep after we learn new things, because that is when the brain moves information to long-term storage.", "ومحتاجين ننام بعد ما نتعلم حاجات جديدة، لأن ده الوقت اللي المخ بينقل فيه المعلومات للذاكرة الطويلة."], ["\"If you have a problem, sleep on it.\" Your brain really works on problems during the night.", "\"لو عندك مشكلة، نام عليها.\" مخك فعلًا بيشتغل على المشاكل بالليل."], ["Sleep deprivation is a form of stress, and it activates your fight-or-flight response.", "قلة النوم نوع من الضغط، وبتشغّل استجابة \"حارب أو اهرب\"."], ["Fight-or-flight describes changes in the body that make us either fight a threat or run away from it.", "حارب أو اهرب بتوصف تغييرات في الجسم بتخلينا يا نواجه الخطر يا نهرب منه."], ["Long-term lack of sleep can lead to heart disease and a weaker immune system.", "قلة النوم على المدى الطويل ممكن تسبب أمراض قلب ومناعة أضعف."], ["These are knock-on effects — results that happen indirectly.", "دي آثار جانبية — نتايج بتحصل بشكل غير مباشر."], ["The average person spends about a third of their life asleep.", "الإنسان العادي بيقضي حوالي تلت حياته نايم."]], "words": ["catch 40 winks", "shut-eye", "take a nap", "doze", "concentrate", "take in", "long-term storage", "sleep on it", "sleep deprivation", "fight-or-flight", "immune system", "knock-on effect"], "quiz": [{"q": "Why was Phil not ready at the start?", "o": ["He was sleeping.", "He was eating.", "He was on the phone."], "a": 0}, {"q": "How much longer do people who sleep enough live?", "o": ["about five years", "about one year", "twenty years"], "a": 0}, {"q": "What happens after a bad night's sleep?", "o": ["You can't concentrate.", "You feel stronger.", "You remember more."], "a": 0}, {"q": "What does \"sleep on it\" mean?", "o": ["wait before making a decision", "sleep on the floor", "never decide"], "a": 0}, {"q": "What can long-term lack of sleep lead to?", "o": ["heart disease and a weaker immune system", "better health", "more energy"], "a": 0}, {"q": "How much of our life do we spend asleep?", "o": ["about a third", "a half", "a quarter"], "a": 0}]}]}, "7": {"n": 7, "title": "Stress and Burnout", "ar": "الضغط والاحتراق النفسي — Causative + Compound Adjectives", "icon": "🔥", "cover": "img/b2/u7.jpg", "intro": "اتكلم عن ضغط الشغل والدراسة والاحتراق النفسي وإزاي توازن حياتك، واستخدم have / get something done (تخلّي حد يعملك حاجة) والصفات المركبة زي stressed-out و time-consuming.", "videos": [{"id": "b2v7", "title": "Running on Empty", "ar": "شغال على الفاضي — منى وحسن", "src": "video/b2/u7v1.mp4", "poster": "img/b2/u7v1.jpg", "sp": {"a": {"n": "Mona", "g": "f"}, "b": {"n": "Hassan", "g": "m"}}, "lines": [["a", "Hassan, are you OK? You've been working late every night this month.", "حسن، إنت كويس؟ بقالك الشهر ده كله بتشتغل لآخر الليل."], ["b", "Honestly, no. I'm completely stressed-out. I can't remember the last time I had a day off.", "بصراحة، لأ. أنا مضغوط خالص. مش فاكر آخر مرة خدت يوم إجازة."], ["a", "That sounds like burnout. Are you sleeping properly?", "ده شكله احتراق نفسي. بتنام كويس؟"], ["b", "Not really. I wake up at 3 a.m. thinking about deadlines. And I've started forgetting simple things.", "مش أوي. بصحى الساعة ٣ الفجر بفكر في المواعيد النهائية. وبدأت أنسى حاجات بسيطة."], ["a", "You're trying to do everything yourself. Why don't you get some of the work done by the new assistant?", "إنت بتحاول تعمل كل حاجة بنفسك. ليه متخليش المساعد الجديد يعمل جزء من الشغل؟"], ["b", "I suppose I could. I even fix my own computer instead of having it repaired by IT. It's so time-consuming.", "تقريبًا أقدر. أنا حتى بصلّح الكمبيوتر بنفسي بدل ما أخلّي الـ IT يصلحوه. وده بياخد وقت جدًا."], ["a", "Exactly! Delegate. And outside work, have your shopping delivered so you have more free time.", "بالظبط! وزّع الشغل. وبرة الشغل، خلّي الطلبات توصلك البيت عشان يبقى عندك وقت فاضي أكتر."], ["b", "That's a good idea. What do you do to stay calm? You always seem so laid-back.", "فكرة حلوة. إنتي بتعملي إيه عشان تفضلي هادية؟ دايمًا باينة رايقة."], ["a", "I wasn't always! Two years ago, I burned out too. Now I go for a walk every evening and switch off my work phone after seven.", "مكنتش كده على طول! من سنتين، أنا كمان احترقت نفسيًا. دلوقتي بتمشى كل يوم بالليل وبقفل موبايل الشغل بعد ٧."], ["b", "After seven? Is that allowed?", "بعد ٧؟ ده مسموح؟"], ["a", "It's my health! A tired employee isn't a productive employee. Talk to your manager — I'm sure she'll understand.", "دي صحتي! الموظف التعبان مش موظف منتج. اتكلم مع مديرتك — أنا متأكدة إنها هتفهم."], ["b", "You're right. Tomorrow I'll have a meeting with her. And this weekend, I'm going to do absolutely nothing!", "عندك حق. بكرة هعمل معاها ميتنج. والويك إند ده، مش هعمل أي حاجة خالص!"]], "quiz": [{"q": "What is Hassan's problem?", "o": ["He's stressed-out and may have burnout.", "He lost his job.", "He is bored."], "a": 0}, {"q": "When does Hassan wake up?", "o": ["at 3 a.m.", "at 7 a.m.", "at noon"], "a": 0}, {"q": "What does Mona suggest about work?", "o": ["getting some work done by the new assistant", "working more hours", "quitting"], "a": 0}, {"q": "What does Mona do every evening?", "o": ["goes for a walk and switches off her work phone", "works late", "watches the news"], "a": 0}, {"q": "What will Hassan do this weekend?", "o": ["absolutely nothing", "work at the office", "fix his computer"], "a": 0}], "fill": [[1, "stressed-out"], [1, "day off"], [2, "burnout"], [3, "deadlines"], [4, "get some of the work done"], [5, "repaired"], [5, "time-consuming"], [6, "Delegate"], [6, "delivered"], [7, "laid-back"], [8, "burned out"], [10, "productive"]]}], "vocab": [{"t": "Stress", "ar": "الضغط", "items": [["😩", "stressed-out", "I'm so stressed-out about my exams."], ["🔥", "burnout", "Working 80 hours a week can lead to burnout."], ["⏰", "deadline", "The deadline is tomorrow morning."], ["🏋️", "workload", "My workload has doubled this month."], ["😰", "anxiety", "Exams can cause anxiety."], ["🤯", "overwhelmed", "I feel overwhelmed by all this work."], ["🔋", "drained", "I feel completely drained."], ["😤", "pressure", "I'm under a lot of pressure at work."]]}, {"t": "Coping", "ar": "التعامل مع الضغط", "items": [["🧘", "cope with", "How do you cope with stress?"], ["🤲", "delegate", "Good managers delegate tasks."], ["⚖️", "work-life balance", "I need a better work-life balance."], ["🚶", "take a break", "Take a break every hour."], ["📵", "switch off", "I switch off my phone after 7."], ["🗒️", "prioritise", "Prioritise the most important tasks."], ["💆", "self-care", "Self-care is not selfish."], ["🎯", "set boundaries", "Learn to set boundaries at work."]]}, {"t": "Compound adjectives", "ar": "صفات مركبة", "items": [["⌛", "time-consuming", "Writing reports is very time-consuming."], ["😌", "laid-back", "My boss is very laid-back."], ["💼", "hard-working", "She is a hard-working employee."], ["😴", "sleep-deprived", "Sleep-deprived workers make more mistakes."], ["🌍", "well-known", "He is a well-known psychologist."], ["🧠", "open-minded", "Be open-minded about new ideas."], ["🔥", "short-tempered", "He's short-tempered when he's tired."], ["📆", "full-time", "She has a full-time job."]]}], "talk": [{"title": "Let's Talk · Student A", "ar": "الطالب A", "list": [["What stresses you out the most?", "إيه أكتر حاجة بتضغطك؟", "Exams and not having enough time."], ["How do you know when you are too stressed?", "بتعرف إزاي إنك مضغوط زيادة؟", "I can't sleep and I get short-tempered."], ["What do you do to relax after a long day?", "بتعمل إيه عشان ترتاح بعد يوم طويل؟", "I play football or listen to music."], ["Do you have a good work-life (or study-life) balance?", "عندك توازن كويس بين الشغل والحياة؟", "Not really. I need to take more breaks."], ["Is some stress good for us?", "شوية ضغط ممكن يكون كويس؟", "Yes, a little stress helps me focus."]]}, {"title": "Let's Talk · Student B", "ar": "الطالب B", "list": [["Why do so many young people feel burnt out today?", "ليه شباب كتير حاسين بالاحتراق النفسي النهارده؟", "Social media and too much competition."], ["Should companies limit working hours?", "الشركات لازم تحدد ساعات الشغل؟", "Yes, tired workers are not productive."], ["What things do you get done by others to save time?", "إيه الحاجات اللي بتخلي حد يعملهالك عشان توفر وقت؟", "I have my groceries delivered."], ["Is it OK to say \"no\" to your boss or teacher?", "ينفع تقول \"لأ\" لمديرك أو مدرسك؟", "Yes, politely, if you have too much work."], ["What advice would you give a friend who is burning out?", "تنصح بإيه صاحبك اللي بيحترق نفسيًا؟", "Talk to someone and take a real break."]]}], "grammar": {"title": "Causative & Compound Adjectives", "ar": "have / get something done + الصفات المركبة", "blocks": [{"type": "intro", "en": "PART 1 — Causative: we use 'have/get + object + past participle' when someone ELSE does something for us (usually a service). PART 2 — Compound adjectives join two words with a hyphen to make one adjective.", "ar": "الجزء ١ — Causative: بنستخدم have/get + حاجة + p.p. لما حد تاني يعملّنا الحاجة (خدمة غالبًا). الجزء ٢ — الصفات المركبة: كلمتين بينهم شرطة بيعملوا صفة واحدة."}, {"type": "big", "items": [{"v": "have + object + p.p.", "p": "someone does it for me", "c": 1, "eg": ["I had my computer repaired by IT.", "She has her shopping delivered every week.", "We're having our flat painted."]}, {"v": "get + object + p.p.", "p": "more informal", "c": 2, "eg": ["Get some of the work done by the assistant.", "I need to get my hair cut.", "He got his phone fixed yesterday."]}, {"v": "number / adjective / noun + - + word", "p": "compound adjectives", "c": 3, "eg": ["a time-consuming task", "a stressed-out student", "a two-hour meeting", "a well-known doctor"]}]}, {"type": "table", "title": "🛠️ Causative in different tenses", "head": ["Tense", "Example"], "rows": [["Present simple", "I have my car washed every Friday."], ["Past simple", "She had her eyes tested last week."], ["Present continuous", "We're having the kitchen redecorated."], ["Future", "I'll get the report checked tomorrow."], ["Modal", "You should have your blood pressure checked."]]}, {"type": "table", "title": "🔗 Common compound adjectives", "head": ["Pattern", "Examples"], "rows": [["adjective + noun-ed", "open-minded · short-tempered · kind-hearted"], ["noun + -ing", "time-consuming · English-speaking · record-breaking"], ["well / badly + p.p.", "well-known · well-paid · badly-organised"], ["number + noun (singular!)", "a ten-minute break · a five-day week"], ["adjective + -ing / p.p.", "good-looking · stressed-out · laid-back"]]}, {"type": "tip", "en": "Causative ≠ doing it yourself: 'I repaired my car' (I did it) vs 'I had my car repaired' (a mechanic did it). With numbers, the noun stays singular: a two-hours meeting ✖ → a two-hour meeting ✔.", "ar": "I repaired my car = أنا صلحتها بنفسي. I had my car repaired = الميكانيكي صلحها. ومع الأرقام الاسم يفضل مفرد: a two-hour meeting."}]}, "exercises": [{"type": "mcq", "title": "Causative & Compound Adjectives — 10 MCQs", "ar": "اختار الصح", "speak": true, "items": [{"q": "I don't fix my computer myself. I ___ by IT.", "o": ["have it repaired", "repair it", "have repaired it", "am repairing"], "a": 0}, {"q": "She ___ her shopping delivered every week.", "o": ["has", "makes", "does", "is"], "a": 0}, {"q": "You should get your eyes ___. You keep getting headaches.", "o": ["tested", "test", "testing", "to test"], "a": 0}, {"q": "We're ___ our flat painted next week.", "o": ["having", "doing", "making", "taking"], "a": 0}, {"q": "He ___ his hair cut yesterday.", "o": ["got", "gets", "has get", "getting"], "a": 0}, {"q": "Writing reports is very ___.", "o": ["time-consuming", "time-consumed", "consuming-time", "time-consume"], "a": 0}, {"q": "We had a ___ meeting this morning.", "o": ["two-hour", "two-hours", "two hours", "hours-two"], "a": 0}, {"q": "My manager is very relaxed and ___.", "o": ["laid-back", "back-laid", "laid-backed", "laying-back"], "a": 0}, {"q": "Which sentence means a mechanic repaired the car?", "o": ["I had my car repaired.", "I repaired my car.", "I was repairing my car.", "I have repaired my car."], "a": 0}, {"q": "Which is a correct compound adjective?", "o": ["a well-known writer", "a known-well writer", "a well-knowing writer", "a well-know writer"], "a": 0}]}, {"type": "mcq", "title": "Who did it?", "ar": "مين عمل الحاجة؟", "items": [{"q": "\"I cut my hair.\" → ___", "o": ["I did it myself", "a hairdresser did it"], "a": 0}, {"q": "\"I had my hair cut.\" → ___", "o": ["a hairdresser did it", "I did it myself"], "a": 0}, {"q": "Causative structure = have/get + object + ___", "o": ["past participle", "-ing"], "a": 0}, {"q": "A student who is very stressed = a ___ student.", "o": ["stressed-out", "stress-outing"], "a": 0}, {"q": "A holiday that lasts ten days = a ___ holiday.", "o": ["ten-day", "ten-days"], "a": 0}]}, {"type": "ord", "title": "Make sentences", "ar": "رتّب الكلمات", "items": [{"c": ["I", "had", "my laptop", "repaired"], "a": [0, 1, 2, 3]}, {"c": ["She", "gets", "her groceries", "delivered"], "a": [0, 1, 2, 3]}, {"c": ["It was", "a very", "time-consuming", "project"], "a": [0, 1, 2, 3]}, {"c": ["We", "are having", "the office", "cleaned"], "a": [0, 1, 2, 3]}]}], "reading": {"title": "When Work Becomes Too Much", "ar": "لما الشغل يزيد عن حده", "g": "m", "lines": [["In 2019, the World Health Organization officially recognised burnout as a \"workplace phenomenon\". It is not simply feeling tired after a busy week.", "في ٢٠١٩، منظمة الصحة العالمية اعترفت رسميًا بالاحتراق النفسي كـ\"ظاهرة في بيئة العمل\". وده مش مجرد إنك تحس بتعب بعد أسبوع مزحوم."], ["Burnout is a state of physical and emotional exhaustion caused by long-term stress.", "الاحتراق النفسي حالة إرهاق جسدي ونفسي سببها ضغط طويل المدى."], ["Experts describe three main signs: feeling drained of energy, feeling negative or distant from your job, and becoming less productive.", "الخبراء بيوصفوا ٣ علامات أساسية: إنك تحس طاقتك مستنزفة، وإنك تحس بسلبية أو بُعد عن شغلك، وإنك تبقى أقل إنتاجية."], ["People with burnout often say they feel like they are \"running on empty\".", "الناس اللي عندها احتراق نفسي كتير بيقولوا إنهم حاسين إنهم \"شغالين على الفاضي\"."], ["Why is burnout becoming so common? One reason is that technology has made it difficult to switch off. Many employees check their emails late at night and even on holiday.", "ليه الاحتراق النفسي بقى منتشر كده؟ من الأسباب إن التكنولوجيا خلت الفصل صعب. موظفين كتير بيشوفوا الإيميلات لآخر الليل وحتى في الإجازات."], ["Students face similar pressure, with long hours of study, private lessons and the fear of failure.", "والطلاب بيواجهوا ضغط شبه كده، بساعات مذاكرة طويلة ودروس خصوصية وخوف من الفشل."], ["The good news is that burnout can be prevented. Experts recommend setting clear boundaries — for example, not answering work messages after a certain time.", "الخبر الحلو إن الاحتراق النفسي ممكن نمنعه. الخبراء بينصحوا بوضع حدود واضحة — مثلًا، متردش على رسايل الشغل بعد وقت معين."], ["Learning to delegate is also important. Not every task needs to be done by you; you can have some jobs done by colleagues or services.", "وكمان مهم تتعلم توزّع الشغل. مش كل مهمة لازم إنت اللي تعملها؛ ممكن تخلّي زمايلك أو خدمات يعملوا جزء."], ["Regular exercise, enough sleep and time with friends all help the brain recover from stress.", "الرياضة المنتظمة، والنوم الكافي، والوقت مع الصحاب، كلهم بيساعدوا المخ يتعافى من الضغط."], ["Perhaps the most important lesson is this: rest is not a reward for finishing your work. Rest is part of the work.", "يمكن أهم درس هو ده: الراحة مش مكافأة إنك خلصت شغلك. الراحة جزء من الشغل."]], "keys": [["🏢", "workplace", "the place where people work"], ["🔋", "drained", "having no energy left"], ["🚫", "boundaries", "limits you set to protect yourself"], ["🛑", "prevent", "to stop something from happening"], ["🤲", "delegate", "to give part of your work to someone else"], ["♻️", "recover", "to become healthy again"]], "quiz": [{"q": "What did the WHO do in 2019?", "o": ["recognised burnout as a workplace phenomenon", "banned working at night", "closed many companies"], "a": 0}, {"q": "What is burnout?", "o": ["exhaustion caused by long-term stress", "feeling tired after one busy day", "a type of fever"], "a": 0}, {"q": "Which is a sign of burnout?", "o": ["becoming less productive", "having more energy", "loving your job more"], "a": 0}, {"q": "How has technology made burnout more common?", "o": ["It is difficult to switch off.", "It has made work easier.", "It stops people from working."], "a": 0}, {"q": "What do experts recommend?", "o": ["setting clear boundaries and delegating", "working on holiday", "never resting"], "a": 0}, {"q": "What is the most important lesson, according to the text?", "o": ["Rest is part of the work.", "Rest is only for lazy people.", "Work never ends."], "a": 0}]}, "idioms": {"items": [["burn the candle at both ends", "To work very hard and sleep very little.", "يحرق نفسه في الشغل والسهر", "You can't burn the candle at both ends forever — you'll get sick.", "مينفعش تحرق نفسك في الشغل والسهر على طول — هتتعب."], ["bite off more than you can chew", "To try to do more than you are able to.", "يحمّل نفسه فوق طاقته", "I took three jobs at once. I bit off more than I could chew.", "خدت ٣ شغلانات مرة واحدة. حمّلت نفسي فوق طاقتي."], ["at the end of your rope", "Having no more patience or energy.", "خلاص على آخره", "After a week with no sleep, I was at the end of my rope.", "بعد أسبوع من غير نوم، كنت على آخري خالص."], ["let off steam", "To do something to release stress or anger.", "يفرّغ طاقته / يطلّع الضغط", "I play football on Fridays to let off steam.", "بلعب كورة يوم الجمعة عشان أفرّغ الضغط."]], "quiz": [{"q": "He works all day and studies all night. He's ___.", "o": ["burning the candle at both ends", "letting off steam", "at the end of the rope", "chewing"], "a": 0}, {"q": "I go running after work to ___.", "o": ["let off steam", "bite off more", "burn the candle", "end the rope"], "a": 0}, {"q": "\"Bite off more than you can chew\" means…", "o": ["try to do too much", "eat too fast", "be very hungry", "chew gum"], "a": 0}, {"q": "\"I'm at the end of my rope.\" means…", "o": ["I have no more patience or energy.", "I am climbing.", "I am very happy.", "I am tied up."], "a": 0}]}, "phrasal": {"items": [["burn out", "To become extremely tired from working too hard.", "يحترق نفسيًا من الشغل", "If you don't take breaks, you'll burn out.", "لو مخدتش بريكات، هتحترق نفسيًا."], ["wind down", "To relax after a period of work or stress.", "يهدّى ويرتاح", "I read a book in the evening to wind down.", "بقرا كتاب بالليل عشان أهدّى."], ["cut back on", "To reduce the amount of something.", "يقلل من", "I'm trying to cut back on coffee.", "بحاول أقلل القهوة."], ["pile up", "To increase in amount, especially in an unwanted way.", "يتراكم", "While I was sick, the emails piled up.", "وأنا عيان، الإيميلات اتراكمت."]], "quiz": [{"q": "After a busy day, I take a hot shower to ___.", "o": ["wind down", "burn out", "pile up", "cut back"], "a": 0}, {"q": "I was on holiday for a week and the work ___.", "o": ["piled up", "wound down", "burned out", "cut back"], "a": 0}, {"q": "The doctor told him to ___ sugar.", "o": ["cut back on", "pile up", "wind down", "burn out"], "a": 0}, {"q": "Nurses who work 14-hour shifts often ___.", "o": ["burn out", "wind up", "pile on", "cut back"], "a": 0}]}, "slang": {"items": [["touch grass", "Go outside and take a break from the internet.", "انزل الشارع / سيب النت شوية", "You've been gaming for ten hours. Go touch grass!", "بقالك ١٠ ساعات بتلعب. انزل اتمشى شوية!", "بهزار بين الصحاب"], ["it's a lot", "It is too much / overwhelming.", "ده كتير / فوق الطاقة", "Three exams in one day? That's a lot.", "تلات امتحانات في يوم واحد؟ ده كتير أوي.", "عادي جدًا"], ["me time", "Time for yourself to relax.", "وقت لنفسي", "Sunday evening is my me time — no phone, no work.", "الحد بالليل ده وقتي لنفسي — لا موبايل ولا شغل.", "تعبير منتشر جدًا"], ["freak out", "To become very anxious or upset suddenly.", "يتخض / يتوتر جامد", "Don't freak out — we still have time to finish.", "متتخضش — لسه عندنا وقت نخلص.", "للصحاب"], ["vibe check", "Checking how someone feels or the mood of a situation.", "نطمّن على المود", "Quick vibe check: how is everyone feeling today?", "نطمّن بسرعة: الكل عامل إيه النهارده؟", "سلانج حديث ولطيف"]], "quiz": [{"q": "\"Go touch grass!\" means…", "o": ["Go outside and take a break from screens.", "Go to the garden and work.", "Plant some grass.", "Play football."], "a": 0}, {"q": "\"Saturday morning is my ___.\" (time for myself)", "o": ["me time", "vibe check", "touch grass", "freak out"], "a": 0}, {"q": "\"Don't freak out!\" means…", "o": ["Don't panic!", "Don't sleep!", "Don't go out!", "Don't eat!"], "a": 0}, {"q": "Your friend asks how the team is feeling. It's a ___.", "o": ["vibe check", "me time", "touch grass", "it's a lot"], "a": 0}]}, "story": {"title": "The Day Karim Stopped", "ar": "اليوم اللي كريم وقف فيه", "g": "f", "lines": [["Karim was the most hard-working employee in the company. He arrived first, left last and answered emails at midnight.", "كريم كان أشطر موظف في الشركة. أول واحد يوصل، وآخر واحد يمشي، وبيرد على الإيميلات الساعة ١٢ بالليل."], ["He never asked for help. He even had his lunch delivered to his desk so he wouldn't waste time.", "عمره ما طلب مساعدة. حتى كان بيخلّي الغدا يوصله على المكتب عشان ميضيعش وقت."], ["For months, he had been burning the candle at both ends, sleeping only four or five hours a night.", "لشهور، كان بيحرق نفسه في الشغل والسهر، بينام ٤ أو ٥ ساعات بس في الليلة."], ["One Monday morning, in the middle of an important presentation, Karim suddenly stopped speaking. His mind went completely blank.", "في صباح يوم اتنين، في نص عرض مهم، كريم فجأة بطّل يتكلم. مخه فضي خالص."], ["He apologised, walked out of the room and sat in his car for an hour, unable to move.", "اعتذر، وخرج من الأوضة، وقعد في عربيته ساعة، مش قادر يتحرك."], ["The doctor's answer was simple: \"You're burnt out. You need at least two weeks of complete rest.\"", "إجابة الدكتور كانت بسيطة: \"إنت محترق نفسيًا. محتاج أسبوعين على الأقل راحة تامة.\""], ["At first, Karim felt guilty. But slowly, he started to wind down. He walked by the Nile, called old friends and slept nine hours a night.", "في الأول، كريم حس بالذنب. بس شوية بشوية، بدأ يهدى. اتمشى جنب النيل، وكلّم صحاب قدام، ونام ٩ ساعات في الليلة."], ["When he returned to work, he was different. He delegated tasks, had his reports checked by his team, and switched off his phone after seven.", "لما رجع الشغل، كان مختلف. وزّع المهام، وخلّى فريقه يراجع تقاريره، وبقى يقفل موبايله بعد ٧."], ["Surprisingly, his work became better, not worse.", "والمفاجأة إن شغله بقى أحسن، مش أوحش."], ["\"I used to think rest was a waste of time,\" he told a new colleague. \"Now I know it's the most productive thing I do.\"", "\"كنت فاكر إن الراحة تضييع وقت،\" قال لزميل جديد. \"دلوقتي عارف إنها أكتر حاجة منتجة بعملها.\""]], "quiz": [{"q": "How did Karim work before?", "o": ["He arrived first, left last and answered emails at midnight.", "He worked from home.", "He worked two days a week."], "a": 0}, {"q": "What happened during the presentation?", "o": ["His mind went blank.", "He won an award.", "He fell asleep."], "a": 0}, {"q": "What did the doctor say?", "o": ["He was burnt out and needed two weeks of rest.", "He had a cold.", "He should work more."], "a": 0}, {"q": "What did he do differently when he returned?", "o": ["delegated tasks and switched off his phone after seven", "worked even more", "stopped talking to his team"], "a": 0}, {"q": "What does Karim think about rest now?", "o": ["It's the most productive thing he does.", "It's a waste of time.", "It's only for weekends."], "a": 0}]}, "challenge": {"title": "Beat the Burnout", "ar": "اهزم الاحتراق النفسي — جاوب وسجّل", "qs": ["Describe the most stressful week you have ever had.", "What are the warning signs that someone is burning out?", "What things do you have done for you to save time?", "Should students have homework at the weekend? Why or why not?", "How do you let off steam?", "Is it possible to be successful without being stressed?", "Describe a laid-back person you know. What can we learn from them?", "Have you ever bitten off more than you could chew? What happened?", "What would your perfect \"me time\" look like?", "If you were the boss, what would you do to protect your employees from burnout?"]}, "games": {"pairs": [["🔥", "burnout"], ["⏰", "deadline"], ["🤲", "delegate"], ["🔋", "drained"], ["😌", "laid-back"], ["⌛", "time-consuming"]], "spell": [["😩", "stressed-out"], ["🏋️", "workload"], ["😰", "anxiety"], ["🤯", "overwhelmed"], ["😤", "pressure"], ["🗒️", "prioritise"], ["💆", "self-care"], ["💼", "hard-working"]], "speed": [["I had my car repaired.", true], ["I had repaired my car by a mechanic.", false], ["She gets her groceries delivered.", true], ["You should get your eyes tested.", true], ["We are having the house paint.", false], ["It was a two-hour meeting.", true], ["It was a two-hours meeting.", false], ["He is very open-minded.", true], ["Writing reports is time-consumed.", false], ["She has her hair cut every month.", true], ["Burnout is exhaustion caused by long-term stress.", true], ["To delegate means to do everything yourself.", false], ["\"Wind down\" means to relax.", true], ["\"Touch grass\" means take a break from screens.", true], ["\"Let off steam\" means to cook.", false], ["A laid-back person is relaxed.", true]]}, "test": {"pass": 60, "sections": [{"id": "voc", "title": "Vocabulary", "ar": "المفردات", "icon": "📚", "qs": [{"q": "Exhaustion caused by long-term stress = ___.", "o": ["burnout", "deadline", "workload"], "a": 0, "pic": "🔥"}, {"q": "To give some of your work to others = to ___.", "o": ["delegate", "prioritise", "overwhelm"], "a": 0, "pic": "🤲"}, {"q": "Taking a lot of time = ___.", "o": ["time-consuming", "laid-back", "full-time"], "a": 0, "pic": "⌛"}, {"q": "Having no energy left = ___.", "o": ["drained", "open-minded", "productive"], "a": 0, "pic": "🔋"}, {"q": "The amount of work you have = your ___.", "o": ["workload", "boundary", "self-care"], "a": 0, "pic": "🏋️"}, {"q": "\"مضغوط جدًا\" in English is…", "o": ["stressed-out", "laid-back", "well-known"], "a": 0, "say": "Choose the correct word."}]}, {"id": "gra", "title": "Grammar", "ar": "القواعد", "icon": "📘", "qs": [{"q": "I don't cut my hair myself. I ___ it cut.", "o": ["have", "do", "make"], "a": 0}, {"q": "She got her phone ___ yesterday.", "o": ["fixed", "fix", "fixing"], "a": 0}, {"q": "We are having our kitchen ___.", "o": ["painted", "paint", "painting"], "a": 0}, {"q": "It was a ___ walk.", "o": ["three-hour", "three-hours", "three hours"], "a": 0}, {"q": "He is a ___ doctor. Everyone knows him.", "o": ["well-known", "known-well", "well-knowing"], "a": 0}, {"q": "Which means someone else did it?", "o": ["I had the report checked.", "I checked the report.", "I was checking the report."], "a": 0}]}, {"id": "con", "title": "Conversation", "ar": "المحادثة", "icon": "💬", "qs": [{"q": "\"You look stressed-out.\" — Best answer:", "o": ["I am. I have three deadlines this week.", "Thank you, I like stress.", "Out is a direction."], "a": 0}, {"q": "\"How do you let off steam?\" — Best answer:", "o": ["I go swimming after work.", "I cook with steam.", "Steam is hot."], "a": 0}, {"q": "\"I have too much work!\" — Best answer:", "o": ["Why not delegate some of it?", "Do more work!", "Work is a noun."], "a": 0}, {"q": "\"Three exams in one day?\" — Best answer:", "o": ["I know, it's a lot.", "It's a little.", "Exams are papers."], "a": 0}, {"q": "\"I'm at the end of my rope.\" — Best answer:", "o": ["Take a break. You need it.", "Buy a longer rope.", "Climb faster."], "a": 0}, {"q": "\"Did you fix your laptop?\" — Best answer:", "o": ["No, I had it fixed at a shop.", "Yes, I had it fix.", "Laptop is fixed."], "a": 0}]}, {"id": "rea", "title": "Reading", "ar": "القراءة", "icon": "📖", "passage": ["Hi, I'm Nadia. I'm a nurse, and last year I almost burned out.", "I was working twelve-hour shifts and sleeping only five hours a night.", "Now I set clear boundaries. I have my groceries delivered, so I have more time to rest.", "Every Friday I go to a dance class to let off steam.", "I'm still hard-working, but now I'm also happy and healthy."], "qs": [{"q": "What is Nadia's job?", "o": ["nurse", "teacher", "engineer"], "a": 0}, {"q": "How long were her shifts?", "o": ["twelve hours", "five hours", "eight hours"], "a": 0}, {"q": "What does she have delivered?", "o": ["her groceries", "her clothes", "her books"], "a": 0}, {"q": "What does she do every Friday?", "o": ["a dance class", "extra work", "shopping"], "a": 0}, {"q": "How is she now?", "o": ["hard-working, happy and healthy", "tired and sad", "unemployed"], "a": 0}]}, {"id": "wri", "title": "Writing", "ar": "الكتابة", "icon": "✍️", "writing": true, "prompt": "Write an email to a friend who is very stressed (70–100 words). Give advice to help them avoid burnout. Use the causative (have/get something done) and at least two compound adjectives.", "promptAr": "اكتب إيميل لصاحبك المضغوط جدًا (٧٠–١٠٠ كلمة) وانصحه إزاي يتجنب الاحتراق النفسي. استخدم have/get something done وصفتين مركبتين على الأقل.", "checks": [["🔥", "Stress words", "x", "\\b(stress|stressed|burnout|burn out|tired|deadline|break|relax|rest|sleep|balance|delegate|pressure)\\b"], ["🛠️", "Causative", "x", "\\b(have|has|had|get|gets|got|having|getting)\\s+(\\w+\\s+){1,3}(done|delivered|cleaned|checked|fixed|repaired|cut|made|painted|washed|cooked|tested)\\b"], ["🔗", "Compound adjective", "x", "\\b[a-z]+-[a-z]+\\b"], ["💬", "At least 70 words", "len70"]]}]}, "watch": [{"yt": "QdE63sYqwd8", "title": "Why Are We All So Stressed?", "ar": "ليه كلنا مضغوطين كده؟ — 6 Minute English", "by": "BBC Learning English", "lines": [["Worrying about work or exams, war and climate change in the news — it's no wonder modern life is stressful.", "القلق من الشغل والامتحانات، والحروب وتغير المناخ في الأخبار — مش غريب إن الحياة الحديثة مرهقة."], ["Not having enough time to do something really makes me stressed out.", "إني مكونش عندي وقت كفاية أعمل حاجة، ده بيضغطني جدًا."], ["When I feel stressed, I try to slow down, pause, take a breath and think: everything will be OK again.", "لما بحس بضغط، بحاول أهدّي، وأوقف، وآخد نفس، وأفكر: كل حاجة هتبقى تمام تاني."], ["Many young people use the word \"overwhelm\" to describe their feelings.", "شباب كتير بيستخدموا كلمة overwhelm عشان يوصفوا مشاعرهم."], ["Overwhelm is an emotional state where you feel overloaded and feel you can't cope.", "الـ overwhelm حالة نفسية بتحس فيها إنك محمّل زيادة ومش قادر تتحمل."], ["If it becomes chronic stress, it might lead to burnout in the end.", "لو بقى ضغط مزمن، ممكن يوصل في الآخر لاحتراق نفسي."], ["Burnout is mental or physical exhaustion caused by working too hard.", "الاحتراق النفسي إرهاق ذهني أو جسدي سببه الشغل الزيادة."], ["It's normal to feel nerves before an exam. Nerves can actually sharpen your thinking.", "طبيعي تحس بتوتر قبل الامتحان. التوتر ممكن فعلًا يخلي تفكيرك أحد."], ["It's OK to be good enough, rather than always trying for perfection.", "عادي إنك تبقى كويس كفاية، بدل ما تحاول توصل للكمال على طول."], ["There's no one-size-fits-all solution for stress.", "مفيش حل واحد يناسب الكل للضغط."], ["Accept that your to-do list is never going to end. That is just a sign of a busy life.", "اقبل إن قايمة المهام بتاعتك عمرها ما هتخلص. ده مجرد علامة على حياة مزحومة."], ["According to research, the most restful activity is… reading.", "حسب الأبحاث، أكتر نشاط مريح هو… القراية."]], "words": ["stressful", "stressed out", "cope", "overwhelm", "overloaded", "chronic", "burnout", "exhaustion", "nerves", "perfection", "one-size-fits-all", "to-do list"], "quiz": [{"q": "What makes Neil stressed out?", "o": ["not having enough time", "reading", "music"], "a": 0}, {"q": "What does \"overwhelm\" describe?", "o": ["feeling overloaded and unable to cope", "feeling very happy", "feeling hungry"], "a": 0}, {"q": "What can chronic stress lead to?", "o": ["burnout", "better sleep", "more free time"], "a": 0}, {"q": "How can nerves help before an exam?", "o": ["They can sharpen your thinking.", "They make you forget everything.", "They help you sleep."], "a": 0}, {"q": "What should we accept about our to-do list?", "o": ["It is never going to end.", "It must be finished today.", "It is not important."], "a": 0}, {"q": "What is the most restful activity, according to research?", "o": ["reading", "walking in nature", "listening to music"], "a": 0}]}]}}, "final": {"pass": 60, "sections": [{"id": "lis", "title": "Listening", "ar": "الاستماع", "icon": "🎧", "listen": true, "qs": [{"audio": "The window wasn't broken and the door was locked, so the thief must have had a key.", "g": "m", "q": "How did the thief probably get in?", "o": ["with a key", "through the window", "through the roof"], "a": 0}, {"audio": "The actor denied having an argument with the director, but he admitted feeling tired after filming.", "g": "f", "q": "What did the actor admit?", "o": ["feeling tired", "arguing with the director", "leaving the film"], "a": 0}, {"audio": "By the end of next month, our volunteers will have been working in the village for a whole year.", "g": "f2", "q": "How long will the volunteers have been working by next month?", "o": ["a whole year", "one month", "two weeks"], "a": 0}, {"audio": "If I hadn't broken my leg skiing, I would be running the marathon with you today.", "g": "m2", "q": "Why isn't he running the marathon?", "o": ["He broke his leg.", "He doesn't like running.", "He is working."], "a": 0}, {"audio": "Despite feeling nervous, she made eye contact and smiled, so as to look confident.", "g": "f", "q": "Why did she make eye contact and smile?", "o": ["to look confident", "because she was bored", "to stop the meeting"], "a": 0}, {"audio": "I'd been scrolling on my phone for three hours before I finally fell asleep.", "g": "m", "q": "What had he been doing before he fell asleep?", "o": ["scrolling on his phone", "reading a book", "studying"], "a": 0}, {"audio": "I was so stressed-out that I had my groceries delivered and took a three-day break.", "g": "f2", "q": "What did she have delivered?", "o": ["her groceries", "her laptop", "flowers"], "a": 0}, {"audio": "He was caught red-handed, but he only got a slap on the wrist.", "g": "m2", "q": "What kind of punishment did he get?", "o": ["a very light one", "a very hard one", "no punishment at all because he ran away"], "a": 0}]}, {"id": "voc", "title": "Vocabulary", "ar": "المفردات", "icon": "📚", "qs": [{"q": "Facts or objects that prove a crime = ___.", "o": ["evidence", "privacy", "insomnia"], "a": 0, "pic": "🔍"}, {"q": "Photographers who follow celebrities = ___.", "o": ["paparazzi", "volunteers", "witnesses"], "a": 0, "pic": "📸"}, {"q": "To give money to help others = to ___.", "o": ["donate", "delegate", "deny"], "a": 0, "pic": "💰"}, {"q": "Very careful to avoid danger = ___.", "o": ["cautious", "reckless", "drowsy"], "a": 0, "pic": "🙈"}, {"q": "The way you stand or sit = your ___.", "o": ["posture", "gesture", "nightmare"], "a": 0, "pic": "🧍"}, {"q": "Not being able to sleep = ___.", "o": ["insomnia", "burnout", "adrenaline"], "a": 0, "pic": "🌙"}, {"q": "Exhaustion caused by long-term stress = ___.", "o": ["burnout", "fame", "charity"], "a": 0, "pic": "🔥"}, {"q": "\"Spill the tea\" means…", "o": ["share gossip", "make tea", "clean the table"], "a": 0, "pic": "☕"}]}, {"id": "gra", "title": "Grammar", "ar": "القواعد", "icon": "📘", "qs": [{"q": "He ___ the money. He was abroad that week.", "o": ["can't have taken", "must have taken", "might take"], "a": 0}, {"q": "She refused ___ the question.", "o": ["to answer", "answering", "answer"], "a": 0}, {"q": "By 2030, they ___ a new hospital.", "o": ["will have built", "will build have", "have built"], "a": 0}, {"q": "If I had studied medicine, I ___ a doctor now.", "o": ["would be", "would have been", "will be"], "a": 0}, {"q": "___ the rain, we went hiking.", "o": ["Despite", "Although", "Unless"], "a": 0}, {"q": "He was tired because he ___ all night.", "o": ["had been working", "has worked", "works"], "a": 0}, {"q": "I had my phone ___ yesterday.", "o": ["repaired", "repair", "repairing"], "a": 0}, {"q": "It was a ___ journey.", "o": ["five-hour", "five-hours", "five hours"], "a": 0}]}, {"id": "rea", "title": "Reading", "ar": "القراءة", "icon": "📖", "passage": ["Hi, I'm Yassin. Two years ago, I was a stressed-out university student who had been sleeping four hours a night.", "One day, a friend invited me to volunteer at a camp for children in Sinai. I almost backed out, but I took the plunge.", "Despite having no experience, I taught the kids English and learned rock climbing with them.", "If I hadn't gone on that trip, I wouldn't be studying to become a teacher now.", "By next summer, I will have been volunteering at the camp for three years. It changed my life!"], "qs": [{"q": "How was Yassin two years ago?", "o": ["stressed-out and sleeping very little", "relaxed and happy", "famous"], "a": 0}, {"q": "Where did he volunteer?", "o": ["at a camp for children in Sinai", "at a hospital", "at a bank"], "a": 0}, {"q": "What did he teach the children?", "o": ["English", "maths", "football"], "a": 0}, {"q": "What is he studying to become now?", "o": ["a teacher", "a doctor", "a climber"], "a": 0}, {"q": "How long will he have been volunteering by next summer?", "o": ["three years", "two months", "one year"], "a": 0}]}, {"id": "wri", "title": "Writing", "ar": "الكتابة", "icon": "✍️", "writing": true, "prompt": "Write an opinion essay (100–150 words): \"Young people today are under too much pressure.\" Do you agree? Give reasons and examples, and use at least four B2 grammar points.", "promptAr": "اكتب مقال رأي (١٠٠–١٥٠ كلمة): \"الشباب النهارده تحت ضغط زيادة عن اللزوم.\" موافق؟ ادّي أسباب وأمثلة واستخدم ٤ قواعد على الأقل من مستوى B2.", "checks": [["🔗", "Advanced linkers", "x", "\\b(despite|although|even though|whereas|however|nevertheless|moreover|furthermore|provided that|unless|so as to|in order to)\\b"], ["🔀", "Conditional", "x", "\\bif\\b"], ["🔍", "Modal perfect", "x", "\\b(must|might|may|could|can't|should|would)\\s+have\\s+\\w+"], ["⏪", "Perfect tenses", "x", "\\b(had|will have|'ll have|have|has)\\s+been\\s+\\w+ing\\b|\\bwill have\\s+\\w+"], ["💬", "At least 70 words", "len70"]]}]}, "cert": "B2 – Upper-Intermediate Level", "home": "<span dir=\"rtl\" style=\"display:block\">مستوى <bdi dir=\"ltr\">B2</bdi> — اتكلم عن الجريمة والشهرة والتطوع والمغامرة ولغة الجسد والنوم والضغط النفسي، ومعاهم Idioms وPhrasal Verbs وSlang وقصص مع Wisy.</span>", "sub": "Upper-Intermediate", "spr": 60, "ch": "img/char-wisy.png"};
